        foreach ($mm as $m) { $tn++; $v = is_array($jr) ? ($jr["cih"][$m[1] . "|"] ?? null) : null; if ($v !== null && abs((float)$num($m[2]) - (float)$v) <= 0.005) $tf++; }
        $pm = ["Fiber & Starlink" => "dishnet", "DishNet 4G" => "4g", "BlueCARD" => "bluecard"];
