        foreach ($mm as $m) { $tn++; $v = is_array($jr) ? ($jr["cih"][$m[2] . "|" . $pm[$m[1]]] ?? null) : null; if ($v !== null && abs((float)$num($m[3]) - (float)$v) <= 0.005) $tf++; }
        $tool = " tool=ran toolro=$ro toolbanner=$bv toolrule=$ru toolfig=$tf/$tn";
