# QN1_PHP — Q-N1, the configuration that bears on the check, READ-ONLY as the database's owner, as ucc_state reads it: the
# configuration files as the installed plugin reads them (the vault filling only what is missing) and the store row —
# set or unset, on or off, equal or differs; the host of crm_base_url against the plugin's own uCRM host; the quotation's
# two e-mail paths; and (5.18.102, QL-N6) the three keys its Uganda quotations read — the customer's notes and P3. Never
# a value. Prints one line.
QN1_PHP="$(cat <<'PHP'
[$code, $inst, $pdd, $qorg] = array_slice($argv, 1, 4) + [null, "", "", "", ""];
try {
    ini_set("error_log", "/dev/null");
    require_once $code . "/lib/ConfigVault.php";
    putenv("DN_VAULT_FILE=" . ConfigVault::path($inst, $pdd));   // the vault the installed plugin reads, read-only (fill)
    require_once $code . "/lib/PluginConfig.php"; require_once $code . "/lib/CrmApiClient.php";
    $f = PluginConfig::read($inst, $pdd);
    $p = new PDO("sqlite:" . rtrim($pdd, "/") . "/plugin.sqlite3", null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_TIMEOUT => 15, PDO::SQLITE_ATTR_OPEN_FLAGS => PDO::SQLITE_OPEN_READONLY]);
    $row = $p->query("SELECT data FROM kyc_config WHERE id = 0 LIMIT 1")->fetchColumn(); $p = null;
    $s = is_string($row) ? (json_decode($row, true) ?: []) : [];
    $str = function (array $c, string $k): string { $v = $c[$k] ?? null; return is_scalar($v) ? trim((string)$v) : ""; };
    $set = function (array $c, string $k) use ($str): string { return $str($c, $k) === "" ? "unset" : "set"; };
    $on = function (array $c, string $k): string { $v = $c[$k] ?? null; if (is_bool($v)) return $v ? "on" : "off"; return in_array(strtolower(trim(is_scalar($v) ? (string)$v : "")), ["1", "true", "on", "yes"], true) ? "on" : "off"; };
    $m = (int)$qorg;
    $lead = function (array $c) use ($str, $m): string { $v = $str($c, "ucrm_lead_organization_id"); if ($v === "") return "unset"; if (!preg_match('/^[0-9]{1,9}$/', $v)) return "invalid"; return (int)$v === $m ? "equal" : "differs"; };
    $plugHost = strtolower((string)parse_url(CrmApiClient::fromUcrm($inst, [])->getBaseUrl(), PHP_URL_HOST));
    $url = function (array $c) use ($str, $plugHost): string { $v = $str($c, "crm_base_url"); if ($v === "") return "unset"; $h = strtolower((string)parse_url($v, PHP_URL_HOST)); return ($h !== "" && $h === $plugHost) ? "same-host" : "other-host"; };
    $two = function (callable $fn, string $k = "") use ($f, $s): string { return $k === "" ? $fn($f) . "/" . $fn($s) : $fn($f, $k) . "/" . $fn($s, $k); };
    $es = json_decode((string)@file_get_contents(rtrim($pdd, "/") . "/email_settings.json"), true);
    $via = is_array($es) ? (!empty($es["quote_email_via_plugin"]) ? "on" : "off") : "nofile";
    $qmail = "?";
    if (is_file($code . "/lib/CustomerEmailDispatcher.php")) {
        try {
            foreach (["CustomerEmails", "CustomerEmailDispatcher"] as $l) if (is_file($code . "/lib/$l.php")) require_once $code . "/lib/$l.php";
            $qmail = (CustomerEmailDispatcher::enabled("quotation", $f) ? "on" : "off") . "/" . (CustomerEmailDispatcher::enabled("quotation", $s) ? "on" : "off");
        } catch (Throwable $e) { $qmail = "?"; }
    }
    echo "lead=", $two($lead), " lsync=", $two($on, "ai_crm_lead_sync"), " token=", $two($set, "crm_auth_token"), " url=", $two($url),
         " qcname=", $two($set, "quote_company_name"), " qcphone=", $two($set, "quote_company_phone"), " qcemail=", $two($set, "quote_company_email"),
         " qvia=", $via, " qmail=", $qmail, " qkey=", $two(function (array $c) use ($str): string { return $str($c, "ucrm_quote_organization_id") === "" ? "unset" : "set"; }),
         // QL-N6: kyc_quote_notes_prefix set or unset (never its text); kyc_auto_quote_enabled on unless it is false
         // (KycService's own rule); kyc_auto_quote_max_amount set when above 0 (quoteOverAutoMax's own rule)
         " qln6=prefix:", $two($set, "kyc_quote_notes_prefix"), ",auto:", $two(function (array $c): string { return (($c["kyc_auto_quote_enabled"] ?? true) !== false) ? "on" : "off"; }),
         ",max:", $two(function (array $c): string { $v = $c["kyc_auto_quote_max_amount"] ?? 0; return (is_scalar($v) && (float)$v > 0) ? "set" : "unset"; });
} catch (Throwable $e) { echo "?", get_class($e); }
PHP
)"
# RBQ_PHP — after a rollback (RB) and in stage A of one: 5.18.99's quoting records (5.18.100 and 5.18.101 write none of
# their own), READ-ONLY as the database's owner — applications with quote_refused, leads flagged quote_org_missing, and
# whether ucrm_quote_organization_id is set in the configuration file and in the store row — and, since 5.18.103 (docs/72
# §G.10, §G.13), "qcrb2", the web-direct applications with no quotation made, by sync status — a record: 5.18.103, the
# rollback target, handles them exactly as 5.18.104 does (their ids to the ids file, its optional second argument under
# /tmp, for the sheet), and "qcrb1t", the uCRM
# catalogue's table a rollback leaves — absent, or its records — read through this read-only connection, never load(),
# which would create it. Counts and set/unset only on stdout. Its first argument is the data folder: the live one, opened
# read-only (RB), or a folder holding a consistent copy (qcrb_count). (5.18.102's own counts — qlunp, ql102, qlrb3,
# qlunconf — guarded a rollback to 5.18.101 and are retired with it.)
RBQ_PHP="$(cat <<'PHP'
[$pdd] = array_slice($argv, 1, 1) + [""];
$db = rtrim((string)$pdd, "/") . "/plugin.sqlite3";
if (!is_file($db)) { echo "nodb"; exit; }
try {
    $p = new PDO("sqlite:" . $db, null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_TIMEOUT => 15, PDO::SQLITE_ATTR_OPEN_FLAGS => PDO::SQLITE_OPEN_READONLY]);
    $has = function (string $t) use ($p): bool {
        if ($p->query("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = " . $p->quote($t))->fetchColumn() === false) return false;
        foreach ($p->query("PRAGMA table_info([" . $t . "])")->fetchAll(PDO::FETCH_ASSOC) as $c) if ((string)$c["name"] === "data") return true;
        return false;
    };
    $n = function (string $sql) use ($p): int { return (int)$p->query($sql)->fetchColumn(); };
    $ref = $has("kyc_applications") ? $n("SELECT COUNT(*) FROM kyc_applications WHERE json_extract(data, '$.quote_refused') IS NOT NULL AND json_extract(data, '$.quote_refused') <> ''") : -1;
    $mis = $has("leads") ? $n("SELECT COUNT(*) FROM leads WHERE json_extract(data, '$.crm_sync_flag') = 'quote_org_missing'") : -1;
    // 5.18.103 (docs/72 §G.10, §G.13; QC-RB2): the web-direct applications with no quotation made, by sync status —
    // counted for the record: 5.18.103, the rollback target, retries and quotes each exactly as 5.18.104 does (the same
    // KycService and UcrmQuoteLines). Their ids go to the ids file (the second argument, under /tmp) for the sheet, never
    // to stdout.
    $ql = " qcrb2=?";
    if ($has("kyc_applications")) {
        $dw = "json_extract(data, '$.quote_sale_entry') = 'web-direct' AND COALESCE(json_extract(data, '$.quote_created'), 0) IN (0, '', '0')";
        $dn = $n("SELECT COUNT(*) FROM kyc_applications WHERE json_extract(data, '$.quote_sale_entry') = 'web-direct'");
        $dq = $n("SELECT COUNT(*) FROM kyc_applications WHERE " . $dw);
        $by = []; foreach (["pending", "review", "failed", "synced"] as $st) $by[$st] = $n("SELECT COUNT(*) FROM kyc_applications WHERE " . $dw . " AND json_extract(data, '$.crm_sync_status') = '" . $st . "'");
        $ql = " qcrb2=direct:" . $dn . ",unquoted:" . $dq . ",pending:" . $by["pending"] . ",review:" . $by["review"] . ",failed:" . $by["failed"] . ",synced:" . $by["synced"];
        $idf = (string)($argv[2] ?? "");
        if ($idf !== "" && strpos($idf, "/tmp/") === 0) {
            $ids = array_map("intval", $p->query("SELECT json_extract(data, '$.id') FROM kyc_applications WHERE " . $dw . " ORDER BY json_extract(data, '$.id')")->fetchAll(PDO::FETCH_COLUMN));
            if (@file_put_contents($idf, ($ids ? "#" . implode(", #", $ids) : "none") . "\n") === false) $ql .= "/?ids"; else @chmod($idf, 0600);
        }
    }
    $row = $p->query("SELECT data FROM kyc_config WHERE id = 0 LIMIT 1")->fetchColumn();
    $s = is_string($row) ? (json_decode($row, true) ?: []) : [];
    $v = $s["ucrm_quote_organization_id"] ?? null;
    $kf = json_decode((string)@file_get_contents(rtrim((string)$pdd, "/") . "/kyc_config.json"), true); $w = is_array($kf) ? ($kf["ucrm_quote_organization_id"] ?? null) : null;
    $u = function ($x): string { return ($x === null || (is_scalar($x) && trim((string)$x) === "")) ? "unset" : "set"; };
    // QC-RB1 (5.18.103): the uCRM catalogue's table a rollback leaves — absent, or its records — read through this
    // read-only connection, never load(), which would create it; its own "?" when it cannot be read
    try {
        $ct = $p->query("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'ucrm_catalogue'")->fetchColumn() !== false;
        $q3 = " qcrb1t=" . (!$ct ? "absent" : ($has("ucrm_catalogue") ? "records:" . $n("SELECT COUNT(*) FROM ucrm_catalogue") : "?"));
    } catch (Throwable $e) { $q3 = " qcrb1t=?"; }
    echo "refused=", $ref < 0 ? "?" : $ref, " orgmissing=", $mis < 0 ? "?" : $mis, " key=", $u($w), "/", $u($v), $ql, $q3;
} catch (Throwable $e) { echo "?"; }
PHP
)"
qn1_state() { [ -n "$DB_OWNER" ] || { echo "?noowner"; return; }; docker exec -u "$DB_OWNER" "$CONTAINER" php -d display_errors=stderr -r "$QN1_PHP" "$1" "$IN_CONTAINER" "$PDD_IN" "${2:-0}" 2>/dev/null </dev/null || echo "?"; }   # qn1_state CODE_ROOT QORG
rbq_state() { [ -n "$DB_OWNER" ] || { echo "?noowner"; return; }; docker exec -u "$DB_OWNER" "$CONTAINER" php -d display_errors=stderr -r "$RBQ_PHP" "${1:-$PDD_IN}" "${2:-}" 2>/dev/null </dev/null || echo "?"; }   # rbq_state [DATA_FOLDER] — the live one by default (RB)
# qcrb_count [WHEN] — QC-RB2, 5.18.103 (docs/72 §G.10, §G.13), carried: the web-direct applications with no quotation
# made, counted for the record — the rollback changes none of them: 5.18.103 handles each exactly as 5.18.104 does —
# READ-ONLY on a consistent copy of the book — VACUUM INTO as the database's owner (CIHV_PHP, the
# backup's own way: its settings row cut to the book's keys), in a folder of mode 700 of this run's own in the container's
# /tmp, removed at once (and by the trap, chk_cleanup) — through RBQ_PHP. Sets QC_RB ("direct:<n>,unquoted:<n>,pending:<n>,
# review:<n>,failed:<n>,synced:<n>") and puts their ids on the run's sheet under WHEN — opening it when none is open yet,
# as in a --rollback's stage A — saying where they went in QC_RB_IDS; or sets QC_RB_ERR. A note, never a
# refusal: going back to 5.18.103 quotes nothing at price 0 (docs/72 §G.8). Never an id, a name or an amount in the log.
QC_RB=""; QC_RB_ERR=""; QC_RB_IDS=""
qcrb_count() {
  local d size free o when="${1:-}"
  QC_RB=""; QC_RB_ERR=""; QC_RB_IDS="ids not kept: the sheet could not be made"
  [ -n "$DB_OWNER" ] || { QC_RB_ERR="no owner of plugin.sqlite3 was found"; return 1; }
  size="$(db_state | sed -nE 's/^size=([0-9]+) .*/\1/p')"; free="$(dxo php -r 'echo (int)@disk_free_space($argv[1]);' /tmp)"
  case "$size" in ''|*[!0-9]*) QC_RB_ERR="the book's size could not be read"; return 1 ;; esac
  case "$free" in ''|*[!0-9]*) QC_RB_ERR="the space free in the container's /tmp could not be read"; return 1 ;; esac
  [ "$free" -ge $(( size + 67108864 )) ] || { QC_RB_ERR="the container's /tmp has $free bytes free; a copy of the book and its margin need $(( size + 67108864 ))"; return 1; }
  d="/tmp/dnb-$EXPECTED_VERSION-qcrb-$TS-$$-$RANDOM"
  dxo mkdir -m 700 "$d" || { QC_RB_ERR="a folder of its own could not be made in the container's /tmp"; return 1; }
  o="$(dxo php -d display_errors=stderr -r "$CIHV_PHP" "$PDD_IN/plugin.sqlite3" "$d/plugin.sqlite3" "$BOOK_KEYS_CSV")"
  case "$o" in "copy=ok "*" side=no") ;; *) cih_drop "$d"; QC_RB_ERR="the consistent copy could not be made (${o:-?})"; return 1 ;; esac
  o="$(rbq_state "$d" "$d/qcrb-ids.txt")"
  if sheet_open; then { printf '\n== QC-RB2 the web-direct applications with no quotation — %s (application ids: never paste) ==\n  ' "${when:-counted on a copy}"; dxo cat "$d/qcrb-ids.txt" || echo "(not read)"; } >> "$SHEET" 2>/dev/null && QC_RB_IDS="ids on the sheet"; fi
  cih_drop "$d"
  QC_RB="$(kv "$o" qcrb2)"
  case "$QC_RB" in direct:[0-9]*,unquoted:[0-9]*,pending:[0-9]*,review:[0-9]*,failed:[0-9]*,synced:[0-9]*) return 0 ;; esac
  QC_RB_ERR="the copy could not be counted (${o:-?})"; QC_RB=""
  return 1
}
qcrb_say() { printf '%s web-direct application(s), %s with no quotation made (pending for uCRM %s, in review %s, failed %s, in uCRM with no quotation %s)' "$(subkv "$1" direct)" "$(subkv "$1" unquoted)" "$(subkv "$1" pending)" "$(subkv "$1" review)" "$(subkv "$1" failed)" "$(subkv "$1" synced)"; }
# Every request this run made of uCRM, by method, summed over its probes (each probe counts its own, through its GET-only
# wrapper): QO_OTHER must be 0 at the end — nothing created, changed or deleted in uCRM.
QO_GETS=0; QO_OTHER=0; QO_COUNT_BAD=""
qo_count() {   # qo_count PROBE-LINE WHICH
  local g o; g="$(kv "$1" gets)"; o="$(kv "$1" other)"
  case "$g" in ''|*[!0-9]*) QO_COUNT_BAD="$QO_COUNT_BAD ${2:-?}"; return 0 ;; esac
  case "$o" in ''|*[!0-9]*) QO_COUNT_BAD="$QO_COUNT_BAD ${2:-?}"; return 0 ;; esac
  QO_GETS=$((QO_GETS + g)); QO_OTHER=$((QO_OTHER + o))
}
qo_set_of() { local s; s="$(kv "$1" setting)"; printf '%s' "${s%%/*}"; }        # the configuration files' answer: on|off:<id>|-:<source>:<error>|-
qo_row_of() { local s; s="$(kv "$1" setting)"; case "$s" in */*) printf '%s' "${s#*/}" ;; esac; }   # the store row's
qo_org() { local s; s="$(qo_set_of "$1")"; case "$s" in on:[0-9]*:*:-) s="${s#on:}"; printf '%s' "${s%%:*}" ;; esac; }   # the quoting organization's id, when it is in force
qo_src() { case "$(qo_set_of "$1")" in *:profile:-) echo "from the Uganda profile" ;; *:setting:-) echo "from the setting ucrm_quote_organization_id" ;; *) echo "?" ;; esac; }
# qo_gate_state GATE-LINE / qo_gate_a — 5.18.102 (E2-2, L2, review 2): a gate reading in one word, so that a reading
# that was never made cannot read as "off" — on:<id> (the quoting organization in force, the files and the store row
# alike), off (0/off, or not Uganda: the files and the store row alike), other (read, and neither: invalid, or the two
# copies disagree), unread (no reading: the probe was not run, or answered no setting); qo_gate_a says stage A's Q-G3
# (QG3_A, a bare setting, the same in both copies or stage A stopped) the same way, unknown when it is not known.
qo_gate_state() {   # qo_gate_state GATE-LINE
  local s r; s="$(qo_set_of "$1")"; r="$(qo_row_of "$1")"
  case "$s" in
    ''|'?'*) echo unread ;;
    on:[0-9]*:*:-) [ "$s" = "$r" ] && echo "on:$(qo_org "$1")" || echo other ;;
    off:-:*:-) [ "$s" = "$r" ] && echo off || echo other ;;
    *) echo other ;;
  esac
}
qo_gate_a() {   # qo_gate_a — QG3_A in qo_gate_state's words: on:<id>, off, other, or unknown
  local x
  case "${QG3_A:-}" in
    '') echo unknown ;;
    on:[0-9]*:*:-) x="${QG3_A#on:}"; echo "on:${x%%:*}" ;;
    off:-:*:-) echo off ;;
    *) echo other ;;
  esac
}
# with_flags EXTRA — the deploy as this run was asked, with EXTRA added, one command on its own line, its own log: what a
# refusal that an explicit flag would lift prints, so that a second refusal never drops the first one's flag. 5.18.102:
# --accept-unpriced (QL-G1) among them, carried as --quote-create-unproven is.
with_flags() {   # the move-list run (--move-list-only) gets its own command back, with --quote-company-off alone
  local f="" x w
  if [ "$MODE" = "movelist" ]; then
    for x in --move-list-only ${QOFF:+--quote-company-off} "$1"; do case " $f " in *" $x "*) ;; *) f="$f $x" ;; esac; done
    w="movelist"
  else
    for x in ${REDEPLOY:+--redeploy} ${WITHOUT_BANK:+--without-bank-balance} ${QOFF:+--quote-company-off} ${QUNPROVEN:+--quote-create-unproven} ${LEADDIFF:+--lead-org-differs} ${ACCEPT_UNPRICED:+--accept-unpriced} "$1"; do
      case " $f " in *" $x "*) ;; *) f="$f $x" ;; esac
    done
    w="$( [ -n "$REDEPLOY" ] && echo redeploy || echo deploy)"
  fi
  printf 'cd %s && bash scripts/deploy-%s.sh%s %s' "$REPO" "$EXPECTED_VERSION" "$f" "$(LOGW "$w")"
}
# qo_gate SUB ROOT NAME OVERRIDE — the gate probe, through ROOT copied once more for it, on a copy of SUB's master of its
# own, with the reading's vault copy (DN_VAULT_FILE) — one PHP process, so that TenantProfile's memo is its own. Prints
# its line (or ?…). Every copy is removed before it returns.
qo_gate() {
  local sub="$1" root="$2" nm="$3" ov="${4:-}" o
  cih_root "$root" "$sub/g-$nm/$PLUGIN" "$sub/conf" || { cih_drop "$sub/g-$nm"; printf '?copy'; return 0; }
  cih_data "$sub/master" "$sub/conf" "$sub/g-$nm-data" || { cih_drop "$sub/g-$nm"; cih_drop "$sub/g-$nm-data"; printf '?data'; return 0; }
  dxo sh -c '[ ! -f "$1" ] || cp "$1" "$2"' _ "$sub/qo-vault.json" "$sub/g-$nm-vault.json"
  o="$(docker exec -u "$DB_OWNER" -e DN_VAULT_FILE="$sub/g-$nm-vault.json" -e DN_DATA_DIR="$sub/g-$nm-data" "$CONTAINER" php -d display_errors=stderr -r "$QO_PHP" gate "$sub/g-$nm/$PLUGIN" "data=$sub/g-$nm-data" "row=$sub/conf/row.json" "override=$ov" "elog=$sub/g-$nm-data/php_error.log" 2>/dev/null </dev/null)"
  cih_drop "$sub/g-$nm-data"; cih_drop "$sub/g-$nm"; dxo rm -f "$sub/g-$nm-vault.json" >/dev/null 2>&1 || true
  printf '%s' "${o:-?}"
}
# qo_hlines TAG HEAD — a reading's hash file (stdin: "HEAD <n>", then n lines "TAG <32 hex> <value>") as one value for
# the shell: "<H>:<value>,…" (items: "<H(item)>:<H(verdict)>"; records: "<H(id)>:a|e"), none when it counts 0, or "?<why>"
# — the file's own ?word (?nokey, ?off, ?skipped, ?nolinks), ?none (no file), ?head, ?line or ?count. 5.18.102 (D14
# §R.7.2, derivation M-1): in memory only, never printed; awk without interval expressions, which the host's may lack.
qo_hlines() {
  awk -v t="$1" -v h="$2" '
    NR == 1 { if (substr($0, 1, 1) == "?") { print $1; bad = 1; exit } if (NF != 2 || $1 != h || $2 !~ /^[0-9]+$/) { print "?head"; bad = 1; exit } n = $2 + 0; next }
    { if (NF != 3 || $1 != t || length($2) != 32 || $2 !~ /^[0-9a-f]+$/ || (t == "i" && (length($3) != 32 || $3 !~ /^[0-9a-f]+$/)) || (t == "r" && $3 != "a" && $3 != "e")) { print "?line"; bad = 1; exit }
      s = s (c++ ? "," : "") $2 ":" $3 }
    END { if (bad) exit; if (NR == 0) { print "?none"; exit } if (c != n) { print "?count"; exit } print (c ? s : "none") }'
}
# qo_run a|m|r INST_ROOT [PIN_ROOT] — the quoting checks' one reading. Its own folder in this run's folder in the container's
# /tmp (mode 700), with the quoting keys' copies of the three settings files, of the vault and of the store row, and a
# consistent copy of the book (VACUUM INTO, as the database's owner, as every reading here): the gate through the
# INSTALLED code (Q-G2; after the copy Q-CA2 and its two controls, each in its own process) and, before the copy, through
# the PIN's (Q-G3); the local counts through the installed code (Q-G5, Q-N2's ids, Q-N4–Q-N7); and uCRM, GET-only, through
# the pin's code before the copy (a: Q-G4, Q-G4b, Q-N2, Q-N3; m, the move-list run: Q-G4 and Q-N2) and through the
# installed code after it (r: Q-CA3, the organizations and the newest quote again). Sets QO_G2, QO_G3, QO_C0, QO_C1,
# QO_L, QO_R, QO_TOK, QO_ORGS (the organizations' lines, Q-G4's to print), QO_PICK_IN, QO_PICK_OUT and QO_PICK_OUTORG
# (two client ids, kept for Q-CA3 — never printed), QO_SINK (the refusal lines the probe's own sink took), QO_LOGHIT
# and QO_LOGSTAFF (r: the live data/plugin.log's lines written while the probe ran — labelled this run's, which only this
# run writes; unlabelled and naming a probed client, which only staff write), QO_CPROBE (r: the probe's refusal lines and
# its control's in its own code copy's data/plugin.log, then in its PHP error log), QO_SINCE (Q-N3's window), QO_AT, or
# QO_ERR; the counts and the client ids go to the run's sheet. Every copy — the token's first — is removed before it
# returns; the run's folder again by the trap. 5.18.102: local also writes the offer and q314 files (the rows the KYC
# form offers; quotation 000314's quote id), which remote reads — at stage A resolving the rows through the PIN's code
# (QL-G1, QL-N7), reading the salesPerson attribute (QL-N1; after the copy QL-CA2) and quotation 000314 (QL-N2) — the
# names to the sheet with the rest. 5.18.102 D14 (§R.7.1): stage A's local reading loads the RELEASE's
# lib/UcrmQuoteLinks.php by its own path — the pin's from Git (PIN_ROOT), never the root it copies — and reads the link
# store on the copy; after the copy no link is read (QL-CA1 and QL-LK1 are retired since 5.18.103, docs/72 §G.13).
# 5.18.103: local also reads the uCRM catalogue's settings on the copy through the RELEASE's lib/UcrmCatalogue.php by
# its own path (a: the pin's from Git; r: the installed root's own copy), the applications by entry, the stock
# categories' titles and public_price_exclude (to the offer file); remote reads what the forms offer through that
# code's offered() (QC-G1 at stage A, QC-CA1 after the copy). The readings key their hashes with the QL key (QL_KEY,
# salt=), never MAP_SALT. Sets QO_QCI (each direct item's keyed hash with its verdict's, "<H>:<H>,…", or none), read
# from its 0600 file in this reading's folder before the folder goes, in memory only, never printed (qo_hlines;
# "?<why>" when the file is not as written) — and QO_KIND, the kind of reading QO_L and QO_R now hold.
QO_G2=""; QO_G3=""; QO_C0=""; QO_C1=""; QO_L=""; QO_R=""; QO_TOK=""; QO_ORGS=""; QO_PICK_IN=""; QO_PICK_OUT=""; QO_PICK_OUTORG=""; QO_SINK=""; QO_LOGHIT=""; QO_LOGSTAFF=""; QO_CPROBE=""; QO_SINCE=""; QO_AT=""; QO_ERR=""; QO_LABEL=""
QO_A_IN=""; QO_A_OUT=""; QO_A_OUTORG=""
QO_QCI=""; QO_KIND=""   # 5.18.103: the direct catalogue's items' keyed hashes (never printed), and which reading QO_R is (5.18.102's QO_QLI, QO_QLREC and QO_APPMAX went with QL-CA1 and QL-LK1)
QO_GATE_R=""; QO_GATE_A=""   # 5.18.102: the quoting organization after the copy and at stage A, one word each (qo_after; for F)
qo_run() {
  local kind="$1" inst="$2" pin="${3:-}" sub o size free need qorg what code plog n0 n1 cin cout since lg lids x
  local -a la
  QO_G2=""; QO_G3=""; QO_C0=""; QO_C1=""; QO_L=""; QO_R=""; QO_TOK=""; QO_ORGS=""; QO_PICK_IN=""; QO_PICK_OUT=""; QO_PICK_OUTORG=""; QO_SINK=""; QO_LOGHIT=""; QO_LOGSTAFF=""; QO_CPROBE=""; QO_SINCE=""; QO_AT=""; QO_ERR=""
  QO_QCI=""; QO_KIND="$kind"
  [ -n "$SHEET" ] || { QO_ERR="the run's sheet is not open"; return 1; }
  cih_init || { QO_ERR="the run's folder in the container's /tmp, or its copy of the vault, could not be made (${CIH_VAULT_SAYS:-?})"; return 1; }
  size="$(db_state | sed -nE 's/^size=([0-9]+) .*/\1/p')"; free="$(dxo php -r 'echo (int)@disk_free_space($argv[1]);' /tmp)"
  case "$size" in ''|*[!0-9]*) QO_ERR="the book's size could not be read"; return 1 ;; esac
  case "$free" in ''|*[!0-9]*) QO_ERR="the space free in the container's /tmp could not be read"; return 1 ;; esac
  need=$(( size * 3 + 67108864 ))
  [ "$free" -ge "$need" ] || { QO_ERR="the container's /tmp has $free bytes free; two copies of the book and their margin need $need"; return 1; }
  CIH_N=$((CIH_N + 1)); sub="$CIH_BASE/qo-$kind-$CIH_N"
  dxo mkdir -m 700 "$sub" "$sub/conf" "$sub/master" "$sub/tok" || { QO_ERR="this reading's folder could not be made"; return 1; }
  o="$(dxo php -d display_errors=stderr -r "$QOP_PHP" conf "$IN_CONTAINER" "$PDD_IN" none "$sub/conf")"
  case "$o" in root=*) ;; *) QO_ERR="the settings files could not be copied (${o:-?})"; cih_drop "$sub"; return 1 ;; esac
  o="$(dxo php -d display_errors=stderr -r "$QOP_PHP" vault "$IN_CONTAINER" "$PDD_IN" "$VAULT_IN" "$sub")"
  case "$o" in vault=*) ;; *) QO_ERR="the vault's quoting keys could not be copied (${o:-?})"; cih_drop "$sub"; return 1 ;; esac
  o="$(dxo php -d display_errors=stderr -r "$QOP_PHP" row "$IN_CONTAINER" "$PDD_IN" none "$sub/conf")"
  case "$o" in row=*) ;; *) QO_ERR="the store row's quoting keys could not be read (${o:-?})"; cih_drop "$sub"; return 1 ;; esac
  QO_AT="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  o="$(dxo php -d display_errors=stderr -r "$CIHV_PHP" "$PDD_IN/plugin.sqlite3" "$sub/master/plugin.sqlite3" "$BOOK_KEYS_CSV")"
  case "$o" in "copy=ok "*" side=no") ;; *) QO_ERR="the consistent copy could not be made (${o:-?})"; cih_drop "$sub"; return 1 ;; esac
  QO_G2="$(qo_gate "$sub" "$inst" i "")"
  [ -z "$pin" ] || QO_G3="$(qo_gate "$sub" "$pin" p "")"
  if [ "$kind" = "r" ]; then QO_C0="$(qo_gate "$sub" "$inst" c0 "tenant_profile=south-sudan")"; QO_C1="$(qo_gate "$sub" "$inst" c1 "ucrm_quote_organization_id=0")"; fi
  qorg="$(qo_org "$( [ "$kind" = "r" ] && printf '%s' "$QO_G2" || printf '%s' "$QO_G3" )")"
  if ! { cih_root "$inst" "$sub/l/$PLUGIN" "$sub/conf" && cih_data "$sub/master" "$sub/conf" "$sub/l-data"; }; then QO_ERR="the local reading's copies could not be made"; cih_drop "$sub"; return 1; fi
  # 5.18.102 D14 (§R.7.1, §R.7.7 item 2; derivation M-1, M-6): the local reading's link arguments. a: the PIN's
  # lib/UcrmQuoteLinks.php from Git, by its own path (never ICODE_A's root, copied above), and the QL key (QL-G1); r and
  # m: no link reading at all — since 5.18.103 QL-CA1 and QL-LK1 are retired (docs/72 §G.13). 5.18.103: the RELEASE's
  # lib/UcrmCatalogue.php by its own path (cat=) — a: the pin's from Git; r: the installed root's own copy — for the
  # catalogue settings on the copy (QC).
  la=("qorg=${qorg:-0}")
  case "$kind" in
    a) la+=("links=$pin/lib/UcrmQuoteLinks.php" "salt=$QL_KEY" "cat=$pin/lib/UcrmCatalogue.php") ;;
    r) la+=("salt=$QL_KEY" "cat=$sub/l/$PLUGIN/lib/UcrmCatalogue.php") ;;
  esac
  dxo sh -c '[ ! -f "$1" ] || cp "$1" "$2"' _ "$sub/qo-vault.json" "$sub/l-vault.json"
  QO_L="$(docker exec -u "$DB_OWNER" -e DN_VAULT_FILE="$sub/l-vault.json" -e DN_DATA_DIR="$sub/l-data" "$CONTAINER" php -d display_errors=stderr -r "$QO_PHP" local "$sub/l/$PLUGIN" "data=$sub/l-data" "ids=$sub/ids.txt" "offer=$sub/offer.json" "q314=$sub/q314.txt" "out=$sub/local.txt" "${la[@]}" "label=${QO_LABEL:-the copy made at $QO_AT}" "elog=$sub/l-data/php_error.log" 2>/dev/null </dev/null)"
  cih_drop "$sub/l-data"; cih_drop "$sub/l"; dxo rm -f "$sub/l-vault.json" >/dev/null 2>&1 || true
  case "$QO_L" in "ids="*) ;; *) QO_ERR="the copy could not be read for the quoting checks (${QO_L:-?})"; QO_L=""; cih_drop "$sub"; return 1 ;; esac
  case "$kind" in a) what="orgs,token,clients,quotes,catalogue,attr,q314,qc"; code="$pin"; cin=0; cout=0 ;; m) what="orgs,clients"; code="$pin"; cin=0; cout=0 ;; *) what="orgs,token,check,quotes,attr,qc"; code="$inst"; cin="${QO_A_IN:-0}"; cout="${QO_A_OUT:-0}" ;; esac
  # 5.18.103 (docs/72 §G.13): after the copy the catalogue is QC-CA1's, through offered(); QL-CA1 and QL-LK1 are retired,
  # so the remote reading after the copy reads no link catalogue ("catalogue" and "lk" are no longer asked for)
  QO_TOK="token=unset"
  if [ "$kind" != "m" ]; then
    QO_TOK="$(dxo php -d display_errors=stderr -r "$QOP_PHP" token "$IN_CONTAINER" "$PDD_IN" none "$sub/tok")"
    case "$QO_TOK" in token=*) ;; *) QO_ERR="whether crm_auth_token is set could not be read (${QO_TOK:-?})"; cih_drop "$sub"; return 1 ;; esac
  fi
  if ! cih_root "$code" "$sub/u/$PLUGIN" "$sub/conf"; then QO_ERR="a code root could not be copied (uCRM's reading)"; cih_drop "$sub"; return 1; fi
  # Q-N3's window: stage A's own date — this run's stage A, or the deploy's state file — so that the newest quote is read
  # twice over the same window; a date of this run's own only where stage A's is not known (Q-CA3: then not comparable).
  since="$QN3_SINCE"; [ -n "$since" ] || since="$(date -u -d '-2 days' +%Y-%m-%d)"; QO_SINCE="$since"
  plog="$DEST/data/plugin.log"; n0="$(grep -c '' "$plog" 2>/dev/null || true)"; n0="${n0:-0}"
  QO_R="$(docker exec -u "$DB_OWNER" -e DN_VAULT_FILE="$sub/u-vault-none.json" -e DN_DATA_DIR="$sub/u-none" "$CONTAINER" php -d display_errors=stderr -r "$QO_PHP" remote "$sub/u/$PLUGIN" "ucrm=$IN_CONTAINER" "qorg=${qorg:-0}" "what=$what" "ids=$sub/ids.txt" "offer=$sub/offer.json" "q314=$sub/q314.txt" "qch=$sub/qch.txt" "salt=$QL_KEY" "out=$sub/remote.txt" "orgsout=$sub/orgs.txt" "pick=$sub/pick.txt" "token=$( [ "$QO_TOK" != "token=unset" ] && printf '%s' "$sub/tok/token.json" )" "sink=$sub/sink.txt" "elog=$sub/php_error.log" "budget=150" "since=$since" "cin=$cin" "cout=$cout" "label=${QO_LABEL:-the copy made at $QO_AT}" 2>/dev/null </dev/null)"
  dxo rm -rf "$sub/tok" >/dev/null 2>&1 || true   # the token's copy — the probe deleted it once read; whatever is left goes now
  qo_count "$QO_R" "$kind"
  if [ "$kind" = "r" ]; then   # Q-CA3: where the probe's refusal lines went, read on its own code copy before it goes — its
                               # data/plugin.log (PluginLog writes beside the code it loads) and its PHP error log, each as
                               # "<lines labelled (deploy-check)>:<lines labelled (deploy-check-control)>"
    QO_CPROBE="$(dxo sh -c 'for f in "$1" "$2"; do if [ -f "$f" ]; then printf "%s:%s " "$(grep -cF "(deploy-check)" "$f")" "$(grep -cF "(deploy-check-control)" "$f")"; else printf "0:0 "; fi; done' _ "$sub/u/$PLUGIN/data/plugin.log" "$sub/php_error.log")"
    QO_CPROBE="${QO_CPROBE% }"
  fi
  cih_drop "$sub/u"
  QO_ORGS="$(dxo cat "$sub/orgs.txt")"
  o="$(dxo cat "$sub/pick.txt")"; QO_PICK_IN="$(kv "$o" in)"; QO_PICK_OUT="$(kv "$o" out)"; QO_PICK_OUTORG="$(kv "$o" outorg)"
  QO_SINK="$(dxo sh -c 'if [ -f "$1" ]; then grep -c "" "$1"; else echo 0; fi' _ "$sub/sink.txt")"
  # 5.18.103 (docs/72 §G.13): the direct catalogue's items' keyed hashes (QC-G1 at stage A, QC-CA1 after the copy),
  # from their 0600 file in this reading's folder — in memory only, never printed; the file goes with the folder below
  QO_QCI="$(dxo sh -c 'if [ -f "$1" ]; then cat "$1"; fi' _ "$sub/qch.txt" | qo_hlines i items)"
  if [ "$kind" = "r" ]; then   # Q-CA3: what the live data/plugin.log gained while the probe ran — lines labelled this run's
                               # (deploy-check, deploy-check-control), which only this run writes; and lines naming a probed
                               # client, unlabelled, which only staff write (the probe cannot reach this file: it logs beside
                               # its own code copy)
    n1="$(grep -c '' "$plog" 2>/dev/null || true)"; n1="${n1:-0}"
    [ "$n1" -ge "$n0" ] || n0=0   # the log was cut while the probe ran: read all of it
    lg="$(tail -n "+$((n0 + 1))" "$plog" 2>/dev/null || true)"
    QO_LOGHIT="$(printf '%s\n' "$lg" | grep -cE '\(deploy-check(-control)?\)' || true)"; QO_LOGHIT="${QO_LOGHIT:-0}"
    lids=""; for x in "${QO_PICK_IN:-0}" "${QO_PICK_OUT:-0}"; do case "$x" in ''|0|*[!0-9]*) ;; *) lids="${lids:+$lids|}$x" ;; esac; done
    QO_LOGSTAFF=0
    if [ -n "$lids" ]; then QO_LOGSTAFF="$(printf '%s\n' "$lg" | grep -E "client #($lids) \(" | grep -vcE '\(deploy-check(-control)?\)' || true)"; QO_LOGSTAFF="${QO_LOGSTAFF:-0}"; fi
    lg=""
  fi
  if ! docker exec -u "$DB_OWNER" "$CONTAINER" sh -c 'cat "$1"; [ ! -f "$2" ] || cat "$2"' _ "$sub/local.txt" "$sub/remote.txt" >> "$SHEET" 2>/dev/null </dev/null; then QO_ERR="the quoting checks' lines could not be put on the sheet"; cih_drop "$sub"; return 1; fi
  cih_drop "$sub"
  case "$QO_R" in *" gets="*" other="*) ;; *) QO_ERR="uCRM could not be read for the quoting checks (${QO_R:-?})"; return 1 ;; esac
  return 0
}
# qn3_cmp NOW STAGE_A — the newest uCRM quote of one window, read twice (an id, or "none"): same | newer | notcomparable.
# A reading that has lost stage A's quote (none now, or a lower id) is not comparable — never staff quoting.
qn3_cmp() {
  local a="$1" b="$2"
  if [ "$a" = "$b" ]; then echo same; return; fi
  case "$a" in ''|*[!0-9]*) echo notcomparable; return ;; esac
  case "$b" in none) echo newer; return ;; ''|*[!0-9]*) echo notcomparable; return ;; esac
  if [ "$a" -gt "$b" ]; then echo newer; else echo notcomparable; fi
}
# Q-N2's line in words: "org #1: n · org #2: m · no organization: c · not found: j · unreadable: k", from the probe's list.
qn2_say() { printf '%s' "$1" | tr ',' '\n' | awk -F: '$1 ~ /^org[0-9]+$/ { printf "%sorg #%s: %s", (n++ ? " · " : ""), substr($1, 4), $2 } $1 == "none" { printf "%sno organization: %s", (n++ ? " · " : ""), $2 } $1 == "notfound" { printf "%snot found: %s", (n++ ? " · " : ""), $2 } $1 == "unreadable" { printf "%sunreadable: %s", (n++ ? " · " : ""), $2 } $1 == "unread" && $2 > 0 { printf "%snot read within the time budget: %s", (n++ ? " · " : ""), $2 } END { if (!n) printf "none read" }'; }
# qo_stage a|m INST_ROOT — stage A's quoting checks (a: a deploy and --check; m: --move-list-only): Q-G2–Q-G6 and the notes
# Q-N1–Q-N7 (m: Q-G2–Q-G4 and Q-N2), on copies and from uCRM with GETs only. A refusal stops, as every refusal of stage
# A does: nothing has changed. Sets QG3_A, QG4_A, QN3_A, QN3_SINCE (for the state file and Q-CA2, Q-CA3) and QO_A_IN,
# QO_A_OUT (two client ids for Q-CA3, never printed), and QOFF_NOTED, QG5_NOTED, QG6_NOTED only when a flag decided its
# check.
QG3_A=""; QG4_A=""; QN3_A=""; QOFF_NOTED=""; QG5_NOTED=""; QG6_NOTED=""; QN3_SINCE=""
qo_stage() {
  local kind="$1" inst="$2" vb s3 r3 qorg="" book ids has qcur tok dbg n5 s5 lf lr ln qn1 t q
  QO_LABEL="$( [ "$kind" = "m" ] && echo "the move-list run" || echo "stage A, before the deploy" ), the copy of $(date -u +%Y-%m-%dT%H:%M:%SZ)"
  vb="$(vt_now)"
  # Q-N3's window, fixed once, here: the quotes created since two days before stage A — Q-CA3 reads the same window again,
  # after the copy, from this value or the deploy's state file.
  [ "$kind" = "m" ] || QN3_SINCE="$(date -u -d '-2 days' +%Y-%m-%d)"
  qo_run "$kind" "$inst" "$P3B_PIN" || stop "NO-GO (Q-G): the quoting checks could not be read on a copy and from uCRM — $QO_ERR. Every copy is removed. Nothing was changed. Send the log file"
  vt_same "$vb" || stop "NO-GO (Q-G): the live vault (${VAULT_IN:-its path not known}) could not be shown unchanged while the quoting checks read their copies ($(vt_say "$vb") → $(vt_say "$(vt_now)")) — a run on a copy must never write it; a settings save at that moment is the other cause. Nothing was changed. Send the log file"
  echo "  quoting copy    made at $QO_AT — the quoting keys of the settings files, of the vault and of the store row, and the book's consistent copy"
  echo "  installed gate  $QO_G2   ($BASELINE_VERSION installed: the tenant, QuoteTaxLine and its QuoteOrganization — files/store row)"
  echo "  pin's gate      $QO_G3   ($EXPECTED_VERSION from Git — files/store row)"
  echo "  the copy        $QO_L"
  echo "  uCRM, GET-only  $QO_R"
  [ "$QO_OTHER" = "0" ] && [ -z "$QO_COUNT_BAD" ] || stop "NO-GO (Q-G4): the probe asked uCRM something other than a GET, or its count of requests could not be read (other $QO_OTHER;${QO_COUNT_BAD:- counted}) — the wrapper refused it before it reached uCRM; this run creates nothing there. Nothing was changed. Send the log file"
  # Q-G2 — the tenant, through the INSTALLED code on a copy.
  [ "$(kv "$QO_G2" tenant)|$(kv "$QO_G2" tax)" = "uganda/uganda|yes/yes" ] \
    || stop "NO-GO (Q-G2): this server is not the Uganda tenant as the installed $BASELINE_VERSION code reads it on a copy of its configuration (TenantProfile $(kv "$QO_G2" tenant), QuoteTaxLine::applies() $(kv "$QO_G2" tax); the configuration files / the store row) — $EXPECTED_VERSION's quoting organization is Uganda's alone, and this script is for the Uganda server. Nothing was changed. Send the log file"
  ok "Q-G2 the tenant is Uganda, through the INSTALLED $BASELINE_VERSION code on a copy of this server's configuration: TenantProfile::current() and QuoteTaxLine::applies(), over the configuration files and over the store row, each with the copy's vault ($(kv "$QO_G2" tenant), $(kv "$QO_G2" tax))"
  # Q-G3 — the effective quoting organization, through the RELEASE's QuoteOrganization::setting() on the same copy.
  s3="$(qo_set_of "$QO_G3")"; r3="$(qo_row_of "$QO_G3")"
  [ "$(kv "$QO_G3" tenant)" = "uganda/uganda" ] || stop "NO-GO (Q-G3): the pin's code does not read this server as the Uganda tenant ($(kv "$QO_G3" tenant); files/store row), where the installed code does (Q-G2). Nothing was changed. Send the log file"
  [ "$s3" = "$r3" ] || stop "NO-GO (Q-G3): the configuration files and the store row give the pin's QuoteOrganization::setting() different answers (files $s3; store row $r3) — the AI-lead worker reads the files, and the KYC form, Send Quotation and the debug retry the store row: they would file and quote under different companies. Nothing was changed. Send the log file"
  case "$s3" in
    on:[0-9]*:*:-) qorg="$(qo_org "$QO_G3")"
      ok "Q-G3 quoting organization #$qorg ($(qo_src "$QO_G3")), through the RELEASE's QuoteOrganization::setting() on the same copy — the configuration files and the store row alike ($s3)" ;;
    *:invalid) stop "NO-GO (Q-G3): ucrm_quote_organization_id is set on this server, and INVALID ($s3; files/store row) — every Uganda app quote is refused (R6) and no KYC customer filed (C2), under $BASELINE_VERSION as after the deploy. Correct it with tools/set_config.php (it lists the key), or remove it, in both copies, then run this again. Nothing was changed. Send the log file" ;;
    off:-:explicit-off:-)
      if [ -n "$QOFF" ]; then QOFF_NOTED=1
        note "Q-G3 --quote-company-off, the operator's explicit choice: ucrm_quote_organization_id is 0/off on this server ($s3) — $EXPECTED_VERSION then quotes as $BASELINE_VERSION does with it off: no quoting organization, no check before a quote, a new KYC customer filed by the old rule; push_products_to_ucrm stays admin-only"
      else stop "NO-GO (Q-G3): ucrm_quote_organization_id is 0/off on this server ($s3; files/store row) — $EXPECTED_VERSION would then quote as $BASELINE_VERSION does with it off, the old rule filing new KYC customers under the other company. Remove it with tools/set_config.php (it lists the key), in both copies, so that the Uganda profile's organization 1 applies; or, to deploy with it off — the operator's explicit choice, said as such in the log — its own command, alone:$(printf '\n      %s' "$(with_flags --quote-company-off)")"; fi ;;
    *) stop "NO-GO (Q-G3): the pin's QuoteOrganization::setting() reads $s3 on this server (files/store row) — on the Uganda tenant it must name the profile's organization or the setting's. Nothing was changed. Send the log file" ;;
  esac
  QG3_A="$s3"
  # Q-G4 — uCRM's organizations, GET-only, through the plugin's own client and the RELEASE's QuoteOrganization.
  case "$(kv "$QO_R" orgs)" in
    ok:*) ;;
    *) stop "NO-GO (Q-G4): uCRM's organizations could not be read through the plugin's own client, GET-only ($(kv "$QO_R" orgs)) — the KYC form reads them to file a new customer and the check before a quote to word its refusal. Nothing was changed. Send the log file" ;;
  esac
  ids="$(kv "$QO_R" orgids)"; has="$(kv "$QO_R" has)"; qcur="$(kv "$QO_R" qcur)"; book="$(kv "$QO_G3" book)"
  while IFS= read -r t; do [ -n "$t" ] && printf '  Q-G4            %s\n' "$t"; done <<< "$QO_ORGS"
  if [ -n "$qorg" ]; then
    [ "$has" = "yes" ] || stop "NO-GO (Q-G4): uCRM lists organization(s) $ids, and not the quoting organization #$qorg — after the deploy every Uganda app quote would be refused (R5) and no KYC customer filed (C1). Nothing was changed. Send the log file"
    case "$qcur" in
      none|-|'') note "Q-G4 currency not given by uCRM for the quoting organization #$qorg — the book's is $book" ;;
      "$book") ;;
      *) stop "NO-GO (Q-G4): the quoting organization #$qorg is a $qcur company in uCRM, and the book's currency is $book — a company in another currency would pass every other check. Nothing was changed. Send the log file" ;;
    esac
    ok "Q-G4 uCRM's organizations, read once through the plugin's own client (CrmApiClient::fromUcrm, the live ucrm.json read in place) wrapped GET-only, through the RELEASE's QuoteOrganization::organizations(): $ids — the quoting organization #$qorg among them$( [ "$qcur" = "$book" ] && echo ", in the book's currency ($book)")"
  else ok "Q-G4 uCRM's organizations, read once through the plugin's own client wrapped GET-only: $ids — no quoting organization is in force here (Q-G3), so none is looked for"; fi
  QG4_A="$ids"
  QO_A_IN="${QO_PICK_IN:-}"; QO_A_OUT="${QO_PICK_OUT:-}"; QO_A_OUTORG="${QO_PICK_OUTORG:-}"
  if [ "$kind" = "m" ]; then
    note "Q-N2 the app's uCRM clients — the distinct crm_client_id of kyc_applications, leads and quotes_log, read/all $(kv "$QO_L" ids | cut -d: -f1) (at most 300 read), one GET each: $(qn2_say "$(kv "$QO_R" qn2)") — the $(kv "$QO_R" outside) filed under another organization are on the sheet by id: the move-list for uCRM"
    return 0
  fi
  # Q-G4b — the token client, when crm_auth_token is set: the KYC path's and the debug retry's own.
  case "$QO_TOK" in
    token=unset) echo "  Q-G4b           crm_auth_token is unset in the store row the KYC path reads: the KYC form and the debug retry read with the plugin's own client, which Q-G4 read" ;;
    token=set*)
      tok="$(kv "$QO_R" token)"; dbg="$(kv "$QO_R" debug)"
      case "$tok" in read:*) ;; *) stop "NO-GO (Q-G4b): token client: ${tok#failed:} — the KYC form reads uCRM through the admin token (crm_auth_token) before every quote, and through it uCRM's organizations could not be read: after the deploy every KYC quote would be refused (R4/R7). Nothing was changed. Send the log file" ;; esac
      [ -z "$qorg" ] || [ "${tok##*:}" = "yes" ] || stop "NO-GO (Q-G4b): token client: organizations read, and the quoting organization #$qorg not among them — after the deploy every KYC quote would be refused (R5). Nothing was changed. Send the log file"
      case "$dbg" in
        same) ;;
        read:*) [ -z "$qorg" ] || [ "${dbg##*:}" = "yes" ] || stop "NO-GO (Q-G4b): the debug retry's token client: organizations read, and the quoting organization #$qorg not among them. Nothing was changed. Send the log file" ;;
        *) stop "NO-GO (Q-G4b): the debug retry's token client: ${dbg#failed:}. Nothing was changed. Send the log file" ;;
      esac
      t="${tok#read:}"; t="${t%%:*}"
      ok "Q-G4b token client: organizations read ($t) — crm_auth_token from the store row, built as KycService::postQuote builds it ($( [ "$(kv "$QO_TOK" url)" = "set" ] && echo "crm_base_url" || echo "the plugin's base URL"), x-auth-token), wrapped GET-only, its copy removed once read$( [ -n "$qorg" ] && echo "; the quoting organization #$qorg among them"); the debug retry's own client $( [ "$dbg" = "same" ] && echo "is that one here (the plugin's client has the same base URL)" || echo "read too ($dbg)")" ;;
    *) stop "NO-GO (Q-G4b): whether crm_auth_token is set could not be read ($QO_TOK). Nothing was changed. Send the log file" ;;
  esac
  # Q-G5 — evidence that Send Quotation's uCRM create works, from the copy of quotes_log.json.
  n5="$(kv "$QO_L" qg5)"; s5="${n5#*:}"; n5="${n5%%:*}"
  case "$n5$s5" in ''|*[!0-9]*) stop "NO-GO (Q-G5): the quotes log could not be counted on the copy ($(kv "$QO_L" qg5)). Nothing was changed. Send the log file" ;; esac
  if [ "$n5" = "0" ]; then note "Q-G5 INCONCLUSIVE: no Lead or Manual quote with a uCRM client in 30 days — whether Send Quotation's uCRM create works here is not shown; the first real quote after the deploy is the evidence"
  elif [ $((2 * s5)) -lt "$n5" ]; then
    if [ -n "$QUNPROVEN" ]; then QG5_NOTED=1
      note "Q-G5 --quote-create-unproven, the operator's explicit choice: of $n5 Lead or Manual quote(s) with a uCRM client in the last 30 days, $s5 have a uCRM quote — fewer than half. A uCRM create that fails on Send Quotation stops the quote with F7, under $BASELINE_VERSION as after the deploy"
    else stop "NO-GO (Q-G5): of $n5 Lead or Manual quote(s) with a uCRM client in the last 30 days, $s5 have a uCRM quote — most quotes with a uCRM client in the last 30 days have no uCRM quote. A row without one is an unticked box or a failed create, which the log cannot tell apart; item 7 stops such quotes with F7, under $BASELINE_VERSION as after the deploy. To deploy all the same — the operator's explicit choice, said as such in the log — its own command, alone:$(printf '\n      %s' "$(with_flags --quote-create-unproven)")"; fi
  else ok "Q-G5 the last 30 days' Lead and Manual quotes with a uCRM client: $n5, $s5 of them with a uCRM quote — at least half (N − S, $((n5 - s5)), bounds the failed creates from above: an unticked box is not told apart)"; fi
  # Q-G6 — the lead organization against the quoting organization.
  lf="$(kv "$QO_G3" lead)"; lr="${lf#*/}"; lf="${lf%%/*}"
  if [ -z "$qorg" ]; then echo "  Q-G6            not asked: no quoting organization is in force (Q-G3)"
  else
    ln=""; for t in "$lf" "$lr"; do case "$t" in -|"$qorg") ;; *) ln="$ln $t" ;; esac; done
    if [ -z "$ln" ]; then ok "Q-G6 ucrm_lead_organization_id $( [ "$lf|$lr" = "-|-" ] && echo "is unset in the configuration files and in the store row: a new AI-lead client falls back to the quoting organization #$qorg" || echo "names the quoting organization #$qorg ($lf/$lr; files/store row, - unset)")"
    elif [ -n "$LEADDIFF" ]; then QG6_NOTED=1
      note "Q-G6 --lead-org-differs, the operator's explicit choice: ucrm_lead_organization_id names organization $lf/$lr (files/store row, - unset), not the quoting organization #$qorg — every new AI-lead client is filed there, where the check before an app quote refuses it"
    else stop "NO-GO (Q-G6): ucrm_lead_organization_id names organization $lf/$lr (files/store row, - unset), not the quoting organization #$qorg — every new AI-lead client would be filed under organization #${ln# }, where the check before every app quote refuses it. Clear or correct the key with tools/set_config.php first; or, to deploy all the same — the operator's explicit choice, said as such in the log — its own command, alone:$(printf '\n      %s' "$(with_flags --lead-org-differs)")"; fi
  fi
  # The notes, counts only.
  qn1="$(qn1_state "$PIN_ROOT" "${qorg:-0}")"
  QL_QN1="$qn1"   # 5.18.102: the same reading, for QL-N6 (ql_stage) — never a second read of the live configuration
  case "$qn1" in
    "lead="*) note "Q-N1 the configuration that bears on the check (the configuration files/the store row): ucrm_lead_organization_id $(kv "$qn1" lead); ai_crm_lead_sync $(kv "$qn1" lsync); crm_auth_token $(kv "$qn1" token), and $(kv "$QO_L" keys | cut -d: -f1) account(s) carrying a personal ucrm_app_key ($(kv "$QO_L" keys | cut -d: -f2) active), the KYC form's key where no token is set; crm_base_url $(kv "$qn1" url); quote_company_name, _phone, _email $(kv "$qn1" qcname), $(kv "$qn1" qcphone), $(kv "$qn1" qcemail) (each wins over the Uganda profile's fallback); quote_email_via_plugin $(kv "$qn1" qvia); the quotation customer e-mail $(kv "$qn1" qmail); ucrm_quote_organization_id $(kv "$qn1" qkey)" ;;
    *) note "Q-N1 the configuration could not be read read-only ($qn1) — said, never a reason to stop" ;;
  esac
  note "Q-N2 the app's uCRM clients — the distinct crm_client_id of kyc_applications, leads and quotes_log, read/all $(kv "$QO_L" ids | cut -d: -f1) (at most 300 read), one GET each: $(qn2_say "$(kv "$QO_R" qn2)") — the $(kv "$QO_R" outside) filed under another organization are on the sheet by id: the move-list for uCRM"
  q="$(kv "$QO_R" qn3)"; QN3_A="${q%%:*}"
  case "$QN3_A" in
    none) note "Q-N3 no uCRM quote created since $QN3_SINCE — read again after the copy (Q-CA3)" ;;
    ''|*[!0-9]*) note "Q-N3 the newest uCRM quote could not be read ($q) — Q-CA3 then has nothing to set its own reading against" ;;
    *) note "Q-N3 the newest uCRM quote: #$QN3_A ($(printf '%s' "$q" | cut -d: -f2) created since $QN3_SINCE) — read again after the copy (Q-CA3): a newer one is staff quoting, never this run" ;;
  esac
  q="$(kv "$QO_L" qn4)"
  note "Q-N4 KycCrmSync's queue — the applications saved here and not yet in uCRM, which its retry creates, after the deploy, under the quoting organization: pending $(subkv "$q" pending) ($(subkv "$q" spent) of them at ten attempts; $(subkv "$q" otherorg) whose saved request names another organization), review $(subkv "$q" review), failed $(subkv "$q" failed); synced $(subkv "$q" synced)"
  note "Q-N5 crm_queue.json by status: $(kv "$QO_L" qn5 | sed 's/,/, /g; s/:/ /g') — the legacy processors still create clients from the rows not done (L2); a client they make is refused at quote time"
  q="$(kv "$QO_L" qn6)"
  note "Q-N6 LTE registrations of the last 90 days: $( [ "$q" = "-" ] && echo "no lte_subscribers table" || echo "${q%%:*}, ${q#*:} of them with a uCRM link") — whether LTE registration is used on Uganda"
  # Q-N7 — carried (5.18.99's L1); since 5.18.102 its last words depend on the quoting organization (docs/71 §P.1, D12).
  q="$(kv "$QO_L" qn7)"
  note "Q-N7 the active non-admin accounts that could open a Sync All screen, through the installed RBAC library and the staff records: UCRM Product Mapping $(subkv "$q" pm) (every one), Subscription Plans $(subkv "$q" plans), the Hardware Catalog $(subkv "$q" hw) — $( [ -n "$qorg" ] && echo "with the quoting organization #$qorg in force, the server refuses Sync All under $BASELINE_VERSION as after the deploy (since 5.18.102: D12, docs/71 §K.3, §P.1): a non-admin \"Admin only.\", an admin the plugin's own refusal \"uCRM's product was not changed: on Uganda, prices are set in uCRM Products.\", which UCRM Product Mapping shows; the Subscription Plans and Hardware Catalog screens draw no Sync All there (D14, docs/71 §R.2.2), and with the uCRM catalogue's switch on (5.18.103) they are out of the menu. $EXPECTED_VERSION changes none of this" || echo "each now gets \"Done… Created: 0\" from Sync All (L1), as under $BASELINE_VERSION: no quoting organization is in force (Q-G3), so the gate is off and the three screens are unchanged")"
  return 0
}
# qo_after INST_ROOT — after the copy (stage R; --after-only too): Q-CA2, Q-CA3 and Q-CA6 through INST_ROOT, the copy of
# the installed code (ICODE_R), on copies and from uCRM with GETs only. Stage R reports; nothing here stops. Reads QG3_A,
# QG4_A, QN3_A and QN3_SINCE (stage A's, from this run or from the state file) and QO_A_IN, QO_A_OUT (this run's stage A
# only: an --after-only run picks its two clients again from Q-N2's list, never from a file).
qo_after() {
  local inst="$1" vb s2 r2 qorg t q in out d o rc
  QO_LABEL="stage R, after the copy, the copy of $(date -u +%Y-%m-%dT%H:%M:%SZ)"
  vb="$(vt_now)"
  sheet_open || true   # R23 opened it; when R23 could not run, the quoting checks open it themselves
  if [ -z "$inst" ]; then bad "Q-CA2 Q-CA3 the copy of the installed code was not made — the quoting organization is not read after the copy"
  elif ! qo_run r "$inst"; then bad "Q-CA2 Q-CA3 the quoting checks could not be read on a copy and from uCRM — $QO_ERR. Every copy is removed"
  else
    vt_same "$vb" || bad "Q-CA the live vault (${VAULT_IN:-its path not known}) could not be shown unchanged while the quoting checks read their copies ($(vt_say "$vb") → $(vt_say "$(vt_now)")) — a run on a copy must never write it; a settings save at that moment is the other cause"
    echo "  quoting copy    made at $QO_AT — the quoting keys of the settings files, of the vault and of the store row, and the book's consistent copy"
    echo "  installed gate  $QO_G2   (files/store row)"
    echo "  control south-sudan  $QO_C0"
    echo "  control quote-org 0  $QO_C1"
    echo "  uCRM, GET-only  $QO_R"
    # Q-CA2 — setting() through the installed code equals stage A's answer through the pin's; two controls.
    s2="$(qo_set_of "$QO_G2")"; r2="$(qo_row_of "$QO_G2")"
    if [ -z "$QG3_A" ]; then bad "Q-CA2 stage A's reading of the quoting organization (Q-G3) is not known to this run ($STATE) — the installed code's ($s2/$r2) has nothing to equal"
    elif [ "$(kv "$QO_G2" tenant)" = "uganda/uganda" ] && [ "$s2" = "$QG3_A" ] && [ "$r2" = "$QG3_A" ]; then ok "Q-CA2 the INSTALLED QuoteOrganization::setting() on a copy reads what stage A read through the pin's: $s2 — the configuration files and the store row alike"
    else bad "Q-CA2 the INSTALLED QuoteOrganization::setting() reads $s2 (files) / $r2 (store row), tenant $(kv "$QO_G2" tenant) — stage A read $QG3_A through the pin's code"; fi
    if [ "$(kv "$QO_C0" tenant)" = "south-sudan/south-sudan" ] && [ "$(kv "$QO_C0" setting)" = "off:-:off:-/off:-:off:-" ]; then ok "Q-CA2 control: the same copy with tenant_profile=south-sudan, in a PHP process of its own → off (off:-:off:-)"
    else bad "Q-CA2 control: the same copy with tenant_profile=south-sudan reads tenant $(kv "$QO_C0" tenant), setting $(kv "$QO_C0" setting) — it must be off"; fi
    if [ "$(kv "$QO_C1" setting)" = "off:-:explicit-off:-/off:-:explicit-off:-" ]; then ok "Q-CA2 control: the same copy with ucrm_quote_organization_id=0, in a PHP process of its own → explicit-off"
    else bad "Q-CA2 control: the same copy with ucrm_quote_organization_id=0 reads $(kv "$QO_C1" setting) — it must be explicit-off"; fi
    qorg="$(qo_org "$QO_G2")"
    # Q-CA3 — the installed checkClient(), GET-only, its sink the run's own; nothing created.
    if [ "$QO_OTHER" = "0" ] && [ -z "$QO_COUNT_BAD" ]; then ok "Q-CA3 nothing was created in uCRM: every request this run made of it, through its GET-only wrappers, was a GET ($QO_GETS in all) — none other was asked"
    else bad "Q-CA3 a request other than a GET was asked of uCRM (other $QO_OTHER;${QO_COUNT_BAD:- counted}) — the wrapper refused it before it reached uCRM"; fi
    case "$(kv "$QO_R" orgs)" in
      ok:*) t="$(kv "$QO_R" orgids)"
        if [ -z "$QG4_A" ]; then note "Q-CA3 uCRM's organizations, through the installed code: $t — stage A's list (Q-G4) is not known to this run"
        elif [ "$t" = "$QG4_A" ]; then ok "Q-CA3 uCRM's organizations, through the INSTALLED QuoteOrganization::organizations(), wrapped GET-only: $t — what stage A read (Q-G4)"
        else bad "Q-CA3 uCRM's organizations, through the installed code: $t — stage A read $QG4_A (Q-G4)"; fi ;;
      *) bad "Q-CA3 uCRM's organizations could not be read through the installed code ($(kv "$QO_R" orgs))" ;;
    esac
    if [ -z "$qorg" ]; then echo "  Q-CA3           checkClient() not asked: no quoting organization is in force (Q-CA2)"
    else
      in="$(kv "$QO_R" in)"; out="$(kv "$QO_R" out)"
      case "$in" in
        pass) ok "Q-CA3 checkClient() on a client of the quoting organization #$qorg (its id on the sheet) → pass" ;;
        none) note "Q-CA3 INCONCLUSIVE: no client of the quoting organization #$qorg was found — neither among the app's clients (Q-N2) nor in one GET clients?limit=50; the first real quote after the deploy is the proof" ;;
        *) bad "Q-CA3 checkClient() on a client stage A read in the quoting organization #$qorg → $in (its id on the sheet)" ;;
      esac
      case "$out" in
        refused:R1) ok "Q-CA3 checkClient() on a client outside it (its id on the sheet) → refused: filed under organization #$(kv "$QO_R" outorg)$( [ -n "$QO_A_OUTORG" ] && [ "$QO_A_OUTORG" != "$(kv "$QO_R" outorg)" ] && echo " (stage A read it under #$QO_A_OUTORG)")" ;;
        none) note "Q-CA3 the refusal is not exercised: the app's clients include none filed under another organization (Q-N2)" ;;
        pass) note "Q-CA3 the client stage A read outside the quoting organization now passes — moved to #$qorg in uCRM since (its id on the sheet); the refusal is not exercised" ;;
        *) bad "Q-CA3 checkClient() on a client outside the quoting organization → $out (its id on the sheet); it must be refused R1" ;;
      esac
      case "$QO_TOK" in
        token=set*) if [ "$(kv "$QO_R" tin)" = "$in" ] && [ "$(kv "$QO_R" tout)" = "$out" ]; then ok "Q-CA3 the same two checks through the token client (built as KycService::postQuote builds it, its copy removed once read): $(kv "$QO_R" tin), $(kv "$QO_R" tout)"
          else bad "Q-CA3 through the token client the two checks answer $(kv "$QO_R" tin), $(kv "$QO_R" tout) — the plugin's client answered $in, $out"; fi ;;
      esac
      echo "  Q-CA3           the guard's refusal lines went to this run's own sink: $(kv "$QO_R" sink) — never to the plugin's log"
    fi
    # Where the probe's refusal lines went, read on its own code copy before it was removed: its data/plugin.log (PluginLog
    # writes beside the code it loads) and its PHP error log hold none of them — its sink took them — and the control, the
    # same guard with no sink on the same copy (deploy-check-control), wrote its one line to each, so the reading can see
    # one. The live data/plugin.log the probe cannot reach: a line there labelled this run's means its code copy logs
    # where the live plugin does (FAIL); a line naming a probed client, unlabelled, is staff at work (a note).
    if [ "$QO_CPROBE" = "0:1 0:1" ]; then ok "Q-CA3 the probe's refusal lines reached neither its code copy's data/plugin.log nor its PHP error log (0 and 0) — its own sink took them; control: the same guard with no sink, on the same copy, wrote its one line to each (1 and 1)"
    else bad "Q-CA3 where the probe's refusal lines went, read on its code copy — data/plugin.log, then its PHP error log, each as the probe's:the control's: ${QO_CPROBE:-not read} — the probe's must be 0 in both, the control's 1 in each"; fi
    if [ "$QO_LOGHIT" != "0" ]; then bad "Q-CA3 the live data/plugin.log gained $QO_LOGHIT line(s) labelled this run's (deploy-check) while the probe ran — only this run's guard writes that label, and its code copy logs beside itself: here it logged where the live plugin does"
    elif [ "$QO_LOGSTAFF" != "0" ]; then note "Q-CA3 the live data/plugin.log gained $QO_LOGSTAFF line(s) naming a probed client (its id on the sheet) while the probe ran, none labelled this run's — staff activity on that client, never this run, whose lines went to its own sink"
    else echo "  Q-CA3           the live data/plugin.log gained no line labelled this run's or naming a probed client while the probe ran (other lines may: staff may be working)"; fi
    # Q-N3's window read again: the quotes created since stage A's own date (this run's stage A, or the deploy's state
    # file), never a window of this run's own — the same question asked twice. A newer quote in it is staff quoting; a
    # reading that has lost stage A's quote, or a window not known, is not comparable: a note either way, never a FAIL.
    q="$(kv "$QO_R" qn3)"; t="${q%%:*}"
    if [ -z "$t" ] || [ "$t" = "?" ] || [ -z "$QN3_A" ] || [ "$QN3_A" = "?" ] || [ -z "$QN3_SINCE" ] || [ "$QO_SINCE" != "$QN3_SINCE" ]; then note "Q-CA3 the newest uCRM quote could not be set against stage A's (now ${q:-not read}, created since ${QO_SINCE:-?}; stage A ${QN3_A:-not known to this run}, created since ${QN3_SINCE:-a date not known to this run})"
    else
      case "$(qn3_cmp "$t" "$QN3_A")" in
        same) ok "Q-CA3 the newest uCRM quote is stage A's ($( [ "$t" = "none" ] && echo "none" || echo "#$t"), created since $QN3_SINCE: stage A's window, read again) — nothing was quoted by this run" ;;
        newer) note "Q-CA3 the newest uCRM quote created since $QN3_SINCE is #$t, stage A read $( [ "$QN3_A" = "none" ] && echo "none" || echo "#$QN3_A") in the same window — staff quoting since, never this run (it asked uCRM nothing but GETs)" ;;
        *) note "Q-CA3 the newest uCRM quote created since $QN3_SINCE is $( [ "$t" = "none" ] && echo "none" || echo "#$t") now, and stage A read #$QN3_A in the same window — not comparable: a quote stage A read is no longer listed (removed in uCRM, or a window uCRM does not keep to); this run asked uCRM nothing but GETs" ;;
      esac
    fi
  fi
  # Q-CA6 — the installed profile, set_config's listing and its refusal of a value that is not a number, on a throwaway folder.
  if [ -z "$inst" ]; then bad "Q-CA6 the copy of the installed code was not made — the profile and set_config are not read"
  else
    o="$(docker exec -u "$DB_OWNER" -e DN_VAULT_FILE="$CHK/qca6-vault-none.json" -e DN_DATA_DIR="$CHK/qca6-none" "$CONTAINER" php -d display_errors=stderr -r "$QO_PHP" profile "$inst" 2>/dev/null </dev/null)"
    [ "$o" = "uganda=1 south-sudan=NULL" ] && ok "Q-CA6 the installed profiles, through the installed TenantProfile: profiles/uganda.json gives quoting.ucrm_organization_id 1, South Sudan none" \
      || bad "Q-CA6 the installed profiles, through the installed TenantProfile: ${o:-?} — profiles/uganda.json must give quoting.ucrm_organization_id 1, and South Sudan none"
    grep -qF "'ucrm_quote_organization_id' => ['text'," "$DEST/tools/set_config.php" 2>/dev/null \
      && ok "Q-CA6 the installed tools/set_config.php lists ucrm_quote_organization_id as text" \
      || bad "Q-CA6 the installed tools/set_config.php does not list ucrm_quote_organization_id as text"
    # The throwaway folder is the database owner's own, in the container's /tmp, named as every folder that owner makes
    # is (ep_run, cih_init): the code copy ($CHK) is root's, made by docker cp, and nobody else may write in it — the
    # folder inside it could never be made (rehearsal trial 4, 99-4). chk_cleanup removes it at the end in any case.
    d="/tmp/dnb-$EXPECTED_VERSION-qca6-$TS-$$-$RANDOM"
    if ! dxo mkdir -m 700 "$d"; then bad "Q-CA6 the throwaway data folder for set_config's refusal could not be made in the container's /tmp"
    else
      o="$(docker exec -u "$DB_OWNER" -e DN_DATA_DIR="$d" -e DN_VAULT_FILE="$d/vault.json" "$CONTAINER" sh -c 'php "$1/tools/set_config.php" --key ucrm_quote_organization_id --value disabled 2>&1; echo "rc=$?"' _ "$inst" 2>/dev/null </dev/null)"
      rc="$(printf '%s\n' "$o" | tail -n1)"; t="$(dxo sh -c 'find "$1" -mindepth 1 | wc -l' _ "$d" | tr -d ' ')"
      cih_drop "$d"
      if [ "$rc" = "rc=1" ] && grep -qF '"disabled" is not an organization number or 0/off, so nothing was saved.' <<<"$o" && [ "$t" = "0" ]; then ok "Q-CA6 the installed tools/set_config.php, from the copy of the installed code on a throwaway data folder of its own (never the live one), refuses --value disabled — \"is not an organization number or 0/off, so nothing was saved\", exit 1, before any uCRM read and any save: the folder is still empty"
      else bad "Q-CA6 the installed tools/set_config.php on a throwaway data folder, --value disabled: ${rc:-no exit status}, $( grep -qF 'is not an organization number or 0/off' <<<"$o" && echo "the refusal printed" || echo "the refusal NOT printed"), ${t:-?} file(s) left in the folder — it must refuse with exit 1 and write nothing"; fi
    fi
  fi
  # 5.18.102 (E2-2, L2, review 2): the quoting organization in one word each, for the summary (F). QO_GATE_R: as the
  # INSTALLED code read it after the copy — unread when no reading was made after it (no code copy: QO_G2 may then still
  # hold stage A's reading of the code installed before the deploy; or qo_run r stopped before its gate probe: QO_G2 is
  # empty). QO_GATE_A: as stage A read it through the pin's (QG3_A, this run's or the deploy's state file).
  QO_GATE_A="$(qo_gate_a)"; QO_GATE_R=unread
  [ -z "$inst" ] || QO_GATE_R="$(qo_gate_state "$QO_G2")"
  return 0
}
# ── 5.18.102: the catalogue the KYC form offers, and the notes (QL, "quote lines"; docs/71 §L.3, §Q) ────────────────────
# The probe's lists are "client:part;client:part" — plug, tok, dbg — each part "key:n,…", or a word: unset (no token), same
# (the debug retry's client is the token client). Helpers over them, counts only.
ql_of() { printf '%s' "$1" | tr ';' '\n' | sed -n "s/^$2://p" | head -1; }   # ql_of LIST CLIENT — that client's part
ql_n() { local v; v="$(subkv "$1" "$2")"; case "$v" in ''|*[!0-9]*) ;; *) printf '%s' "$v" ;; esac; }   # ql_n PART KEY — a count, or nothing
ql_well() { local f; for f in rows ok unpriced unlinked fiber unread other; do [ -n "$(ql_n "$1" "$f")" ] || return 1; done; return 0; }   # all seven counts (5.18.102 D14 derivation M-20: unlinked beside unpriced)
ql_bk() { local u l; u="$(ql_n "$1" unpriced)"; l="$(ql_n "$1" unlinked)"; if [ -n "$u" ] && [ -n "$l" ] && [ "$l" -le "$u" ]; then echo $((u - l)); fi; }   # ql_bk PART — linked but broken: the unpriced less the not linked (D14 §R.7.3), or nothing
ql_say() { printf '%s item(s) — %s resolve, %s not linked, %s linked but broken, %s Fiber (apart)' "$(ql_n "$1" rows)" "$(ql_n "$1" ok)" "$(ql_n "$1" unlinked)" "$(ql_bk "$1")" "$(ql_n "$1" fiber)"; }
ql_why() {   # ql_why PART [all] — a client's part of qlr= in words: the classes that are not 0 — the broken ones; with all, not linked too
  # 5.18.102 D14 (docs/71 §R.4.1, §R.7.3; derivation M-3): each class is one of the release's fixed why codes, said as what
  # it holds; each item's reason, verbatim — which says its own remedy — is on the sheet with its name.
  printf '%s' "$1" | tr ',' '\n' | awk -F: -v all="${2:-}" '$2 > 0 && (all != "" || $1 != "unlinked") { w = $1
      if ($1 == "unlinked") w = "not linked"; else if ($1 == "two") w = "two links recorded"
      else if ($1 == "replaced") w = "linked before its row was replaced"; else if ($1 == "org") w = "linked for another quoting organization"
      else if ($1 == "gone") w = "linked to a uCRM item uCRM no longer lists, or lists as archived, not active or another organization"
      else if ($1 == "bad") w = "no price, a price of 0, more than 2 decimals, taxable, no product id or an invoice label unlike its name"
      else if ($1 == "rows200") w = "200 service plans or more in uCRM"; else if ($1 == "twin") w = "its service plan spelled like another"
      else if ($1 == "nomonth") w = "no 1-month price"; else if ($1 == "planprice") w = "a service plan price that is not its 1-month price"
      else if ($1 == "differs") w = "a product price that differs from its service plan"; else if ($1 == "apart") w = "a product and service plan not spelled alike"
      else if ($1 == "likeplan") w = "hardware spelled like a service plan"; else if ($1 == "rule8") w = "a kit and the installation linked to one product (rule 8)"
      printf "%s%s %s", (n++ ? ", " : ""), w, $2 } END { if (!n) printf "none" }'
}
# 5.18.102 D14 (docs/71 §R.7.1–§R.7.3): the probe's link, candidate and comparison counts in words, and the checks over
# them — counts only. A hash value is never printed: ql_hl_say says its state.
ql_hl_ok() {   # ql_hl_ok i|r VALUE — VALUE (since 5.18.103 QO_QCI, QC_I_A: "<H>:<H>,…"; an r value "<H>:a|e,…" or none) as written
  case "$1:$2" in r:none) return 0 ;; esac
  if [ "$1" = "i" ]; then printf '%s' "$2" | drained grep -qxE '[0-9a-f]{32}:[0-9a-f]{32}(,[0-9a-f]{32}:[0-9a-f]{32})*'
  else printf '%s' "$2" | drained grep -qxE '[0-9a-f]{32}:[ae](,[0-9a-f]{32}:[ae])*'; fi
}
ql_hl_n() { case "$1" in none) echo 0 ;; *) printf '%s\n' "$1" | tr ',' '\n' | grep -c . || true ;; esac; }   # ql_hl_n VALUE — how many entries
ql_hl_say() { case "$1" in '') echo "none made" ;; '?'*) echo "$1" ;; none) echo none ;; *) echo "not as written" ;; esac; }   # ql_hl_say VALUE — its state, never a hash
ql_cand_well() { [ -n "$(ql_n "$1" plans)" ] && [ -n "$(ql_n "$1" hw)" ]; }   # ql_cand_well PART — qlcand's two counts
ql_cand_say() { printf '%s plan pair(s) (a product with its service plan) and %s product(s) for hardware and the installation' "$(ql_n "$1" plans)" "$(ql_n "$1" hw)"; }
ql_cand_no() {   # ql_cand_no PART PLANS WHO — the kinds uCRM offers nothing an admin could link for through WHO, or nothing:
  # plans only where the form offers a plan that is not Fiber (PLANS, qlrows' plan), hardware and the installation always —
  # the installation is always offered (D14 derivation M-4)
  [ "$(ql_n "$1" plans)" != "0" ] || [ "${2:-0}" = "0" ] || printf '; plans, through %s' "$3"
  [ "$(ql_n "$1" hw)" != "0" ] || printf '; hardware and the installation, through %s' "$3"
  return 0
}
ql_rows_say() { printf '%s plan(s) (%s Fiber, apart), %s kit(s) (%s Fiber, apart) and the installation; %s kyc_packages row(s), apart (QL-N7)' "$(ql_n "$1" plan)" "$(ql_n "$1" planfiber)" "$(ql_n "$1" kit)" "$(ql_n "$1" kitfiber)" "$(ql_n "$1" package)"; }
ql_org1() { case "$1" in */*/*) printf '%s row(s), %s carrying an organizationId, %s of them not the quoting organization'"'"'s' "${1%%/*}" "$(printf '%s' "$1" | cut -d/ -f2)" "${1##*/}" ;; *) printf 'not read (%s)' "${1:-?}" ;; esac; }
ql_org_say() { case "$1" in -|'') printf 'not read' ;; *) printf 'products %s; service plans %s' "$(ql_org1 "$(subkv "$1" p)")" "$(ql_org1 "$(subkv "$1" s)")" ;; esac; }   # ql_org_say QLORG-PART — "p:<rows>/<with>/<differs>,s:…" in words
ql_cmp_well() { local f; for f in same differs left new gone linked ended; do [ -n "$(ql_n "$1" "$f")" ] || return 1; done; return 0; }   # ql_cmp_well QLCMP — all seven counts
ql_cmp_say() { printf '%s compared — the same %s, different %s; not at stage A %s, at stage A and not now %s; left out %s — link records made since stage A %s, ended or relinked since %s' "$(( $(ql_n "$1" same) + $(ql_n "$1" differs) ))" "$(ql_n "$1" same)" "$(ql_n "$1" differs)" "$(ql_n "$1" new)" "$(ql_n "$1" gone)" "$(ql_n "$1" left)" "$(ql_n "$1" linked)" "$(ql_n "$1" ended)"; }   # ql_cmp_say QLCMP — after ql_cmp_well
ql_need_say() {   # ql_need_say QLNEED — "plan:<none>:<other>,kit:…,install:…" (the local reading's judge(), offered items only) in words; nothing when every one carries a link in force; fails when not well formed
  local pn po kn ko ia io s
  pn="$(subkv "$1" plan)"; kn="$(subkv "$1" kit)"; ia="$(subkv "$1" install)"
  for s in "$pn" "$kn" "$ia"; do case "$s" in ''|*[!0-9:]*|:*|*:|*:*:*) return 1 ;; *:*) ;; *) return 1 ;; esac; done
  po="${pn#*:}"; pn="${pn%%:*}"; ko="${kn#*:}"; kn="${kn%%:*}"; io="${ia#*:}"; ia="${ia%%:*}"
  [ $((pn + kn + ia + po + ko + io)) != 0 ] || return 0
  if [ "$ia" = "0" ]; then s="$pn plan(s) and $kn kit(s) the KYC form offers are not linked (the installation is)"
  else s="$pn plan(s), $kn kit(s) and the installation are not linked"; fi
  [ $((po + ko + io)) = 0 ] || s="$s; $((po + ko + io)) more carry a link that no longer holds (two links recorded, a row replaced since it was linked, or another quoting organization's)"
  printf '%s' "$s"
}
ql_stray_say() {   # ql_stray_say QLSTRAY — "plan:<n>,kit:<n>,kitinstall:<n>" (links in force on rows the form does not offer) in words
  local a b k
  a="$(ql_n "$1" plan)"; b="$(ql_n "$1" kit)"; k="$(ql_n "$1" kitinstall)"
  if [ -z "$a" ] || [ -z "$b" ] || [ -z "$k" ]; then printf 'not counted (%s)' "${1:-not read}"; return 0; fi
  printf '%s plan(s) and %s kit(s)' "$a" "$b"
  [ "$k" = "0" ] || printf ' — of the kits, %s name the installation'"'"'s product, which does not block the installation (rule 8 judges the offered kits only), while a stored sale holding such a row is unpriced at use (docs/71 §R.17)' "$k"
}
ql_unp() {   # ql_unp QLC — the items that do not resolve through the plugin's own client and the token client (when set), summed; or nothing
  # — for the decisions alone: none or some (QL-G1's note, F; QL-CA1's until 5.18.103). Both clients judge the same items the form
  # offers, so the sum counts verdicts, not items: never print it as a number of items — ql_unp_say says them.
  local p t a b
  p="$(ql_of "$1" plug)"; t="$(ql_of "$1" tok)"
  a="$(ql_n "$p" unpriced)"; b=0; case "$t" in unset|'') ;; *) b="$(ql_n "$t" unpriced)" ;; esac
  [ -n "$a" ] && [ -n "$b" ] && echo $((a + b))
}
ql_unp_say() {   # ql_unp_say QLC [QLR] — the items that do not resolve, client by client, in words: not linked, and linked but broken (with the broken ones' classes when QLR is given)
  local p t a b
  p="$(ql_of "$1" plug)"; t="$(ql_of "$1" tok)"; a="$(ql_bk "$p")"
  printf 'through the plugin'"'"'s own client %s not linked, %s linked but broken' "$(ql_n "$p" unlinked | sed 's/^$/?/')" "${a:-?}"
  [ -z "${2:-}" ] || [ "${a:-0}" = "0" ] || printf ' (%s)' "$(ql_why "$(ql_of "$2" plug)")"
  case "$t" in
    unset|'') ;;
    *) b="$(ql_bk "$t")"; printf '; through the token client %s not linked, %s linked but broken' "$(ql_n "$t" unlinked | sed 's/^$/?/')" "${b:-?}"
       [ -z "${2:-}" ] || [ "${b:-0}" = "0" ] || printf ' (%s)' "$(ql_why "$(ql_of "$2" tok)")"
       printf ', the same items judged by each' ;;
  esac
}
ql_pk_say() {   # ql_pk_say QLPK-PART — QL-N7's kyc_packages rows in words: each "package" (D14 §R.2.5), none priced
  case "$(ql_n "$1" unread)" in 0) ;; '') printf 'not counted (%s)' "${1:-not read}"; return 0 ;; *) printf '%s row(s), not judged: uCRM'"'"'s products could not be read' "$(ql_n "$1" rows)"; return 0 ;; esac
  printf '%s row(s) — %s a retailer-app package, not linked to uCRM; %s priced%s; %s unclassified' "$(ql_n "$1" rows)" "$(ql_n "$1" unpriced)" "$(ql_n "$1" ok)" "$( [ "$(ql_n "$1" ok)" = "0" ] || echo " (the release prices none: say so with the log file)")" "$(ql_n "$1" other)"
}
ql_rd() {   # ql_rd STATE — a client's catalogue read state (qlread=) in words: read, http<code>, curl, unusable or noanswer
  case "$1" in
    unusable) printf '%s' "uCRM answered, but not with a list the release can use: 500 rows or more in Products or Service Plans, or a body that is not a JSON list" ;;
    noanswer) printf '%s' "no answer recorded" ;;
    *) printf '%s' "${1:-not read}" ;;
  esac
}
ql_who() { printf '%s' "$1" | sed 's/plug/the plugin client/; s/tok/the token client/; s/dbg/the debug client/; s/,/ and /g'; }   # ql_who CLIENTS — plug,tok,dbg in words
ql_attr_say() { case "$1" in one:1) echo "exactly one, #1 — an id the release never uses" ;; one:*) echo "exactly one, #${1#one:}" ;; absent) echo "absent" ;; ambig:*) echo "${1#ambig:} attributes keyed salesPerson (ambiguous)" ;; unread:*) echo "not readable (${1#unread:})" ;; *) echo "not read (${1:-?})" ;; esac; }
ql_n3_say() {   # ql_n3_say CELLS STATUS — one status's cells of qln3= in words
  printf '%s' "$1" | tr ',' '\n' | awk -F'[.:]' -v s="$2" '$1 == s { t += $5; m[$2] += $5; l[$3] += $5; c[$4] += $5 }
      END { printf "%d (marked by 5.18.102 %d, by 5.18.103 %d, neither %d; lines with a productId %d, without one %d, none %d; Cash %d, Credit %d)", t, m["marked"], m["direct"], m["unmarked"], l["pid"], l["nopid"], l["none"], c["cash"], c["credit"] }'
}
ql_q314_say() {   # "read:<n>items:<type>.pid<0|1>.unit<0|1>,…" in words
  local n l; n="${1#read:}"; l="${n#*items:}"; n="${n%%items:*}"
  printf '%s item(s)' "$n"
  [ "$l" = "-" ] || printf ' — %s' "$(printf '%s' "$l" | tr ',' '\n' | awk -F. '{ printf "%s%s, %s, %s", (n++ ? "; " : ""), $1, ($2 == "pid1" ? "a productId" : "no productId"), ($3 == "unit1" ? "a unit" : "no unit") }')"
}
ql_d11_say() {   # ql_d11_say QLN3D11 — QL-N3's applications the retry cannot price after the deploy (D11), in words
  # 5.18.102 D14 (docs/71 E-1, §R.7.1, §R.7.5 item 11): "pending:<n>,review:<n>,p1:<n>,p2:<n>" — by the release's entry
  # rule, every one with no quotation made whose quote_sale_entry is neither web (5.18.102's form) nor web-direct, by
  # status and by what retryLines then records (P1, P2), Fiber or not, marked or not. Counts only.
  local p r a b
  p="$(ql_n "$1" pending)"; r="$(ql_n "$1" review)"; a="$(ql_n "$1" p1)"; b="$(ql_n "$1" p2)"
  if [ -z "$p" ] || [ -z "$r" ] || [ -z "$a" ] || [ -z "$b" ] || [ $((p + r)) -ne $((a + b)) ]; then
    printf 'How many of them the retry cannot price after the deploy, whatever uCRM holds (D11), was not counted (%s)' "${1:-not read}"
    return 0
  fi
  printf 'Whatever uCRM holds and whatever an admin links, the retry makes no quotation for %s of them (D11, docs/71 §F.4; E-1): every one with no quotation made that is neither a web registration nor a direct sale — pending %s, review %s; P1, Credit or no cash recorded, %s; P2, Cash with cash collected, %s%s' \
    "$((p + r))" "$p" "$r" "$a" "$b" \
    "$( [ $((p + r)) = 0 ] || echo " — each one's quotation is made by hand in uCRM, or not at all (docs/71 §F.4, §F.5); its Orders card draws no Make the quotation")"
}
# ql_stage — QL-G1 and QL-N1–QL-N7, stage A (a deploy and --check), on qo_stage's reading (qo_run a: the PIN's code from
# Git — its UcrmQuoteLines, and its lib/UcrmQuoteLinks.php loaded into the local reading by that file's own path — on the
# copies, and uCRM with GETs only, in the probe whose requests Q-G4's refusal counted). 5.18.102 D14 (docs/71 §R.7.1):
# an item the form offers that does not resolve is not refused — before 5.18.102's copy nothing could be linked (5.18.101
# had no link screen), and since it the link store is what 5.18.102's Plans and Hardware screens wrote (under D6 nothing
# is linked, docs/72 G-10) — so every such item is "not linked" (§R.6), or broken, and the count is a note. QL-G1
# refuses (docs/71 §Q D-R4, §R.7.1): an unreadable catalogue through the plugin's own client or, when crm_auth_token is
# set, the token client; an answer this script cannot classify ("other": a why code it does not know, or a text that is
# not that code's exact template with the item's shown name — D14 derivation M-3); a request but the two lists; the link
# store on the copy unread, or the pin without its lib/UcrmQuoteLinks.php (?nolinks, derivation M-6); the items' or the
# link records' keyed hashes not made — no flag lifts these; and a kind for which uCRM offers nothing an admin could link
# (qlcand: the release's own candidate() over an empty judge — plans where the form offers a plan that is not Fiber,
# hardware and the installation always; derivation M-4), unless --accept-unpriced, the operator's explicit choice
# (QLG1_NOTED). The not linked and the broken, the link store (two active records for one item a note here — derivation
# M-10), the organization field (derivation M-8) and the debug retry's own client are notes; the kyc_packages rows are
# QL-N7's. With no quoting organization in force QL-G1 is a note. A refusal stops: nothing has changed. Sets QLG1_A
# (QL-G1's counts by client and by class), QLATTR_A, and QLG1_NOTED only when --accept-unpriced decided QL-G1. Since
# 5.18.103 (docs/72 §G.13) QL-CA1 and QL-LK1 are retired, so the items' and the link records' keyed hashes and the
# highest application id they compared are neither judged nor kept.
QLG1_A=""; QLATTR_A=""; QLG1_NOTED=""; QL_QN1=""
QL_KEY_A=""   # the QL key the readings after the copy compare under (QC-CA1 since 5.18.103), set in stage R (never printed)
QLN3_D11_A=""   # QL-N3's count of the applications the retry cannot price (D11): this run's stage A only, never the state file
ql_stage() {
  local c r p t d u x a q why y lk n cp ct z
  case "$QO_KIND:$QO_R" in a:*" gets="*" other="*) ;; *) stop "NO-GO (QL-G1): stage A's quoting reading is not in this run (${QO_KIND:-none}) — the catalogue cannot be judged. Nothing was changed. Send the log file" ;; esac
  c="$(kv "$QO_R" qlc)"; r="$(kv "$QO_R" qlr)"
  case "$c" in
    off) QLG1_A="off"
      note "QL-G1 not asked: no quoting organization is in force (Q-G3) — $EXPECTED_VERSION then quotes as $BASELINE_VERSION does, nothing is priced from uCRM, and there is nothing to measure (docs/71 D7)" ;;
    plug:*)
      x="$(kv "$QO_R" qlpath)"
      [ "$x" = "ok" ] || stop "NO-GO (QL-G1): the RELEASE's resolver asked uCRM, through $(ql_who "${x#bad:}"), for something other than its two lists once each (GET products?limit=500, then GET service-plans?limit=500) — the code is not the one this script was reviewed against; the wrapper let only GETs through. No flag lifts it. Nothing was changed. Send the log file"
      p="$(ql_of "$c" plug)"; t="$(ql_of "$c" tok)"; d="$(ql_of "$c" dbg)"
      ql_well "$p" || stop "NO-GO (QL-G1): the catalogue's counts through the plugin's own client could not be read ($c). No flag lifts it. Nothing was changed. Send the log file"
      if [ "$QO_TOK" = "token=unset" ]; then [ "$t" = "unset" ] || stop "NO-GO (QL-G1): crm_auth_token is unset, and the probe read the catalogue through a token client ($t). Nothing was changed. Send the log file"
      else ql_well "$t" || stop "NO-GO (QL-G1): crm_auth_token is set, and the catalogue's counts through the token client could not be read (${t:-none}). No flag lifts it. Nothing was changed. Send the log file"; fi
      [ "$(ql_n "$p" unread)" = "0" ] || stop "NO-GO (QL-G1): uCRM's Products and Service Plans could not be read through the plugin's own client, GET-only ($(ql_rd "$(ql_of "$(kv "$QO_R" qlread)" plug)")) — the release reads them so for Send Quotation, and for the KYC form, the submission and the retries where no token is set: after the deploy every Uganda quotation would be refused as unpriced. No flag lifts it. Nothing was changed. Send the log file"
      [ "$t" = "unset" ] || [ "$(ql_n "$t" unread)" = "0" ] || stop "NO-GO (QL-G1): uCRM's Products and Service Plans could not be read through the token client (crm_auth_token, built as KycService::postQuote builds it), GET-only ($(ql_rd "$(ql_of "$(kv "$QO_R" qlread)" tok)")) — the KYC form, the submission and the retries read them so: after the deploy every KYC quotation would be refused as unpriced. No flag lifts it. Nothing was changed. Send the log file"
      u=$(( $(ql_n "$p" other) + $( [ "$t" = "unset" ] && echo 0 || ql_n "$t" other ) ))
      [ "$u" = "0" ] || stop "NO-GO (QL-G1): $u answer(s) of the RELEASE's resolver cannot be classified (\"other\") — a why code this script does not know, or a text that is not that code's exact template with the item's shown name (D14 derivation M-3): the release's words and this script's disagree, so an item's verdict cannot be told; each is on the sheet, verbatim (less $SHEET). No flag lifts it. Nothing was changed. Send the log file"
      # The link store on the copy, read through the pin's UcrmQuoteLinks by its own path (QO_L's qllinks; D14 §R.7.1,
      # derivation M-6): absent (never made here) or counted; anything else leaves a leftover link unjudged.
      lk="$(kv "$QO_L" qllinks)"
      case "$lk" in
        absent) ;;
        records:*) { [ -n "$(ql_n "$lk" records)" ] && [ -n "$(ql_n "$lk" active)" ] && [ -n "$(ql_n "$lk" two)" ]; } || stop "NO-GO (QL-G1): the link store on the copy was read, and its counts could not be ($lk). No flag lifts it. Nothing was changed. Send the log file" ;;
        '?nolinks') stop "NO-GO (QL-G1): the quoting organization is in force, and the RELEASE's lib/UcrmQuoteLinks.php was not where the local reading loads it, the pin's own file by its path (?nolinks) — the link store on the copy cannot be judged: the pin's code, or this script's path to it, is not the one reviewed. No flag lifts it. Nothing was changed. Send the log file" ;;
        *) stop "NO-GO (QL-G1): the link store on the copy could not be read through the pin's UcrmQuoteLinks (${lk:-not read}) — a link made on the Plans or Hardware screens (5.18.102's, or a later release's while the uCRM catalogue's switch is off) would go unjudged. No flag lifts it. Nothing was changed. Send the log file" ;;
      esac
      QLG1_A="$c/$r"
      # What uCRM offers that an admin could link, by kind (qlcand: the release's candidate() over an empty judge and the
      # catalogue just read), against what the form offers (qlrows) — D14 §R.7.1, derivation M-4. A kind with none would
      # stay unpriced after the deploy whatever an admin does: refused, unless --accept-unpriced.
      y="$(kv "$QO_R" qlrows)"; n="$(ql_n "$y" plan)"; x="$(kv "$QO_R" qlcand)"; cp="$(ql_of "$x" plug)"; ct="$(ql_of "$x" tok)"
      { [ -n "$n" ] && ql_cand_well "$cp" && { [ "$t" = "unset" ] || ql_cand_well "$ct"; }; } || stop "NO-GO (QL-G1): what uCRM offers that an admin could link was not counted (${x:-not read}; the rows the form offers: ${y:-not read}). No flag lifts it. Nothing was changed. Send the log file"
      why="$(ql_cand_no "$cp" "$n" "the plugin's own client")$( [ "$t" = "unset" ] || ql_cand_no "$ct" "$n" "the token client")"
      if [ -z "$why" ]; then ok "QL-G1 the plugin's own catalogue — what the KYC form offers while the uCRM catalogue's switch is off (5.18.102's path, which 5.18.103 and 5.18.104 keep; QC-G1 below is what it offers with the switch on) — is read and judged through the RELEASE's UcrmQuoteLines on a copy, GET-only — GET products?limit=500, then GET service-plans?limit=500, nothing else asked by the resolver (the organization field's raw reads come after, below) — with the copy's link records judged by its UcrmQuoteLinks, every answer classified by its why code and exact text: through the plugin's own client $(ql_say "$p")$( [ "$t" = "unset" ] && echo " (crm_auth_token unset: the form, the submission and the retries read with it)" || echo "; through the token client $(ql_say "$t")"); with the switch off the form offers $(ql_rows_say "$y"); uCRM offers what an admin could link, by the release's own rules — through the plugin's own client $(ql_cand_say "$cp")$( [ "$t" = "unset" ] || echo "; through the token client $(ql_cand_say "$ct")"); per item its name, any link recorded on it and uCRM's items with the same spelling (a hint only, never a verdict) on the sheet"
      elif [ -n "$ACCEPT_UNPRICED" ]; then QLG1_NOTED=1
        note "QL-G1 --accept-unpriced, the operator's explicit choice: uCRM offers nothing an admin could link for ${why#; } — no product (for a plan, no product with its service plan) passes the release's own rules over the catalogue just read (docs/71 §R.3.1 rules 4–7) — so while the uCRM catalogue's switch is off — under $BASELINE_VERSION today as after the deploy, which leaves the switch as it is stored — every item of that kind stays unpriced, whatever an admin links: a Cash sale of one is refused, and a Credit one registered with no quotation (P1), the agent told; while it is on, no link decides anything: the forms offer uCRM's own items (docs/72 §G.1, G-10). The catalogue read: through the plugin's own client $(ql_say "$p")$( [ "$t" = "unset" ] || echo "; through the token client $(ql_say "$t")"); per item, uCRM's items with the same spelling and the rule that stops each (a hint only) on the sheet"
      else stop "NO-GO (QL-G1): uCRM offers nothing an admin could link for ${why#; } — no product (for a plan, no product with its service plan) passes the release's own rules over the catalogue just read (docs/71 §R.3.1 rules 4–7) — so while the uCRM catalogue's switch is off — under $BASELINE_VERSION today as after the deploy, which leaves the switch as it is stored — every item of that kind would stay unpriced, whatever an admin links: a Cash sale of one refused, a Credit one registered with no quotation (P1); while it is on, no link decides anything (the sheet's QC lines say what the forms would offer then). Prepare uCRM as docs/71 §M step 3 lists, and run --check again: its sheet lists, per item, uCRM's items with the same spelling and the rule that stops each, a hint only (less $SHEET); or, to deploy with that kind unpriced — the operator's explicit choice, said as such in the log — its own command, alone:$(printf '\n      %s' "$(with_flags --accept-unpriced)")"; fi
      # The items that do not resolve, before the copy: a note (no longer QL-G1's refusal — D14 §R.7.1)
      u="$(ql_unp "$c")"
      [ "${u:-0}" = "0" ] || note "QL-G1 item(s) of the plugin's own catalogue — what the KYC form offers while the uCRM catalogue's switch is off — do not resolve — $(ql_unp_say "$c" "$r") — not linked on 5.18.102's Plans or Hardware screens (or a later release's while the switch was off; under D6 nothing is linked, docs/72 G-10), or linked and broken: a note, as in 5.18.102's and 5.18.103's runs (docs/71 §R.7.1). While the switch is on the forms offer uCRM's own items and no link decides anything (docs/72 §G.1, G-10); only with it off — under $BASELINE_VERSION as under $EXPECTED_VERSION, which leaves the switch as it stands (QC-N1 below says how) — is a Cash sale of one refused and a Credit one registered with no quotation (P1); a broken one's own reason, on the sheet, says its remedy"
      case "$lk" in
        absent) note "QL-G1 the link store on the copy: none — no link was ever recorded on this book on $BASELINE_VERSION's Plans and Hardware screens (under D6 nothing is linked, docs/72 G-10)" ;;
        *) note "QL-G1 the link store on the copy, read through the pin's UcrmQuoteLinks by its own path: $(ql_n "$lk" records) record(s), $(ql_n "$lk" active) active — the store 5.18.102's Plans and Hardware screens wrote (5.18.103's write it only while the uCRM catalogue's switch is off), which $EXPECTED_VERSION keeps as $BASELINE_VERSION does, frozen while the switch is on (docs/72 G-11); each active one is judged above as at use (resolves, or broken by class), its verdict on the sheet with the record$( [ "$(ql_n "$lk" two)" = "0" ] || echo "; $(ql_n "$lk" two) item(s) with two active records — the store is corrupt, the release never writes two (§R.1.4): an admin links each again while the uCRM catalogue is off (a note; QL-LK1, which failed on it, is retired since 5.18.103)")" ;;
      esac
      x="$(kv "$QO_R" qlorg)"; y="$(kv "$QO_R" qlorgpath)"
      note "QL-G1 the organization field, read raw through the same GET-only clients after the catalogue's two lists, counted apart (one GET of each list per client; docs/71 §R.7.1, §D.2): through the plugin's own client $(ql_org_say "$(ql_of "$x" plug)")$( [ "$t" = "unset" ] || echo "; through the token client $(ql_org_say "$(ql_of "$x" tok)")")$( [ "$y" = "ok" ] || echo " — those reads were not exactly the two lists once more (${y:-not read}: $(ql_who "${y#bad:}"))") — a note, never toward the NO-GO; the organization numbers seen on the sheet"
      case "$d" in
        unset|same|'') ;;
        *) note "QL-G1 the debug retry's own client (read only where its base URL differs from the KYC path's): $(ql_say "$d"), unreadable $(ql_n "$d" unread), unclassified $(ql_n "$d" other)$( [ "$(ql_bk "$d")" = "0" ] || echo " — broken: $(ql_why "$(ql_of "$r" dbg)")") — a note, never toward the NO-GO (docs/71 §Q D-R4)" ;;
      esac ;;
    *) why=""
      case "$c" in nolib) why=": the pin's code has no lib/UcrmQuoteLines.php or no lib/UcrmQuoteLinks.php" ;; nooffer) why=": the rows the form offers, or the copy's link records, were not read from the copy" ;; '?'*) why=": the resolver threw" ;; esac
      stop "NO-GO (QL-G1): the catalogue could not be resolved on the copy (${c:-not read}$why). No flag lifts it. Nothing was changed. Send the log file" ;;
  esac
  # QL-N1 — the salesPerson client attribute (docs/71 §I, §M step 2), through the plugin's own client: its id alone. With
  # no quoting organization in force (Q-G3) the release sets no "Prepared by" at all — UcrmClientTarget's lookup and its
  # PATCH return first, and their two callers run only with the gate on: the attribute is said, its use is not (E2-1,
  # review 2; the probe's qlattrrel is then "off").
  a="$(kv "$QO_R" qlattr)"; QLATTR_A="$a"; x="$(kv "$QO_R" qlattrrel)"
  if [ "$c" = "off" ] || [ "$x" = "off" ]; then note "QL-N1 the client attribute keyed salesPerson: $(ql_attr_say "$a") — not used: no quoting organization is in force (Q-G3), so $EXPECTED_VERSION sets no \"Prepared by\" on a new KYC customer; it does so only where the quoting organization is in force (docs/71 §I, D7)"
  else
  case "$a" in
    one:1) note "QL-N1 the client attribute keyed salesPerson: exactly one, #1 — the release never uses id 1, so \"Prepared by\" is not set on a new KYC customer; the release's own lookup answers ${x:-?} (docs/71 §I)" ;;
    one:*) note "QL-N1 the client attribute keyed salesPerson: exactly one, #${a#one:} — \"Prepared by\" is PATCHed on each new KYC customer after its create and the company check (docs/71 §I); the release's own lookup (UcrmClientTarget::salesPersonFieldId) answers $( [ "$x" = "${a#one:}" ] && echo "the same" || echo "${x:-?}, not the same: say so with the log file")" ;;
    absent) note "QL-N1 no client attribute is keyed salesPerson in uCRM — \"Prepared by\" is not set on new KYC customers until one is: add the \"Sales Person\" client attribute, its key exactly salesPerson (docs/71 §M step 2)" ;;
    ambig:*) note "QL-N1 ${a#ambig:} client attributes are keyed salesPerson — ambiguous: the release sets none of them, so \"Prepared by\" is not set; keep exactly one (docs/71 §M step 2)" ;;
    *) note "QL-N1 the salesPerson attribute could not be read through the plugin's own client (${a:-not read}) — said, never a reason to stop" ;;
  esac
  fi
  # QL-N2 — quotation 000314, read back (docs/71 §N): per item its type, whether it carries a productId, whether a unit.
  q="$(kv "$QO_R" ql314)"
  case "$q" in
    notfound) note "QL-N2 quotation 000314: not found in the book — no application holds it as its quote number with a quote id; no request was made" ;;
    ambig:*) note "QL-N2 quotation 000314: ${q#ambig:} quote ids are stored under that quote number — ambiguous; none was read" ;;
    read:*) note "QL-N2 quotation 000314, read back once through the plugin's own client (GET billing/quotes/{the quote id its application stores}): $(ql_q314_say "$q") — the first measurement of what uCRM does with a line (docs/71 §N); never a label or a price, the units on the sheet" ;;
    *) note "QL-N2 quotation 000314 could not be read back (${q:-not read}) — said, never a reason to stop" ;;
  esac
  # QL-N3 — Q-N4 extended, by line shape and sale type. With the quoting organization in force, also the applications
  # the retry cannot price after the deploy whatever uCRM holds and whatever an admin links (D11, docs/71 §F.4; D14 E-1:
  # the release's entry rule comes first, so every one with no quotation made and quote_sale_entry neither web nor
  # web-direct — the probe's qln3d11, kept in QLN3_D11_A); since 5.18.103 (docs/72 §G.13) its own mark is counted
  # apart from 5.18.102's — both are the live code's (5.18.103's writes 5.18.102's while the uCRM catalogue's switch is
  # off, its own while it is on), neither a rolled-back run's; with none in force the retry quotes them as 5.18.102
  # does (D7; E2-1, review 2).
  q="$(kv "$QO_L" qln3)"; QLN3_D11_A="$(kv "$QO_L" qln3d11)"
  case "$q" in
    ''|'?'*) note "QL-N3 the pending and review applications could not be counted by line shape (${q:-not read}) — said, never a reason to stop" ;;
    *) x="$(printf '%s' "$q" | tr ',' '\n' | awk -F'[.:]' '$2 == "marked" { m += $5 } END { print m + 0 }')"
      z="$(printf '%s' "$q" | tr ',' '\n' | awk -F'[.:]' '$2 == "direct" { m += $5 } END { print m + 0 }')"
      y="pending $(ql_n3_say "$q" pending); review $(ql_n3_say "$q" review) — $x carry 5.18.102's mark (quote_lines_source 'ucrm-5.18.102': priced at its KYC form through a link — 5.18.102's, or 5.18.103's with its uCRM catalogue's switch off; under D6 nothing is linked, docs/72 G-10); $z carry 5.18.103's own (ucrm-direct-5.18.103): priced direct sales, made with the uCRM catalogue's switch on"
      if [ "$c" = "off" ]; then note "QL-N3 Q-N4 by line shape and sale type — the applications saved here and not yet in uCRM: $y. With no quoting organization in force (Q-G3) the retry quotes them after the deploy as $BASELINE_VERSION does: nothing is priced from uCRM (D7)"
      else note "QL-N3 Q-N4 by line shape and sale type — the applications saved here and not yet in uCRM: $y. After the deploy $EXPECTED_VERSION retries them exactly as $BASELINE_VERSION does: a web registration of 5.18.102's form (quote_sale_entry web) through the links — with the uCRM catalogue's switch on, one unpriced is quoted in uCRM by hand, QC-N4; a direct sale (web-direct, made with the switch on) by its stored uCRM ids; and none of the others from uCRM: the entry rule comes first (docs/71 E-1, §R.4.2). $(ql_d11_say "$QLN3_D11_A")"; fi ;;
  esac
  # QL-N4 — the last 90 days by entry point; QL-N5 — the newest plan save and kit, as dates.
  q="$(kv "$QO_L" qln4)"
  note "QL-N4 KYC applications of the last 90 days (submitted_at): $(subkv "$q" all) — of them an existing customer's $(subkv "$q" existing) (a request carrying a customer_id: crm_client_type existing); the entry point of the rest is not measurable, the record carries none$( [ "$(subkv "$q" nodate)" = "0" ] || echo "; $(subkv "$q" nodate) with no date, not counted")"
  q="$(kv "$QO_L" qln5)"
  note "QL-N5 the newest plan save (subscription_plans updated_at) $(subkv "$q" plan), the newest kit added (kyc_devices created_at) $(subkv "$q" kit) — dates only; a kit edit writes nothing, and a product push is not recorded by the plugin"
  # QL-N6 — the settings the customer's notes and P3 read, set or unset: Q-N1's own reading (qn1_state, read-only, the
  # pin's code), kept by qo_stage — the live configuration is not read a second time.
  q="${QL_QN1:-}"; x="$(kv "$q" qln6)"
  case "$x" in
    prefix:*) note "QL-N6 the settings the customer's notes and P3 read (the configuration files/the store row; the KYC path reads the store row): kyc_quote_notes_prefix $(subkv "$x" prefix) — on Uganda it becomes the quotation's notes, which the customer sees (docs/71 §F.1, §M step 4); kyc_auto_quote_enabled $(subkv "$x" auto); kyc_auto_quote_max_amount $(subkv "$x" max) — a quotation over it is not made (P3)" ;;
    *) note "QL-N6 the settings could not be read read-only (${q:-?}) — said, never a reason to stop" ;;
  esac
  # QL-N7 — the active kyc_packages rows through the same resolver, as planLine($row, 'package'): a note (docs/71 §Q
  # D-R4). 5.18.102 D14 (§R.2.5, derivation M-19): on Uganda each is a retailer-app package, never priced from uCRM.
  q="$(kv "$QO_R" qlpk)"
  case "$c" in
    off) note "QL-N7 not asked: no quoting organization is in force (Q-G3)" ;;
    *) p="$(ql_of "$q" plug)"; t="$(ql_of "$q" tok)"
      note "QL-N7 the active kyc_packages rows — offered by the retailer app and the mobile API, never by the KYC form, and on Uganda never priced from uCRM: each is a retailer-app package, which is not linked to uCRM (docs/71 §R.2.5) — through the plugin's own client $(ql_pk_say "$p")$( [ "$t" = "unset" ] || echo "; through the token client $(ql_pk_say "$t")") — a note, never toward the NO-GO (docs/71 §Q D-R4); names on the sheet" ;;
  esac
  return 0
}
# ql_after INST_ROOT — QL-CA2 after the copy (stage R; --after-only too), on qo_after's reading (qo_run r: the INSTALLED
# code, a copy of it, ICODE_R, and uCRM with GETs only). Reports; never stops. 5.18.102's QL-CA1 — the installed
# resolver's verdicts against stage A's, item by item, and the items still to link — is retired since 5.18.103 (docs/72
# §G.13): with the uCRM catalogue on, links decide nothing, and QC-CA1 compares what the forms offer instead.
ql_after() {
  local inst="$1" a rel ok_r=""
  case "$QO_KIND:$QO_R" in r:*" gets="*" other="*) ok_r=1 ;; esac
  # QL-CA2 — the salesPerson attribute again, through the installed code's reading (a note when it differs). With no
  # quoting organization in force through the installed code (the probe's qlattrrel "off"), the installed release sets
  # no "Prepared by": a note, never an ok (E2-1, review 2).
  a="$( [ -n "$ok_r" ] && [ -n "$inst" ] && kv "$QO_R" qlattr)"; rel="$( [ -n "$ok_r" ] && [ -n "$inst" ] && kv "$QO_R" qlattrrel)"
  if [ -z "$a" ]; then note "QL-CA2 the salesPerson attribute was not read after the copy"
  elif [ "$rel" = "off" ]; then note "QL-CA2 the client attribute keyed salesPerson, through the installed code's reading: $(ql_attr_say "$a") — not used: no quoting organization is in force (Q-CA2), so $EXPECTED_VERSION sets no \"Prepared by\" on a new KYC customer$( [ -n "$QLATTR_A" ] && [ "$a" != "$QLATTR_A" ] && echo "; stage A read $(ql_attr_say "$QLATTR_A")")"
  elif [ -z "$QLATTR_A" ]; then note "QL-CA2 the client attribute keyed salesPerson, through the installed code's reading: $(ql_attr_say "$a") — stage A's answer is not known to this run$( [ "$MODE" = "after" ] && echo " (the state file $STATE holds none)")"
  elif [ "$a" = "$QLATTR_A" ]; then
    case "$a" in
      one:1) note "QL-CA2 the client attribute keyed salesPerson reads as stage A read it: exactly one, #1 — an id the release never uses, so \"Prepared by\" is not set (docs/71 §M step 2)" ;;
      one:*) if [ "$rel" != "off" ] && [ "$rel" = "${a#one:}" ]; then ok "QL-CA2 the client attribute keyed salesPerson reads as stage A read it: exactly one, #${a#one:} — the installed release's own lookup answers the same: \"Prepared by\" is set on each new KYC customer"
             else note "QL-CA2 the client attribute keyed salesPerson reads as stage A read it (exactly one, #${a#one:}), and the installed release's own lookup answers ${rel:-?} — say so with the log file"; fi ;;
      *) note "QL-CA2 the client attribute keyed salesPerson reads as stage A read it: $(ql_attr_say "$a") — \"Prepared by\" is not set until there is exactly one (docs/71 §M step 2)" ;;
    esac
  else note "QL-CA2 the client attribute keyed salesPerson now reads $(ql_attr_say "$a"); stage A read $(ql_attr_say "$QLATTR_A") — the operator adds or changes it in uCRM (docs/71 §M step 2), never this run, which asked uCRM nothing but GETs"; fi
  return 0
}
# (5.18.102's ql_lk1 — QL-LK1, an --after-only's judgement of the links — is retired since 5.18.103, docs/72 §G.13: with the
# uCRM catalogue on links decide nothing, and under D6 every item stays unlinked, so it would fail every run.)
# ql_ca3_txt pin|inst — QL-CA3's text read (docs/71 §R.7.6 item 2): includes/post/post_sync.php's three blocks D14 adds,
# whole-line comments aside (sec_src, sec_block, sec_code — the readers 5.18.95's checks use). Each block is found by its
# own first line, a POST with that action, so POST-only, and that line must be the file's one code line naming the
# action. The gate's condition — QuoteOrganization::setting(...)['on'] — at the block's first level, every line after it
# one level in, up to the gate's close, the block's last two lines; then $auth->requireAdmin(), the account's fresh
# re-read written in the action itself ($store->findOne('retailers.json', 'id', …)) and the own-page check (csrfCheck() &&
# !CustomerSession::crossSite() && BankGate::fromOwnPage('POST')), in that order, each before the block's first act — a
# UcrmQuoteLinks:: or makeQuotation( call (case-sensitive: canMakeQuotation( is not one), or a $store-> call other than
# that re-read — and the block's own act present. Prints "ok", or "<action>:<fixed word>" for each that fails, never a
# line of the code. The caller reads the pin's file from Git the same way, the control: a reader, a path or a needle that
# could not see the release would pass any installed file, so the check refuses unless the pin reads "ok".
ql_ca3_txt() {
  local src code act need w="" one
  src="$(sec_src "$1" includes/post/post_sync.php)"
  [ -n "$src" ] || { echo nofile; return 0; }
  code="$(printf '%s\n' "$src" | sec_code)"
  for act in ucrm_link_save ucrm_link_clear kyc_make_quote; do
    case "$act" in kyc_make_quote) need="makeQuotation(" ;; *) need="UcrmQuoteLinks::" ;; esac
    one="$(grep -cF -- "'$act'" <<<"$code" || true)"
    [ "$one" = "1" ] || w="$w $act:named-on-${one:-?}-code-lines"
    w="$w$(printf '%s\n' "$src" | sec_block "if (\$_SERVER['REQUEST_METHOD'] === 'POST' && (\$_POST['action'] ?? '') === '$act') {" | sec_code \
      | QA_NAME="$act" QA_ACT="$need" QA_GATE="    if (QuoteOrganization::setting(" QA_ON="['on']) {" QA_RA="\$auth->requireAdmin()" QA_FR="\$store->findOne('retailers.json', 'id', " \
        QA_CS="csrfCheck() && !CustomerSession::crossSite() && BankGate::fromOwnPage('POST')" awk '
        { L[NR] = $0 }
        END {
          a = ENVIRON["QA_NAME"]; w = ""
          if (NR < 3) { printf " %s:noblock", a; exit }
          g = 0; ra = 0; fr = 0; cs = 0; fa = 0; own = 0
          for (i = 2; i <= NR; i++) {
            s = L[i]
            if (!g && index(s, ENVIRON["QA_GATE"]) == 1 && index(s, ENVIRON["QA_ON"]) > 0) g = i
            if (!ra && index(s, ENVIRON["QA_RA"]) > 0) ra = i
            if (!fr && index(s, ENVIRON["QA_FR"]) > 0) fr = i
            if (!cs && index(s, ENVIRON["QA_CS"]) > 0) cs = i
            if (!fa && (index(s, "UcrmQuoteLinks::") > 0 || index(s, "makeQuotation(") > 0 || (index(s, "$store->") > 0 && index(s, ENVIRON["QA_FR"]) == 0))) fa = i
            if (index(s, ENVIRON["QA_ACT"]) > 0) own++
          }
          if (!g) w = w " " a ":no-gate"
          else {
            if (L[NR - 1] != "    }" || L[NR] != "}") w = w " " a ":the-gate-does-not-close-the-block"
            for (i = g + 1; i <= NR - 2; i++) if (L[i] !~ /^[ \t]*$/ && L[i] !~ /^        /) { w = w " " a ":a-line-outside-the-gate"; break }
          }
          if (!ra) w = w " " a ":no-requireAdmin"
          if (!fr) w = w " " a ":no-fresh-re-read"
          if (!cs) w = w " " a ":no-own-page-check"
          if (!own) w = w " " a ":no-" (ENVIRON["QA_ACT"] == "makeQuotation(" ? "makeQuotation" : "UcrmQuoteLinks") "-call"
          if (g && ra && fr && cs) {
            if (!(g < ra && ra < fr && fr < cs)) w = w " " a ":out-of-order"
            if (fa && fa < cs) w = w " " a ":an-act-before-the-checks"
          }
          printf "%s", w
        }')"
  done
  sec_say "$w"
}
# ql_ca3_map pin|inst — QL-CA3's third reading (docs/71 §R.7.6 item 3, optional, taken): includes/api/api_products_admin.php's
# admin-only gate ($_gateAdminOnly, read as Q-CA4 reads it, comments aside) must name auto_map_products and
# set_product_mapping, whose Uganda refusal (409, §R.2.6) comes only after that gate. Prints "ok" or fixed words.
ql_ca3_map() {
  local g w=""
  g="$(sec_src "$1" includes/api/api_products_admin.php | awk '/\$_gateAdminOnly *= *\[/ { p = 1 } p && /\];/ { exit } p' | sec_code)"
  [ -n "$g" ] || { echo noblock; return 0; }
  sec_has "$g" "'auto_map_products'," || w="$w no-auto_map_products"
  sec_has "$g" "'set_product_mapping'," || w="$w no-set_product_mapping"
  sec_say "$w"
}
# ── 5.18.103: what the forms offer from uCRM in direct mode (QC; root docs/72 §G.13) ─────────────────────────────────────
# The readings are qo_run's (the probe's "qc" parts: on the copy, the uCRM catalogue's records through the RELEASE's
# lib/UcrmCatalogue.php by its own path; from uCRM, GET-only, the RELEASE's UcrmQuoteLines::offered() over them — the pin's
# at stage A, the INSTALLED code after the copy). Counts, read states, HTTP codes and fixed why codes in the log; names,
# uCRM ids, prices and reasons on the sheet; each item's verdict as a keyed hash under the QL key, never printed.
qc_well() { local f; for f in sp pr plans hw not unread other; do [ -n "$(ql_n "$1" "$f")" ] || return 1; done; return 0; }   # qc_well PART — qcc's seven counts
qc_say() { printf '%s service plan(s) and %s product(s) counted; offered %s plan(s) and %s hardware item(s); %s not offered' "$(ql_n "$1" sp)" "$(ql_n "$1" pr)" "$(ql_n "$1" plans)" "$(ql_n "$1" hw)" "$(ql_n "$1" not)"; }
qc_why_say() {   # qc_why_say PART — qcwhy's "why.n+…" (the release's fixed codes) in words
  case "$1" in ''|none) printf 'none'; return 0 ;; esac
  printf '%s\n' "$1" | tr '+' '\n' | awk -F. '
    { w = $1
      if (w == "plan_rows") w = "200 service plans or more"; else if (w == "unlisted") w = "no longer listed"
      else if (w == "plan_twin") w = "a service plan spelled like another"; else if (w == "no_month") w = "no 1-month price"
      else if (w == "plan_price") w = "a service plan priced other than its 1-month price"
      else if (w == "plan_no_product") w = "no product spelled like the service plan"; else if (w == "plan_two_products") w = "two products spelled like the service plan"
      else if (w == "bad") w = "no usable price, taxable, or an invoice label unlike its name"; else if (w == "price_differs") w = "a product price unlike its service plan"
      else if (w == "spelled_apart") w = "product and service plan spelled apart"; else if (w == "like_plan") w = "hardware spelled like a service plan"
      else if (w == "kept_off") w = "kept off by an admin"; else if (w == "archived") w = "archived"; else if (w == "inactive") w = "not active"
      else if (w == "organization") w = "another organization'"'"'s"; else if (w == "other") w = "UNCLASSIFIED"
      printf "%s%s %s", (n++ ? ", " : ""), $2, w }
    END { if (!n) printf "none" }'
}
qc_cmp() {   # qc_cmp STAGE_A NOW — two "<H>:<H>,…" lists (or none) compared by key: "same:<n>,differs:<n>,new:<n>,gone:<n>"
  awk -v a="$1" -v b="$2" 'BEGIN {
    na = (a == "none" || a == "") ? 0 : split(a, x, ","); nb = (b == "none" || b == "") ? 0 : split(b, y, ",")
    for (i = 1; i <= na; i++) A[substr(x[i], 1, 32)] = substr(x[i], 34)
    for (i = 1; i <= nb; i++) { k = substr(y[i], 1, 32); v = substr(y[i], 34); if (k in A) { if (A[k] == v) s++; else d++; seen[k] = 1 } else n++ }
    for (k in A) if (!(k in seen)) g++
    printf "same:%d,differs:%d,new:%d,gone:%d", s, d, n, g }'
}
qc_cmp_say() { printf '%s compared — the same %s, different %s; not offered or left out at stage A %s, at stage A and not now %s' "$(( $(ql_n "$1" same) + $(ql_n "$1" differs) ))" "$(ql_n "$1" same)" "$(ql_n "$1" differs)" "$(ql_n "$1" new)" "$(ql_n "$1" gone)"; }
qc_inst_say() { case "$1" in ok) echo "set, and passing" ;; unset) echo "not set" ;; unread) echo "not read (uCRM unreadable)" ;; unset*|'') echo "${1:-not read}" ;; *) echo "set, and not passing ($(qc_why_say "$1.1" | sed 's/^1 //'))" ;; esac; }
# qc_stage — QC-G1 and QC-N1–QC-N7, stage A (a deploy and --check), on qo_stage's reading (qo_run a: the PIN's code from
# Git — its UcrmQuoteLines and, by that file's own path, its lib/UcrmCatalogue.php — on the copies, and uCRM with GETs
# only, in the probe whose requests Q-G4's refusal counted). Direct mode lives under the quoting organization (D7): with
# none in force QC-G1 is a note. QC-G1 refuses — no flag lifts it — an unreadable catalogue through the plugin's own client
# or, when crm_auth_token is set, the token client; an answer this script cannot classify ("other": a why code outside the
# release's set, or an empty reason); a request but the two lists; the catalogue's settings on the copy unread, or the pin
# without its lib/UcrmCatalogue.php; the items' keyed hashes not made (QC-CA1 compares them after the copy). Every count
# of what is offered is a note: 5.18.105 changes nothing of the catalogue, and QC-CA1 compares it after the copy.
# Sets QC_A (QC-G1's counts
# by client), QC_I_A (each item's keyed hash with its verdict's, under the QL key: never printed), QCSW_A and QCCAT_A (the
# switch and the catalogue's records on stage A's copy) — for QC-CA1 after the copy and, through the state file, a later
# --after-only's.
QC_A=""; QC_I_A=""; QCSW_A=""; QCCAT_A=""
qc_stage() {
  local c p t x lt w s i k
  case "$QO_KIND:$QO_R" in a:*" gets="*" other="*) ;; *) stop "NO-GO (QC-G1): stage A's quoting reading is not in this run (${QO_KIND:-none}) — what the forms would offer from uCRM cannot be judged. Nothing was changed. Send the log file" ;; esac
  c="$(kv "$QO_R" qcc)"; lt="$(kv "$QO_L" qccat)"; QCCAT_A="$lt"; QCSW_A="$(kv "$QO_L" qcsw)"
  case "$c" in
    off) QC_A="off"
      note "QC-G1 not asked: no quoting organization is in force (Q-G3) — the uCRM catalogue lives under it, so $EXPECTED_VERSION then offers nothing from uCRM and its screen is not shown (docs/72 §G.10)" ;;
    plug:*)
      x="$(kv "$QO_R" qcpath)"
      [ "$x" = "ok" ] || stop "NO-GO (QC-G1): the RELEASE's offered() asked uCRM, through $(ql_who "${x#bad:}"), for something other than its two lists once each (GET products?limit=500, then GET service-plans?limit=500) — the code is not the one this script was reviewed against; the wrapper let only GETs through. No flag lifts it. Nothing was changed. Send the log file"
      p="$(ql_of "$c" plug)"; t="$(ql_of "$c" tok)"
      qc_well "$p" || stop "NO-GO (QC-G1): what the forms would offer could not be counted through the plugin's own client ($c). No flag lifts it. Nothing was changed. Send the log file"
      if [ "$QO_TOK" = "token=unset" ]; then [ "$t" = "unset" ] || stop "NO-GO (QC-G1): crm_auth_token is unset, and the probe read the catalogue through a token client ($t). Nothing was changed. Send the log file"
      else qc_well "$t" || stop "NO-GO (QC-G1): crm_auth_token is set, and what the forms would offer could not be counted through the token client (${t:-none}). No flag lifts it. Nothing was changed. Send the log file"; fi
      [ "$(ql_n "$p" unread)" = "0" ] || stop "NO-GO (QC-G1): uCRM's Products and Service Plans could not be read through the plugin's own client, GET-only ($(ql_rd "$(ql_of "$(kv "$QO_R" qcread)" plug)")) — the uCRM catalogue screen, Send Quotation and the lead quotes read them so. No flag lifts it. Nothing was changed. Send the log file"
      [ "$t" = "unset" ] || [ "$(ql_n "$t" unread)" = "0" ] || stop "NO-GO (QC-G1): uCRM's Products and Service Plans could not be read through the token client (crm_auth_token), GET-only ($(ql_rd "$(ql_of "$(kv "$QO_R" qcread)" tok)")) — the KYC form, the submission and the retries read them so. No flag lifts it. Nothing was changed. Send the log file"
      w=$(( $(ql_n "$p" other) + $( [ "$t" = "unset" ] && echo 0 || ql_n "$t" other ) ))
      [ "$w" = "0" ] || stop "NO-GO (QC-G1): $w answer(s) of the RELEASE's offered() cannot be classified (\"other\": a why code outside the release's set, or an empty reason) — the release's words and this script's disagree; each is on the sheet, verbatim (less $SHEET). No flag lifts it. Nothing was changed. Send the log file"
      # The settings' own refusals (?nocat, ?created, a reading that threw) are in the *) branch below: a local reading other
      # than absent or records leaves the remote reading without them (qcc=nooffer), so they never reach this branch.
      ql_hl_ok i "$QO_QCI" || stop "NO-GO (QC-G1): the items' keyed hashes were not made ($(ql_hl_say "$QO_QCI")) — QC-CA1 would have nothing to compare after the copy, item by item. Nothing was changed. Send the log file"
      QC_A="$c"; QC_I_A="$QO_QCI"
      ok "QC-G1 what the forms would offer in direct mode is read and judged through the RELEASE's UcrmQuoteLines::offered() on a copy, GET-only — GET products?limit=500, then GET service-plans?limit=500, nothing else — with the copy's catalogue settings ($( [ "$lt" = "absent" ] && echo "none: the table was never written on this book" || echo "$(ql_n "$lt" records) record(s), $(ql_n "$lt" inforce) in force")), every answer classified by the release's why codes: through the plugin's own client $(qc_say "$p")$( [ "$t" = "unset" ] && echo " (crm_auth_token unset)" || echo "; through the token client $(qc_say "$t")"); per item its name, uCRM ids, price and unit, or its reason, on the sheet"
      note "QC-G1 not offered, by why — through the plugin's own client: $(qc_why_say "$(ql_of "$(kv "$QO_R" qcwhy)" plug)")$( [ "$t" = "unset" ] || echo "; through the token client: $(qc_why_say "$(ql_of "$(kv "$QO_R" qcwhy)" tok)")") — each one's reason says its remedy in uCRM (docs/72 §G.4); a note, never toward the NO-GO"
      [ "$(ql_n "$p" plans)" != "0" ] || note "QC-G1 no plan is offered from uCRM through the plugin's own client: $( [ "$QCSW_A" = "on" ] && echo "the switch is on, so the forms that read uCRM through that client offer no plan from uCRM now, under $BASELINE_VERSION$( [ "$t" = "unset" ] || echo " (the KYC form reads with the token client: its count is above)") — each service plan's reason is on the sheet; $EXPECTED_VERSION changes nothing of the catalogue" || echo "the uCRM catalogue screen refuses to turn the switch on until one is (each service plan's reason is on the sheet); $EXPECTED_VERSION changes nothing of the catalogue")" ;;
    *) if [ "$c" = "nooffer" ]; then case "$lt" in
           '?nocat') stop "NO-GO (QC-G1): the quoting organization is in force, and the RELEASE's lib/UcrmCatalogue.php was not where the local reading loads it, the pin's own file by its path (?nocat) — the catalogue's settings on the copy cannot be read. No flag lifts it. Nothing was changed. Send the log file" ;;
           '?created') stop "NO-GO (QC-G1): reading the uCRM catalogue's settings on the copy created their table (?created) — the release's reader never does: the pin's code is not the one reviewed. No flag lifts it. Nothing was changed. Send the log file" ;;
           '?'*) stop "NO-GO (QC-G1): the uCRM catalogue's settings on the copy could not be read through the pin's UcrmCatalogue (${lt:-not read}). No flag lifts it. Nothing was changed. Send the log file" ;;
         esac; fi
       stop "NO-GO (QC-G1): what the forms would offer could not be read on the copy (${c:-not read}$(case "$c" in nolib) echo ": the pin's code has no lib/UcrmQuoteLines.php or no lib/UcrmCatalogue.php" ;; nooffer) echo ": the copy's catalogue settings, stock categories or public_price_exclude were not read" ;; '?'*) echo ": the reading threw" ;; esac)). No flag lifts it. Nothing was changed. Send the log file" ;;
  esac
  # QC-N1 — the switch as stored on stage A's copy, a note either way: on is an admin's choice on the uCRM catalogue
  # screen (5.18.103's, kept byte for byte), and the copy changes nothing of it. With no quoting organization in force
  # the switch is not read (it lives under it).
  if [ "$c" = "off" ]; then note "QC-N1 the uCRM catalogue's switch not read: no quoting organization is in force (Q-G3) — the switch lives under it"
  else
  case "$QCSW_A" in
    on) note "QC-N1 the uCRM catalogue's switch on stage A's copy: on, as an admin set it on the uCRM catalogue screen (5.18.103's; docs/72 §G.3) — the KYC form, Send Quotation and the lead quotes already offer uCRM's plans and hardware, and the plugin's Plans and Hardware are hidden. $EXPECTED_VERSION changes nothing of the catalogue, so after the copy agents see what they see now, and a rollback of $EXPECTED_VERSION leaves the switch as it is" ;;
    off|none) note "QC-N1 the uCRM catalogue's switch on stage A's copy: $( [ "$QCSW_A" = "none" ] && echo "never set" || echo "off, as an admin left it") — the forms offer the plugin's own plans and kits, priced through the uCRM item linked to each, as $BASELINE_VERSION does with the switch off; $EXPECTED_VERSION changes nothing of the catalogue, so turning the switch on, under either release, is an admin's step on the uCRM catalogue screen when it allows (docs/72 §G.3)" ;;
    two) note "QC-N1 two switch records are in force on stage A's copy — the release reads that as off (it never writes two); an admin sets it again on the uCRM catalogue screen" ;;
    *) note "QC-N1 the uCRM catalogue's switch could not be read on the copy (${QCSW_A:-not read}) — said, never a reason to stop" ;;
  esac
  fi
  # QC-N2 — the installation product and the standard quotations, on the copy, judged through the pin's offered().
  case "$c" in
    off) ;;
    *) i="$(kv "$QO_R" qcinst)"; s="$(kv "$QO_R" qcstd)"
      note "QC-N2 the installation product (the copy's: $(kv "$QO_L" qcinst)): through the plugin's own client $(qc_inst_say "$(ql_of "$i" plug)")$( [ "$QO_TOK" = "token=unset" ] || echo "; through the token client $(qc_inst_say "$(ql_of "$i" tok)")") — while it is not set, or not passing, a sale DishNet installs is unpriced in direct mode (the agent is told; P1); standard quotations defined and usable now: $(ql_of "$s" plug | sed 's#/# defined, #; s#$# usable#')$( [ "$QO_TOK" = "token=unset" ] || echo " (the token client: $(ql_of "$s" tok | sed 's#/# defined, #; s#$# usable#'))") — each on the sheet" ;;
  esac
  # QC-N3 — F11's measure (docs/72 §G.11): the applications by entry; QC-N4 — 5.18.102's web applications refused P1 with
  # no quotation, which an admin quotes by hand once the switch is on (G-10).
  x="$(kv "$QO_L" qcentry)"
  case "$x" in
    web:*) note "QC-N3 the applications by entry (quote_sale_entry, which every application saved since 5.18.102's copy carries): web $(subkv "$x" web) (the KYC form with the uCRM catalogue's switch off: 5.18.102, 5.18.103 or later), app $(subkv "$x" app) (the retailer app, the mobile API, a form opened before 5.18.102's copy, or a KYC form drawn with the switch off and sent once it was on: G-9), web-direct $(subkv "$x" direct) (the KYC form with the switch on, since 5.18.103), none $(subkv "$x" none) (saved before 5.18.102's copy, or while no quoting organization was in force)$( [ "$(subkv "$x" other)" = "0" ] || echo ", another value $(subkv "$x" other)") — F11's measure (docs/72 §G.11): the retailer app and the mobile API stay on the plugin's own lists in $EXPECTED_VERSION; if agents use them, moving them to the uCRM catalogue is the next step" ;;
    *) note "QC-N3 the applications could not be counted by entry (${x:-not read}) — said, never a reason to stop" ;;
  esac
  x="$(kv "$QO_L" qcwebp1)"
  case "$x" in
    0) note "QC-N4 no web application of $BASELINE_VERSION is waiting with P1 and no quotation" ;;
    [0-9]*) note "QC-N4 $x web application(s) (quote_sale_entry web: the KYC form under 5.18.102, or under 5.18.103 or 5.18.104 with the uCRM catalogue switch off) refused P1 with no quotation — under $EXPECTED_VERSION, as under $BASELINE_VERSION: with the switch off, Make the quotation applies to them as before once their items are linked; with the switch on, an admin quotes each in uCRM by hand, as its Orders card says (docs/72 G-10), but first checks in uCRM that the customer has no quotation yet. Ids on the sheet" ;;
    *) note "QC-N4 the waiting web applications could not be counted (${x:-not read})" ;;
  esac
  # QC-N5 — offered hardware with no active stock category of its title (the stock deduction matches by title, §G.7);
  # QC-N6 — offered items public_price_exclude names (a hint: the forms never read that list, G-5); QC-N7 — the plugin's
  # active plans by type, none of which direct mode draws.
  case "$c" in
    off) ;;
    *) x="$(ql_of "$(kv "$QO_R" qcstock)" plug)"
      case "$x" in
        0) note "QC-N5 every hardware item offered through the plugin's own client has an active stock category of the same title ($(kv "$QO_L" qcstock))" ;;
        [0-9]*) note "QC-N5 $x hardware item(s) offered from uCRM have no active stock category of the same title ($(kv "$QO_L" qcstock)) — a direct sale's cart carries uCRM's names, so a completed job deducts nothing for such an item (\"No stock category found\"): title those categories as uCRM names the products (docs/72 §G.7); names on the sheet" ;;
        *) note "QC-N5 the stock categories could not be compared (${x:-not read}; $(kv "$QO_L" qcstock))" ;;
      esac
      x="$(ql_of "$(kv "$QO_R" qcppx)" plug)"
      case "$x" in
        0) note "QC-N6 public_price_exclude ($(kv "$QO_L" qcppx)) names none of the items offered from uCRM" ;;
        [0-9]*) note "QC-N6 public_price_exclude ($(kv "$QO_L" qcppx)) names $x item(s) offered from uCRM — the website hides them, the forms do not read that list (docs/72 G-5): an admin keeps one off on the uCRM catalogue screen if it is not to be sold; names on the sheet" ;;
        *) note "QC-N6 public_price_exclude could not be compared (${x:-not read}; $(kv "$QO_L" qcppx))" ;;
      esac ;;
  esac
  x="$(kv "$QO_L" qcplantype)"
  note "QC-N7 the plugin's own active plans by type: $(printf '%s' "${x:-not read}" | sed 's/:/ /g; s/,/, /g') — with the switch on none of them is drawn: the KYC form offers uCRM's service plans with their products, so a plan sold from the plugin's list today (an LTE or SIM one among them) must exist in uCRM as a service plan with its product to be offered"
  return 0
}
# qc_after INST_ROOT — QC-CA1 after the copy (stage R; --after-only too), on qo_after's reading (qo_run r: the INSTALLED
# code's offered(), a copy of it, ICODE_R, over a fresh copy's catalogue settings, uCRM with GETs only). In the deploy run
# every item's verdict must equal stage A's, item by item, under the QL key — unless the catalogue's records changed since
# stage A (an admin used the uCRM catalogue screen while the run printed), then the comparison is a note naming that; in
# an --after-only run (the state file's hashes, the key file's key) a note. An unreadable catalogue, an unclassified
# answer, the settings unread, a request but the two lists or any request but a GET fails. Then, in an --after-only run
# only, the switch as found (docs/72 §G.13): on, QC-ON1 says so and QC-ON2 the installation product set and passing and
# QC-ON3 every standard quotation usable (none defined: a note) are judged; off or never set, an admin's choice, one note
# instead (two records in force, or a switch not read, fails QC-ON1); either way QC-ON4 G-7's invariant over the copy's
# web-direct records — package_choice '', device_id '' and only id 0 in hw_cart_json and quote_sale_cart; with no quoting
# organization in force QC-ON1–QC-ON3 are one note (direct mode lives under it). Reports; never stops.
qc_after() {
  local inst="$1" c p t x m lt ok_r="" i s n u g
  case "$QO_KIND:$QO_R" in r:*" gets="*" other="*) ok_r=1 ;; esac
  lt="$( [ -n "$ok_r" ] && kv "$QO_L" qccat)"
  if [ -z "$inst" ]; then bad "QC-CA1 the copy of the installed code was not made — what the forms offer is not read after the copy"
  elif [ -z "$ok_r" ]; then bad "QC-CA1 what the forms offer could not be read after the copy: the quoting checks' reading through the installed code did not complete (${QO_ERR:-Q-CA2 and Q-CA3 above say why})"
  else
    c="$(kv "$QO_R" qcc)"
    case "$c" in
      off) if [ -n "$QC_A" ] && [ "$QC_A" != "off" ]; then bad "QC-CA1 no quoting organization is in force through the installed code (Q-CA2), and stage A read the catalogue under one — the gate is not as stage A read it"
           else echo "  QC-CA1          not asked: no quoting organization is in force (Q-CA2) — the uCRM catalogue lives under it"; fi ;;
      plug:*)
        p="$(ql_of "$c" plug)"; t="$(ql_of "$c" tok)"; x=""
        [ "$(kv "$QO_R" qcpath)" = "ok" ] || x="$x offered() asked for something other than its two lists once each (through $(ql_who "$(kv "$QO_R" qcpath | sed 's/^bad://')"));"
        if ! qc_well "$p"; then x="$x the plugin's own client's counts not read ($p);"
        elif [ "$(ql_n "$p" unread)" != "0" ]; then x="$x unreadable through the plugin's own client ($(ql_rd "$(ql_of "$(kv "$QO_R" qcread)" plug)"));"
        elif [ "$(ql_n "$p" other)" != "0" ]; then x="$x $(ql_n "$p" other) unclassified answer(s) through the plugin's own client;"; fi
        if [ "$QO_TOK" = "token=unset" ]; then [ "$t" = "unset" ] || x="$x a token client's reading where crm_auth_token is unset ($t);"
        elif ! qc_well "$t"; then x="$x the token client's counts not read (${t:-none});"
        elif [ "$(ql_n "$t" unread)" != "0" ]; then x="$x unreadable through the token client ($(ql_rd "$(ql_of "$(kv "$QO_R" qcread)" tok)"));"
        elif [ "$(ql_n "$t" other)" != "0" ]; then x="$x $(ql_n "$t" other) unclassified answer(s) through the token client;"; fi
        case "$lt" in absent|records:*) ;; *) x="$x the catalogue's settings on the copy not read through the installed UcrmCatalogue (${lt:-not read});" ;; esac
        [ "$QO_OTHER" = "0" ] && [ -z "$QO_COUNT_BAD" ] || x="$x a request other than a GET was asked of uCRM (other $QO_OTHER;${QO_COUNT_BAD:- counted});"
        m=""; { [ -n "$QC_I_A" ] && ql_hl_ok i "$QC_I_A" && ql_hl_ok i "$QO_QCI"; } && m="$(qc_cmp "$QC_I_A" "$QO_QCI")"
        if [ -n "$x" ]; then bad "QC-CA1 what the forms offer, through the INSTALLED offered():${x%;} — each item by name on the sheet"
        elif [ "$MODE" = "deploy" ]; then
          if [ -z "$QC_I_A" ]; then bad "QC-CA1 stage A's verdicts are not known to this run$( [ "$QC_A" = "off" ] && echo " (stage A read none: no quoting organization was in force then, Q-G3)") — the installed code's: through the plugin's own client $(qc_say "$p")"
          elif [ -z "$m" ]; then bad "QC-CA1 what the installed code offers was not compared with stage A's, item by item: the hashes are not as written (stage A's $(ql_hl_say "$QC_I_A"), now $(ql_hl_say "$QO_QCI"))"
          elif [ "$(ql_n "$m" differs):$(ql_n "$m" new):$(ql_n "$m" gone)" = "0:0:0" ]; then
            ok "QC-CA1 the INSTALLED UcrmQuoteLines::offered(), on a fresh copy and GET-only, offers exactly what stage A's pin offered, item by item (compared under this run's QL key, never printed: $(qc_cmp_say "$m")) — the same plans and hardware at the same uCRM ids, prices and units, the same reason for each item left out; through the plugin's own client $(qc_say "$p")"
          elif [ "$lt" != "$QCCAT_A" ] || [ "$(kv "$QO_L" qcsw)" != "$QCSW_A" ]; then
            note "QC-CA1 what the installed code offers differs from stage A's, item by item ($(qc_cmp_say "$m")), and the uCRM catalogue's settings changed since stage A ($QCCAT_A, switch $QCSW_A → $lt, switch $(kv "$QO_L" qcsw)) — an admin used the uCRM catalogue screen while the run printed; each item on the sheet"
          else bad "QC-CA1 what the INSTALLED code offers is not what stage A's pin offered, item by item (compared under this run's QL key): $(qc_cmp_say "$m") — uCRM's Products or Service Plans changed while the deploy ran (a price, a name, an item archived), or the code differs from the one reviewed; each item by name on the sheet. Send the log file"; fi
        else
          ok "QC-CA1 what the forms offer, through the INSTALLED UcrmQuoteLines::offered() on a fresh copy, GET-only: through the plugin's own client $(qc_say "$p")$( [ "$t" = "unset" ] || echo "; through the token client $(qc_say "$t")"); not offered, by why: $(qc_why_say "$(ql_of "$(kv "$QO_R" qcwhy)" plug)")"
          if [ -n "$m" ]; then note "QC-CA1 against stage A's verdicts, item by item (the state file's hashes, under the deploy's QL key — never printed): $(qc_cmp_say "$m") — uCRM's catalogue and the uCRM catalogue screen's settings change between runs; each item on the sheet"
          else note "QC-CA1 stage A's verdicts could not be compared item by item ($( [ -z "$QC_I_A" ] && echo "the state file $STATE holds none, or the deploy's QL key file $QL_KEY_FILE is missing or not one QL_KEY= line of 48 hex" || echo "the hashes are not as written"))"; fi
        fi ;;
      *) bad "QC-CA1 what the forms offer could not be read through the installed code (${c:-not read})" ;;
    esac
  fi
  [ "$MODE" = "after" ] || return 0
  # QC-ON1–QC-ON4 — an --after-only run, the switch as found (docs/72 §G.13; DS5): off or never set, QC-ON1–QC-ON3 are
  # one note. With no quoting organization in force the switch, the installation and the standard quotations are not
  # asked (D7): one note.
  if [ -n "$ok_r" ] && [ "$(kv "$QO_R" qcc)" = "off" ]; then
    note "QC-ON1–QC-ON3 not asked: no quoting organization is in force (Q-CA2) — the uCRM catalogue lives under it, so $EXPECTED_VERSION quotes as $BASELINE_VERSION does with it off (D7), and its screen is not shown"
  else
  x="$( [ -n "$ok_r" ] && kv "$QO_L" qcsw)"
  if [ "$x" = "off" ] || [ "$x" = "none" ]; then
    note "QC-ON1–QC-ON3 not judged: the uCRM catalogue is switched off$( [ "$x" = "none" ] && echo " (never set)") on the copy — an admin's choice on the uCRM catalogue screen (docs/72 §G.3); the forms quote through the plugin's links, as $BASELINE_VERSION does with it off$( [ "${QCSW_A:-}" = "on" ] && echo "; it read on at the deploy's stage A")"
  else
  case "$x" in
    on) ok "QC-ON1 the uCRM catalogue is switched ON (the copy's record): the KYC form, Send Quotation and the lead quotes offer uCRM's plans and hardware on Uganda, and the plugin's Plans and Hardware are hidden" ;;
    *) bad "QC-ON1 the uCRM catalogue's switch reads neither on nor off on the copy (${x:-not read}: two records in force, which the release reads as off and never writes, or a reading that failed) — an admin sets it again on the uCRM catalogue screen (Uganda); then run --after-only again" ;;
  esac
  i="$( [ -n "$ok_r" ] && kv "$QO_R" qcinst)"
  case "$(ql_of "$i" plug)" in
    ok) [ "$QO_TOK" = "token=unset" ] || [ "$(ql_of "$i" tok)" = "ok" ] && ok "QC-ON2 the installation product is set and passes through the release's own rules$( [ "$QO_TOK" = "token=unset" ] || echo ", through the plugin's own client and the token client") — a sale DishNet installs carries it as a line" \
        || bad "QC-ON2 the installation product passes through the plugin's own client and not through the token client ($(qc_inst_say "$(ql_of "$i" tok)")) — the KYC form's submission reads with the token" ;;
    *) bad "QC-ON2 the installation product: $(qc_inst_say "$(ql_of "$i" plug)") — a sale DishNet installs is unpriced in direct mode (P1, the agent told): set it, or fix it in uCRM, on the uCRM catalogue screen (its reason is on the sheet)" ;;
  esac
  s="$( [ -n "$ok_r" ] && ql_of "$(kv "$QO_R" qcstd)" plug)"; n="${s%%/*}"; u="${s#*/}"
  case "$n:$u" in
    0:0) note "QC-ON3 no standard quotation is defined — a one-click quotation needs one: an admin defines it on the uCRM catalogue screen (docs/72 §G.3)" ;;
    *[!0-9:]*|:*|*:) bad "QC-ON3 the standard quotations could not be judged (${s:-not read})" ;;
    *) if [ "$n" = "$u" ]; then ok "QC-ON3 every standard quotation ($n) is usable now: its plan, hardware and installation are all offered"
       else bad "QC-ON3 $((n - u)) of $n standard quotation(s) cannot be used now — an item in it is no longer offered; the uCRM catalogue screen, and the sheet, say which"; fi ;;
  esac
  fi
  fi
  g="$( [ -n "$ok_r" ] && kv "$QO_L" qcg7)"
  case "$g" in
    direct:0,bad:0) note "QC-ON4 no web-direct application on the copy yet — G-7's invariant has nothing to read; run --after-only again after the first direct sale" ;;
    direct:*,bad:0) ok "QC-ON4 every web-direct application on the copy ($(subkv "$g" direct)) keeps G-7: package_choice and device_id empty, and only id 0 in hw_cart_json and in quote_sale_cart, if any — nothing 5.18.102 would match to a plugin row, were 5.18.103 itself ever rolled back (G-7, docs/72 §G.2)" ;;
    direct:*,bad:*) bad "QC-ON4 $(subkv "$g" bad) of $(subkv "$g" direct) web-direct application(s) break G-7 (package_choice or device_id set, or in hw_cart_json or quote_sale_cart an id that is not 0 or a cart that does not read) — ids on the sheet. Send the log file" ;;
    *) bad "QC-ON4 the web-direct applications could not be read on the copy (${g:-not read})" ;;
  esac
  return 0
}
# qc_ca2_txt pin|inst — QC-CA2's text read (5.18.103, docs/72 §G.3): includes/post/post_sync.php's one block for the uCRM
# catalogue's five actions, whole-line comments aside (sec_src, sec_block, sec_code — the readers QL-CA3 uses). The block is
# found by its own first line, and every code line of the file that names an action lies inside it. The gate's condition —
# QuoteOrganization::setting(...)['on'] — at the block's first level, every line after it one level in, up to the gate's
# close, the block's last two lines; then $auth->requireAdmin(), the account's fresh re-read ($store->findOne('retailers.json',
# 'id', …)) and the own-page check (csrfCheck() && !CustomerSession::crossSite() && BankGate::fromOwnPage('POST')), in that
# order, each before the block's first act — a UcrmCatalogue write (setMode, setInstall, setHidden, saveStandard,
# endStandard) or a $store-> call other than that re-read — and each of the five writes present. Prints "ok" or fixed words,
# never a line of the code. The caller reads the pin's file from Git the same way, the control.
qc_ca2_txt() {
  local src code blk act w="" one inb
  src="$(sec_src "$1" includes/post/post_sync.php)"
  [ -n "$src" ] || { echo nofile; return 0; }
  code="$(printf '%s\n' "$src" | sec_code)"
  blk="$(printf '%s\n' "$src" | sec_block "if (\$_SERVER['REQUEST_METHOD'] === 'POST'" | sec_code)"
  for act in ucrm_cat_mode ucrm_cat_install ucrm_cat_hidden ucrm_cat_standard_save ucrm_cat_standard_end; do
    one="$(grep -cF -- "'$act'" <<<"$code" || true)"; inb="$(grep -cF -- "'$act'" <<<"$blk" || true)"
    { [ "${inb:-0}" -ge 1 ] && [ "$one" = "$inb" ]; } || w="$w $act:named-on-${one:-?}-code-lines-${inb:-?}-in-the-block"
  done
  w="$w$(printf '%s\n' "$src" | sec_block "if (\$_SERVER['REQUEST_METHOD'] === 'POST'" | sec_code \
    | QA_GATE="    if (QuoteOrganization::setting(" QA_ON="['on']) {" QA_RA="\$auth->requireAdmin()" QA_FR="\$store->findOne('retailers.json', 'id', " \
      QA_CS="csrfCheck() && !CustomerSession::crossSite() && BankGate::fromOwnPage('POST')" awk '
      { L[NR] = $0 }
      END {
        w = ""
        if (NR < 4 || index(L[2], "ucrm_cat_mode") == 0) { printf " ucrm_cat:noblock"; exit }
        g = 0; ra = 0; fr = 0; cs = 0; fa = 0; n = split("setMode(,setInstall(,setHidden(,saveStandard(,endStandard(", W, ",")
        for (i = 3; i <= NR; i++) {
          s = L[i]
          if (!g && index(s, ENVIRON["QA_GATE"]) == 1 && index(s, ENVIRON["QA_ON"]) > 0) g = i
          if (!ra && index(s, ENVIRON["QA_RA"]) > 0) ra = i
          if (!fr && index(s, ENVIRON["QA_FR"]) > 0) fr = i
          if (!cs && index(s, ENVIRON["QA_CS"]) > 0) cs = i
          for (k = 1; k <= n; k++) if (index(s, "UcrmCatalogue::" W[k]) > 0) { H[k]++; if (!fa) fa = i }
          if (!fa && index(s, "$store->") > 0 && index(s, ENVIRON["QA_FR"]) == 0) fa = i
        }
        if (!g) w = w " ucrm_cat:no-gate"
        else {
          if (L[NR - 1] != "    }" || L[NR] != "}") w = w " ucrm_cat:the-gate-does-not-close-the-block"
          for (i = g + 1; i <= NR - 2; i++) if (L[i] !~ /^[ \t]*$/ && L[i] !~ /^        /) { w = w " ucrm_cat:a-line-outside-the-gate"; break }
        }
        if (!ra) w = w " ucrm_cat:no-requireAdmin"
        if (!fr) w = w " ucrm_cat:no-fresh-re-read"
        if (!cs) w = w " ucrm_cat:no-own-page-check"
        for (k = 1; k <= n; k++) if (!H[k]) w = w " ucrm_cat:no-UcrmCatalogue::" substr(W[k], 1, length(W[k]) - 1)
        if (g && ra && fr && cs) {
          if (!(g < ra && ra < fr && fr < cs)) w = w " ucrm_cat:out-of-order"
          if (fa && fa < cs) w = w " ucrm_cat:an-act-before-the-checks"
        }
        printf "%s", w
      }')"
  sec_say "$w"
}
# qc_ca3_txt pin|inst — QC-CA3's text read (5.18.103, docs/72 §G.9, G-15): Send Quotation and the lead quotes re-price each
# picked uCRM line inside QuotationService, from a fresh read — the installed includes/post/post_leads.php calling
# QuotationService::directForm( and QuotationService::pickedLine( (each at least once), and lib/QuotationService.php
# defining directForm, pickedLine and directLines and refusing a changed price (DIRECT_PRICE_CHANGED) — each count, comments
# aside, equal to the pin's, which must read at least one of each (the control). Prints "ok" or fixed words.
qc_ca3_txt() {
  local w="" f nd p i
  while IFS='|' read -r f nd; do
    p="$(sec_src pin "$f" | sec_code | grep -cF -- "$nd" || true)"; i="$(sec_src "$1" "$f" | sec_code | grep -cF -- "$nd" || true)"
    case "$p" in ''|0) w="$w $f:the-control-reads-none-of-$nd" ; continue ;; esac
    [ "$i" = "$p" ] || w="$w $f:$nd×${i:-?}-not-$p"
  done <<'NEEDLES'
includes/post/post_leads.php|QuotationService::directForm(
includes/post/post_leads.php|QuotationService::pickedLine(
lib/QuotationService.php|function directForm(
lib/QuotationService.php|function pickedLine(
lib/QuotationService.php|function directLines(
lib/QuotationService.php|DIRECT_PRICE_CHANGED
NEEDLES
  sec_say "$w"
}
# ── 5.18.104: the sales follow-up (QF, Part F's codes; root docs/73 §H.2.15, §H.2.16) ─────────────────────────────────────
# Read-only on COPIES, as every reading here: a VACUUM INTO copy of the book as its owner (CIHV_PHP), its settings row cut
# to the keys the ladder declares — its switch and record keys, its settings, the pre-existing keys it reads and the
# book's — never a secret (PluginConfig::SECRET_KEYS, crm_auth_token, webhook_secret_file and the rest); copies of the
# three settings files cut the same way; the readings' one copy of the live vault (QF_VAULT, its book keys and the keys
# the readings keep, never a secret), named by DN_VAULT_FILE in every reading of a copy that loads the plugin's
# configuration (every other reading of a copy names a vault that is never made, in its own folder: T-D3); and a code
# root of its own, a copy of the PIN's code from Git (stage A) or of the INSTALLED code (ICODE_R, after the copy), in
# the container's /tmp —
# never the plugin folder. LK's readings open the live book itself, read-only (SQLITE_OPEN_READONLY, query_only): the
# ladder's keys (the files and the store row: LK-G1, LK-B1, LK-CA1, LK-AO, LK-RB0, LK-RB1), the baseline (QF-G1) and
# the rows (LK-CA2, LK-RB1). Nothing here writes the live book: 5.18.105 never runs the switch tool (root docs/74 §H.4.3),
# so the tool's lines below pass only through its --check and show. The log carries counts, fixed codes, key names, PASS/FAIL/NOTE and
# hashes; the tool's own lines pass through qf_safe, which turns any run of 9 or more digits into <digits> (the tool
# prints none: belt and braces), and its "was on:" lines go to the sheet. Never a phone, a name, an amount, a staff id,
# a value of a key or a credential; the OpenAI key is "set" or "not set" only.
QF_PHP="$(cat <<'PHP'
// QF_PHP — 5.18.104's Part F readings (root docs/73 §H.2.15), one mode per call, as the database's owner in the
// container. Every mode but "lk", "base", "rbn" and (at the baseline) "lkrows" reads only a COPY in a folder of this
// run's; those open the live book with SQLITE_OPEN_READONLY and read its files as text — counts, key names and keyed
// hashes only, never a value (5.18.105, root docs/74 §H.4.3: "g4" and "rb3" went with QF-G4 and QF-RB3). Output: one
// line of key=value words (counts, fixed codes, key names); never a phone, a name, an amount, a staff id or a secret.
// PHP 7.4 syntax (the release's).
$mode = (string)($argv[1] ?? '');
$a = array_slice($argv, 2);
// A reading of a COPY that loads the plugin's configuration reads the copy's own vault — DN_VAULT_FILE, the reading's
// folder's vault.json (qf_copy's: the live vault's book keys and the keys the readings keep, never a secret) — and never
// ConfigVault::path()'s default beside the code root, which holds nothing: without it a copy whose tenant or instances
// live only in the vault would read as South Sudan, or as having no instance (5.18.103 sets DN_VAULT_FILE for every
// in-process reading). Each of these modes takes [ROOT, DIR], DIR the reading's folder.
if (in_array($mode, ['notes', 'ca4', 'ca6', 'ca8', 'on3', 'lon', 'cfgkey'], true)) putenv('DN_VAULT_FILE=' . rtrim((string)($a[1] ?? ''), '/') . '/vault.json');
// Every other reading of a COPY loads none of the plugin's configuration — the book alone, the pin's migrations
// through MigrationRunner ("trial", "neg"), the live master log or the pin's tree read as text ("n5", "hk7") — and
// names a vault that is never made, in the reading's own folder, as 5.18.103's readings that load no configuration do
// (notes-, bank-, c-vault-none.json; T-D3): nothing it runs can reach ConfigVault::path()'s default, nor a DN_VAULT_FILE
// the container itself sets. The folder: the DIR argument where the mode takes one, else the folder holding the
// first argument (DB, TREE).
if (in_array($mode, ['g1', 'ca1', 'ca2', 'hk7', 'flags'], true)) putenv('DN_VAULT_FILE=' . dirname((string)($a[0] ?? '')) . '/qf-' . $mode . '-vault-none.json');
if (in_array($mode, ['n5', 'on5'], true)) putenv('DN_VAULT_FILE=' . rtrim((string)($a[0] ?? ''), '/') . '/qf-' . $mode . '-vault-none.json');
if (in_array($mode, ['trial', 'neg'], true)) putenv('DN_VAULT_FILE=' . rtrim((string)($a[1] ?? ''), '/') . '/qf-' . $mode . '-vault-none.json');
$ro = function (string $db) {
    $p = new PDO('sqlite:' . $db, null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_TIMEOUT => 15,
                                                PDO::SQLITE_ATTR_OPEN_FLAGS => PDO::SQLITE_OPEN_READONLY]);
    $p->exec('PRAGMA query_only = ON');
    return $p;
};
$rw = function (string $db) {
    $p = new PDO('sqlite:' . $db, null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_TIMEOUT => 15]);
    $p->exec('PRAGMA busy_timeout = 5000');
    return $p;
};
$has = function (PDO $p, string $t): bool {
    $s = $p->prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?"); $s->execute([$t]);
    return $s->fetchColumn() !== false;
};
$col = function (PDO $p, string $t, string $c) use ($has): bool {
    if (!$has($p, $t)) return false;
    foreach ($p->query('PRAGMA table_info(' . $t . ')')->fetchAll(PDO::FETCH_ASSOC) as $r) if ((string)$r['name'] === $c) return true;
    return false;
};
$one = function (PDO $p, string $sql, array $x = []) { $s = $p->prepare($sql); $s->execute($x); return $s->fetchColumn(); };
$ladder = function (string $root): array {
    require_once $root . '/lib/UtcClock.php';
    require_once $root . '/lib/SalesFollowupLadder.php';
    return ['all' => SalesFollowupLadder::allKeys(), 'settings' => SalesFollowupLadder::settingKeys(),
            'pre' => SalesFollowupLadder::preexistingKeys()];
};
$secret = function (string $root): array {
    require_once $root . '/lib/PluginConfig.php';
    $s = PluginConfig::SECRET_KEYS;
    foreach (['admin_token', 'crm_auth_token', 'webhook_secret_file', 'smtp_pass', 'smtp_password'] as $k) $s[] = $k;
    return array_values(array_unique($s));
};
$setNow = function (array $c, string $k): bool { return array_key_exists($k, $c) && $c[$k] !== null && $c[$k] !== '' && $c[$k] !== false; };
$readJson = function (string $f) { if (!is_file($f) || !is_readable($f)) return null; $d = json_decode((string)@file_get_contents($f), true); return is_array($d) ? $d : null; };
$storeRow = function (PDO $p) use ($has): array {
    if (!$has($p, 'kyc_config')) return [];
    $j = $p->query('SELECT data FROM kyc_config WHERE id = 0 LIMIT 1')->fetchColumn();
    $d = is_string($j) ? json_decode($j, true) : null;
    return is_array($d) ? $d : [];
};
// a SqliteStore JSON document, read as SqliteStore::load() reads it (lib/SqliteStore.php:339): the table is the file's
// name; a config document (master_schedule.json) is one row with the sentinel id 0, a record list (retailers.json) a row each
$flat = function (PDO $p, string $name) use ($has) {
    $t = preg_replace('/[^a-zA-Z0-9_]/', '_', preg_replace('/\.json$/', '', $name));
    if (!$has($p, $t)) return null;
    $j = $p->query('SELECT data FROM [' . $t . '] WHERE id = 0 LIMIT 1')->fetchColumn();
    $d = is_string($j) ? json_decode($j, true) : null;
    return is_array($d) ? $d : null;
};
$docRows = function (PDO $p, string $name) use ($has) {
    $t = preg_replace('/[^a-zA-Z0-9_]/', '_', preg_replace('/\.json$/', '', $name));
    if (!$has($p, $t)) return null;
    $out = [];
    foreach ($p->query('SELECT data FROM [' . $t . '] ORDER BY id ASC')->fetchAll(PDO::FETCH_COLUMN) as $j) { $d = json_decode((string)$j, true); if (is_array($d)) $out[] = $d; }
    return $out;
};
$JOBS = ['quote_chase', 'quote_daily_list', 'ai_media', 'offers_send'];
// master_schedule.json as read: 'read' (its row decoded), 'absent' (no table, or no row) or 'unreadable' (a row that is
// not JSON); and how many entries it holds besides the four jobs' — the positive control that the schedule was read at
// all, without which "no entry for the four" would pass over a schedule nobody read (QF-CA3, the redeploy baseline)
$sched = function (PDO $p) use ($has, $JOBS): array {
    if (!$has($p, 'master_schedule')) return ['absent', 0];
    $j = $p->query('SELECT data FROM [master_schedule] WHERE id = 0 LIMIT 1')->fetchColumn();
    if (!is_string($j)) return ['absent', 0];
    $d = json_decode($j, true);
    if (!is_array($d)) return ['unreadable', 0];
