$SC = [];
foreach (explode(' ', '089_quote_followups.sql:38 090_wa_voice.sql:79 091_wa_offers.sql:25') as $x) { [$f, $n] = explode(':', $x); $SC[$f] = (int)$n; }
try {
    switch ($mode) {
    case 'keys':   // keys ROOT — the ladder's three lists, by name
        $L = $ladder($a[0]);
        echo 'all=', count($L['all']), ' settings=', count($L['settings']), ' pre=', count($L['pre']),
