        $toks = token_get_all($src);
        $stack = []; $depth = 0; $pending = null; $line = 1;
        for ($i = 0, $n = count($toks); $i < $n; $i++) {
            $t = $toks[$i];
            if (is_array($t)) {
                $line = $t[2];
