                    for ($j = $i + 1; $j < $n; $j++) {
                        if (is_array($toks[$j]) && $toks[$j][0] === T_WHITESPACE) continue;
                        if ($toks[$j] === '&') continue;
                        $pending = (is_array($toks[$j]) && $toks[$j][0] === T_STRING) ? $toks[$j][1] : '{closure}';
