                    }
                }
                if ($t[0] === T_CURLY_OPEN || $t[0] === T_DOLLAR_OPEN_CURLY_BRACES) { $depth++; }
                if ($t[0] === T_VARIABLE && preg_match('/^\$evo[A-Za-z_]*$/', $t[1]) || ($t[0] === T_VARIABLE && $t[1] === '$this')) {
                    $k = $i + 1; $chain = $t[1];
