                     'steps' => [$step], 'out' => $T . '/out-' . $n . '.json', 'error_log' => $T . '/err-' . $n . '.log'];
            $sf = $T . '/spec-' . $n . '.json';
            if (@file_put_contents($sf, json_encode($spec, JSON_UNESCAPED_SLASHES)) === false) return ['bad' => 'spec'];
            $before = count($sessions());
            $env = ['PATH' => (string)getenv('PATH'), 'HOME' => $T, 'TMPDIR' => $T, 'DN_VAULT_FILE' => $T . '/vault.json', 'DN_DATA_DIR' => $T . '/data'];
            $h = proc_open([PHP_BINARY, '-d', 'disable_functions=' . $NONET, '-d', 'allow_url_fopen=0', '-d', 'display_errors=0', '-d', 'opcache.enable_cli=0', $drive, $sf],
                           [0 => ['file', '/dev/null', 'r'], 1 => ['file', '/dev/null', 'w'], 2 => ['file', '/dev/null', 'w']], $pp, $T, $env);
