            for ($i = 0; $i < 60 && count($sessions()) < $before + 1; $i++) usleep(50000);
            usleep(300000);                                                         // a second session, were there one, shows here
            return ['rc' => $rc, 'out' => is_array($out) ? $out : null, 'sess' => array_slice($sessions(), $before), 'path' => $path];
        };
        $dec = function (string $T, int $qid) use ($ro, $has): array {
            $p = $ro($T . '/data/plugin.sqlite3'); $out = [];
            if (!$has($p, 'quote_agent_copies')) return $out;
