            $k = 0; foreach ($t as $x) $k += (int)$p->query('SELECT COUNT(*) FROM [' . $x . ']')->fetchColumn();
            return implode(',', $t) . ':' . $k;
        };
        $logSt = function (string $T, int $qid) use ($ro, $has, $one, $tok): string {
            $p = $ro($T . '/data/plugin.sqlite3');
