            $v = $one($p, 'SELECT status FROM customer_email_log WHERE dedupe_key = ?', ['quotation:' . $qid]);
            return $v === false ? 'none' : $tok($v);
        };
        $dataN = function (array $s): int { return count(array_filter((array)($s['commands'] ?? []), function ($c) { return strtoupper(trim((string)$c)) === 'DATA'; })); };
        $ccOf = function (array $s): ?array {   // the message's Cc header (unfolded), as lower-case bare addresses; null when there is none
            $d = (string)($s['data'] ?? '');
            $i = strpos($d, "\r\n\r\n"); if ($i === false) $i = strpos($d, "\n\n");
