            if (($r['out']['steps'][0]['exc'] ?? null) !== null) $b[] = 'exc';
            $ret = $r['out']['steps'][0]['ret'] ?? null;
            if ($r['path'] === 'app' && (!is_array($ret) || empty($ret['ok']) || empty($ret['emailed_by_plugin']))) $b[] = 'not_by_plugin';
