            'c2' => [[$TO], null, ['path' => 'plugin', 'outcome' => 'skipped', 'code' => 'same_as_customer', 'source' => 'actor', 'rcpt' => 'none', 'send_ok' => 1], null],
            'c3' => [[$TO, $KY], [$KY], ['path' => 'webhook', 'outcome' => 'added', 'code' => 'added', 'source' => 'kyc', 'rule' => 'kyc_submitter', 'agent_id' => 990000049, 'rcpt' => 'accepted', 'send_ok' => 1], 'sent'],
            'c4' => [[$TO], null, ['path' => 'webhook', 'outcome' => 'skipped', 'code' => 'no_agent', 'source' => 'none', 'rcpt' => 'none', 'send_ok' => 1], 'sent'],
        ];
        foreach ($want as $tag => $w) {
