                if ($rcpt($s) !== $w[0]) $b[] = 'rcpt';
                if ($ccOf($s) !== $w[1]) $b[] = 'cc';
                $ds = $dec($U, $C[$tag][2]);
                if (count($ds) !== 1) $b[] = 'decisions_' . count($ds);
                else foreach ($w[2] as $k => $v) if ((string)($ds[0][$k] ?? '') !== (string)$v) $b[] = 'decision_' . $k;
                if ($w[3] !== null && $logSt($U, $C[$tag][2]) !== $w[3]) $b[] = 'log_row';
            }
