        $live = rtrim($pdd, '/') . '/quote_mail.log'; $dst = $dir . '/quote_mail.log';
        if (file_exists($dst)) { echo '?dest'; exit(3); }
        $n0 = $mlCount($pdd);
        if (!is_file($live)) { echo 'ml=absent live=', $n0, ' copy=0 after=', $mlCount($pdd); break; }
        $raw = is_readable($live) ? @file_get_contents($live) : false;
        if ($raw === false) { echo 'ml=unreadable live=', $n0, ' copy=0 after=', $mlCount($pdd); break; }
        if (!$put($dst, (string)$raw)) { echo '?write'; exit(3); }
