# its lock its own, and the retry job 5.18.91's, its gate in place, each byte for byte…
[ "$(sha256sum "$DEST/$MAIN" 2>/dev/null | cut -c1-64)" = "$MAIN_BASE_SHA256" ] || RB_REF="$RB_REF main:not-5.18.93's"
