grep -qF 'InternalNumbers' "$DEST/tools/set_config.php" 2>/dev/null || RB_REF="$RB_REF safety-fix:set_config.php"
grep -qF 'InternalNumbers' "$DEST/tools/channels.php" 2>/dev/null || RB_REF="$RB_REF safety-fix:channels.php"
