fi

# 5.18.93: the salesperson pilot against the deploy's own record of it. A run compares the pilot only with what it read
# itself (V3f, V3h, R3, R11, RB — its key is its own); an --after-only run, or a rollback, also sets what its stage A
# found against what the deploy found before it changed anything (the state file: the switches, and the shapes of 087's
# rows, the registry, 5.18.89's rules and the policy as the code read them — never an HMAC). This script writes none of
# them: a difference since the deploy is the operator's (the card, set_config.php) — a note, never a failure.
if [ "$MODE" != "deploy" ] && [ -n "$STATE" ] && [ -f "$STATE" ]; then
  AO_AT="$(sed -n 's/^DEPLOYED_AT=//p' "$STATE" 2>/dev/null | head -1)"; AO_DIFF=""; AO_N=0; AO_POL="${POL_A:-}"
  while IFS='|' read -r ao_key ao_label ao_now; do
    [ -n "$ao_key" ] || continue
    ao_rec="$(sed -n "s/^$ao_key=//p" "$STATE" 2>/dev/null | head -1 | sed -E 's/ sig=[^ ]*//; s/\|.*$//')"
    ao_now="$(printf '%s' "$ao_now" | sed -E 's/ sig=[^ ]*//')"
    { [ -n "$ao_rec" ] && [ -n "$ao_now" ]; } || continue
    AO_N=$((AO_N+1))
    [ "$ao_rec" = "$ao_now" ] && continue
    case "$ao_rec$ao_now" in
      *" "*) AO_DIFF="$AO_DIFF; $ao_label: $(LC_ALL=C comm -23 <(tr ' ' '\n' <<<"$ao_rec" | LC_ALL=C sort) <(tr ' ' '\n' <<<"$ao_now" | LC_ALL=C sort) | paste -sd' ' -) → $(LC_ALL=C comm -13 <(tr ' ' '\n' <<<"$ao_rec" | LC_ALL=C sort) <(tr ' ' '\n' <<<"$ao_now" | LC_ALL=C sort) | paste -sd' ' -)" ;;
      *) AO_DIFF="$AO_DIFF; $ao_label: ${ao_rec#*=} → ${ao_now#*=}" ;;
    esac
  done <<AO_EOF
MN_BEFORE|$MN_FLAG|$MN_BEFORE
OL_BEFORE|$OL_KEY|$OL_BEFORE
FH_BEFORE|$FH_KEY|$FH_BEFORE
HC_BEFORE|$HC_KEY|$HC_BEFORE
WA87_BEFORE|087's rows and trail|$WA87_BEFORE
REG_BEFORE|the registry as the code read it|${REG_A:-}
B2C_BEFORE|5.18.89's rules as the code read them|${B2C_A:-}
POL_BEFORE|the automated-send policy as the code read it|${AO_POL%%|*}
AO_EOF
  if [ "$AO_N" = "0" ]; then echo "  pilot record    the deploy's state file ($STATE) holds no record of the pilot to set this run's reading against"
  elif [ -z "$AO_DIFF" ]; then echo "  pilot record    as the deploy found it before it changed anything${AO_AT:+ ($AO_AT)}: $AO_N reading(s) — the pilot's switches, 087's rows and trail, the code's readings — the same in every state and count"
  else note "the salesperson pilot is not as the deploy found it before it changed anything${AO_AT:+ ($AO_AT)}${AO_DIFF/#; / — }. This script writes none of it: a change since the deploy is the operator's (the card, set_config.php). This run's own before and after are what V3f, V3h, R3 and R11$( [ "$MODE" = "rollback" ] && echo " and RB") judge — reported here, never a failure"; fi
fi
fi   # 5.18.97: the end of what --check never reaches (from B on)
# ════════════════════════════════════════════════════════
z_stage   # Z1, Z2 — defined with the helpers, so that --check-bank closes with it too (5.18.97)
# ════════════════════════════════════════════════════════
hdr "F. Summary"
# ════════════════════════════════════════════════════════
# 5.18.103: the names of its own checks, said once — QC-G1 (a refusal before the copy), QC-N1–QC-N7 (notes), QC-CA1 (after
# the copy), QC-CA2 and QC-CA3 (stage V), QC-ON1–QC-ON4 (an --after-only run, the switch as found), QC-RB1 and QC-RB2 (after
# a rollback; QC-RB2's count is stage A of --rollback's note too) — "quote catalogue", so that none reads as an earlier
# release's check; 5.18.102's (QL-G1, QL-N1–QL-N7, QL-CA2, QL-CA3 — its QL-CA1, QL-LK1 and QL-RB1–QL-RB3 retired, docs/72
# §G.13), 5.18.101's, 5.18.100's, 5.18.99's and 5.18.98's, carried, keep theirs. The catalogue's reads, the organization
# field's and the notes' are GETs of the quoting checks' own probe, through its GET-only wrapper, so QO_GETS and QO_OTHER
# count them with Q-G4's and Q-CA3's; QL-CA3's and QC-CA2's are stage V's, from the host to the plugin's own public
# address, as V's other anonymous refusals are.
echo "  names             LK-G1, LK-B1, LK-CA1, LK-CA2, LK-ON, LK-AO, LK-RB0, LK-RB1, LM-G1, LM-G2, LM-CA1, LM-CA2, LM-ON,"
echo "                    LM-RB1 and RB105 are $EXPECTED_VERSION's own (root docs/74 §H.4, §H.5); QF-G1–QF-G3, QF-N1–QF-N7,"
echo "                    QF-CA1–QF-CA8 and QF-ON0–QF-ON5 are 5.18.104's (QF, Part F's; root docs/73 §H.2.15), carried and"
echo "                    live-aware (its QF-G4 and QF-RB1–QF-RB3 retired); VN-G1–VN-G7, VN-M1, VN-M2, VN-CA1–VN-CA4, VN-K1,"
echo "                    VN-K2, VN-ON1–VN-ON4, VN-RB5 and VA-ON1 are Part V's (VN, VA; §H.3.25); OF-G1, OF-G2, OF-N1–OF-N3,"
echo "                    OF-M1, OF-M2, OF-CA1–OF-CA5, OF-ON1, OF-ON2 and OF-RB2 are Part O's (OF; §H.4.18); AC-L1, AC-N1,"
echo "                    AC-N2, AC-CA1, AC-CA2, AC-ON1 and AC-RB2 are Part P's (AC; §H.5.14); QC-G1, QC-N1–QC-N7, QC-CA1–QC-CA3, QC-ON1–QC-ON4,"
echo "                    QC-RB1 and QC-RB2 are 5.18.103's (QC, \"quote catalogue\"), carried; QL-G1, QL-N1–QL-N7, QL-CA2 and QL-CA3 are 5.18.102's (its QL-CA1, QL-LK1"
echo "                    and QL-RB1–QL-RB3 retired); QS-G1 and QS-CA1 are 5.18.101's; TN-G1–TN-G3, TN-N1, TN-N2 and"
echo "                    TN-CA1–TN-CA3 are 5.18.100's; Q-G1–Q-G6, Q-N1–Q-N7 and Q-CA1–Q-CA6 are 5.18.99's"
echo "                    (SPEC-quote-company §6), and 5.18.98's G2, G3, CA2–CA4, C1–C5 and N1–N4 — each carried with its name"
echo "  uCRM              asked $QO_GETS GET(s) by this run — the quoting checks', 5.18.102's catalogue, organization field and notes (QL-G1, QL-N1, QL-N2, QL-CA2) and 5.18.103's direct catalogue (QC-G1, QC-CA1) alike — through its GET-only wrappers, and nothing else ($QO_OTHER other)"
# Since 5.18.97: --check ends here — stage A alone, as a deploy runs it, and no further: no backup, no copy, no deploy,
# nothing written but its own cash sheet and its row digest (0600, ids and hashes, no figure). Its verdict is GO or NO-GO;
# the deploy itself is its own command, run when chosen — the runbook's, the branch pulled and the release fetched
# first, with the flags this --check ran with — each of --without-bank-balance, --quote-company-off,
# --quote-create-unproven, --lead-org-differs and --accept-unpriced only where its check went to its note under it
# (G3_NOTED, QOFF_NOTED, QG5_NOTED, QG6_NOTED, and 5.18.102's QLG1_NOTED — docs/71 §Q, D-R13): where a check held
# without it, it is not needed, and the command below is printed without it. (5.18.104's --clear-switches is refused at
# parse since 5.18.105.)
if [ -n "$CHECK_ONLY" ]; then
  F_FLAGS=""; F_TYPED=""
  [ -z "$REDEPLOY" ] || F_FLAGS="$F_FLAGS --redeploy"
  [ -z "${G3_NOTED:-}" ] || F_FLAGS="$F_FLAGS --without-bank-balance"
  [ -z "${QOFF_NOTED:-}" ] || F_FLAGS="$F_FLAGS --quote-company-off"
  [ -z "${QG5_NOTED:-}" ] || F_FLAGS="$F_FLAGS --quote-create-unproven"
  [ -z "${QG6_NOTED:-}" ] || F_FLAGS="$F_FLAGS --lead-org-differs"
  [ -z "${QLG1_NOTED:-}" ] || F_FLAGS="$F_FLAGS --accept-unpriced"
  { [ -z "$WITHOUT_BANK" ] || [ -n "${G3_NOTED:-}" ]; } || F_TYPED="$F_TYPED --without-bank-balance"
  { [ -z "$QOFF" ] || [ -n "${QOFF_NOTED:-}" ]; } || F_TYPED="$F_TYPED --quote-company-off"
  { [ -z "$QUNPROVEN" ] || [ -n "${QG5_NOTED:-}" ]; } || F_TYPED="$F_TYPED --quote-create-unproven"
  { [ -z "$LEADDIFF" ] || [ -n "${QG6_NOTED:-}" ]; } || F_TYPED="$F_TYPED --lead-org-differs"
  { [ -z "$ACCEPT_UNPRICED" ] || [ -n "${QLG1_NOTED:-}" ]; } || F_TYPED="$F_TYPED --accept-unpriced"
  echo "  --check           stage A alone, every refusal and note of a deploy$( [ -n "$F_FLAGS" ] && echo " with$F_FLAGS")$( [ -n "$F_TYPED" ] && echo " (typed and not needed:$F_TYPED — each check held without it; the deploy below is printed without it)"): nothing was backed up, copied, deployed or switched — nothing was changed; it wrote only its own cash sheet and row digest, below"
  echo "  cash sheet        $(sheet_say)"
  [ -n "${CIH_ROWS:-}" ] && [ -f "$CIH_ROWS" ] && echo "  row digest        $CIH_ROWS — 0600: each row's id and a 16-hex hash of it, no figure; this script's own record, as the sheet is"
  if [ -n "$SHEET" ] && [ -f "$SHEET" ]; then
    echo "                    the figures of the book as stage A read them, the copy checks' and the notes' counts, ECO Bank's"
    echo "                    offered accounts, the quoting checks' counts and the move-list's client ids, and the catalogue's"
    echo "                    items by name, each with its reason, which can carry a price (QL-G1, QL-N7), and, per item,"
    echo "                    under \"uCRM items with the same spelling — a hint only\", the uCRM items spelled like it, by id,"
    echo "                    with whether each could be linked, a hint, never a verdict; the organization numbers uCRM gives"
    echo "                    its products; what the forms would offer from uCRM in direct mode — each plan and hardware item"
    echo "                    with its uCRM ids, price and unit, every other item with its reason (QC-G1) — the uCRM catalogue's"
    echo "                    settings on the copy, and the waiting web applications' ids (QC-N4) — for you alone; never paste it."
    echo "                    To read it:"
    echo "      less $SHEET"
  fi
  echo "  checks            $PASS ok, $FAIL failed, $NOTE notes"
  if [ "$FAIL" = "0" ]; then
    if [ -z "$F_FLAGS" ]; then F_RUN_CMD="$RUNBOOK_CMD"
    else F_RUN_CMD="cd $REPO && git pull origin $BRANCH && git fetch origin $RELEASE_BRANCH && mkdir -p $OUT && bash scripts/deploy-$EXPECTED_VERSION.sh$F_FLAGS $(LOGW "$( [ -n "$REDEPLOY" ] && echo redeploy || echo deploy)")"; fi
    echo; echo "  $EXPECTED_VERSION (check): GO — stage A holds. Send this LOG FILE back (not a copy of the terminal, and never the cash sheet)."
    echo "  The deploy itself, when you choose to run it — its own command, alone; it runs stage A again before it asks you to type DEPLOY:"
    echo "      $F_RUN_CMD"
  else echo; echo "  $EXPECTED_VERSION (check): NO-GO — $FAIL failed; send the log file (never the cash sheet). Nothing was changed."; fi
  [ "$FAIL" = "0" ]; return
fi
# Every command printed here stands alone on its line and carries its own log wrapper, so a later step run from this
# text leaves a log of its own; the rollback comes last, after the verdict, its own (root docs/44 §16.9).
LIVE_NOW="$(live_commit)"
case "$MODE" in
  rollback) echo "  serving           ${LIVE_NOW:-?}  (plugin $BASELINE_VERSION)"
            echo "  what it means     on Uganda the uCRM catalogue is 5.18.103's own and the rollback leaves it exactly as it was — its screen, its settings and its switch as an admin left them, the KYC form, Send Quotation and the lead quotes offering what they offered (RB); the web-direct applications stay on 5.18.103's direct rules, as under 5.18.105 — ${QCRB_SAY:-not counted} (QC-RB2$( [ -n "$QC_RB" ] && echo "; $QC_RB_IDS")): retried by their uCRM ids, Make the quotation on an Orders card where it applies; the rollback adds none to quote by hand, and nothing is quoted at price 0. Every switch of the sales follow-up is as it was (LK-RB1): the steps that were on keep running, and the lines 5.18.105 masked write phone numbers again (LM-RB1). The files 5.18.105 adds stay on disk, read by nothing (QC-RB1). The Cashbook, ECO Bank, every number and the quoting organization stay as they are (RB)" ;;
  *)        echo "  deployed commit   ${LIVE_NOW:-?}  (plugin $EXPECTED_VERSION, the release commit on $RELEASE_BRANCH)" ;;
esac
[ -n "$BK" ] && echo "  backup            $BK"
if [ "$MODE" != "rollback" ]; then
  case "${BK_AFTER#bk=}" in
    on/*)  F_SW="ECO Bank's switch is ON in the configuration files, as the operator left it" ;;
    *)     F_SW="ECO Bank's switch is NOT on in the configuration files ($( [ -n "${V3J_WBB:-}" ] && echo "--without-bank-balance, the operator's choice" || echo "V3j says why"))" ;;
  esac
  # 5.18.102 (E2-2, L2, review 2): which quoting organization the summary speaks of. As the INSTALLED code read it after
  # the copy (QO_GATE_R, set by qo_after: on:<id> or off) — and only that reading may say "not in force". Where nothing
  # was read after the copy (unread: no code copy, or qo_run r stopped before its gate probe) or what was read is neither
  # (other: an invalid setting, or the files and the store row disagree), stage A's reading through the pin's stands in
  # for "in force", said as such (QO_GATE_A, from QG3_A: this run's, or in --after-only the deploy's state file); a
  # stage-A "off", or no usable stage-A reading, leaves it NOT ESTABLISHED. A reading that failed is never read as "off":
  # 5.18.101 let an empty one say "none in force" in one clause, and 5.18.102 hangs its whole summary on it. A reading
  # after the copy that differs from stage A's, or has no stage-A reading to equal (Q-CA2 fails), is said beside it,
  # never "as under 5.18.101". Ids and fixed words only.
  F_QGR="${QO_GATE_R:-unread}"; F_QGA="${QO_GATE_A:-$(qo_gate_a)}"
  F_QORG=""; F_QST=unknown; F_QNR=""; F_QDIFF=""; F_QSA=""; F_QSAW=""; F_QIN=" (Q-G3, Q-CA2)"; F_QD9=""
  case "$F_QGA" in
    on:[0-9]*) F_QSA="#${F_QGA#on:} in force" ;;
    off) F_QSA="not in force (0/off)" ;;
    other) F_QSAW="stage A's reading (Q-G3) was neither in force nor off" ;;
    *) F_QSAW="stage A's reading (Q-G3) is not known to this run" ;;
  esac
  case "$F_QGR" in
    on:[0-9]*) F_QORG="${F_QGR#on:}"; F_QST=on ;;
    off) F_QST=off ;;
    other) F_QNR="read after the copy as neither in force nor off (Q-CA2 above says why)" ;;
    *) F_QNR="not read after the copy (Q-CA2 above says why)" ;;
  esac
  case "$F_QST" in
    on|off) if [ -z "$F_QSA" ]; then F_QDIFF="; $F_QSAW (Q-CA2 above)"
            elif [ "$F_QGA" != "$F_QGR" ]; then F_QDIFF="; stage A read it $F_QSA (Q-G3) — Q-CA2 above"; fi ;;
    *) case "$F_QGA" in on:[0-9]*) F_QORG="${F_QGA#on:}"; F_QST=stageA ;; esac ;;
  esac
  case "$F_QST" in
    on)     if [ -z "$F_QDIFF" ]; then F_QWHAT="#$F_QORG, as under $BASELINE_VERSION (Q-G3, Q-CA2)"
            else F_QIN=" after the copy (Q-CA2)$F_QDIFF"; F_QWHAT="#$F_QORG after the copy (Q-CA2)$F_QDIFF"; fi ;;
    off)    if [ -z "$F_QDIFF" ]; then F_QOFF="Q-G3: ucrm_quote_organization_id 0/off, the operator's choice"; F_QWHAT="none in force, as under $BASELINE_VERSION (Q-G3, Q-CA2)"
            else F_QOFF="Q-CA2: 0/off through the installed code after the copy$F_QDIFF"; F_QWHAT="none in force after the copy (Q-CA2)$F_QDIFF"; fi ;;
    stageA) F_QIN=" as stage A read it (Q-G3) — $F_QNR; the --after-only below reads it again"
            F_QWHAT="#$F_QORG as stage A read it (Q-G3), $F_QNR — not shown unchanged by this run" ;;
    *)      F_QWHAT="$F_QNR, and $( [ -n "$F_QSA" ] && echo "stage A read it $F_QSA (Q-G3)" || echo "$F_QSAW") — not shown unchanged by this run" ;;
  esac
  case "$F_QST" in
    on|stageA|unknown) F_QD9="" ;;   # 5.18.103 through 5.18.105: D9 (no Delivery PDF on Uganda) was 5.18.102's change; none changes it — 5.18.105's post_kyc.php and webhook.php hunks are LM's masked log lines only
  esac
  # 5.18.103 (docs/72 §G): said where the quoting organization is in force — as read after the copy, or as stage A read it
  # where nothing was read after it (above); with ucrm_quote_organization_id 0/off read after the copy the release quotes
  # as 5.18.102 does with it off (D7); otherwise NOT ESTABLISHED, and said so. The uCRM catalogue's switch as this run's
  # reading after the copy found it (qcsw: as an admin last left it on the uCRM catalogue screen; this script never sets
  # it) decides F_SWW; --accept-unpriced is said where it decided QL-G1 (this run's QLG1_NOTED, or
  # in an --after-only run the deploy's, from its state file). Counts and fixed words only.
  F_QLN="${QLG1_NOTED:-}"
  [ -n "$F_QLN" ] || [ "$MODE" != "after" ] || F_QLN="$(sed -n 's/^QLG1_NOTED=//p' "$STATE" 2>/dev/null | tail -n1)"
  F_SW103=""; F_P1=""
  case "${QO_KIND:-}:${QO_R:-}" in r:*" gets="*" other="*) F_SW103="$(kv "${QO_L:-}" qcsw)"; F_P1="$(kv "${QO_L:-}" qcwebp1)" ;; esac
  case "$F_SW103" in on) F_SWW="ON" ;; off|none) F_SWW="off" ;; *) F_SWW="not read after the copy (QC-CA1 above)" ;; esac
  case "$F_P1" in ''|*[!0-9]*) F_P1="not counted" ;; esac
  F_QLNS=""
  [ -z "$F_QLN" ] || F_QLNS=" The deploy went ahead on --accept-unpriced — the operator's explicit choice (QL-G1): with the switch off a kind of item uCRM offered nothing linkable for stays unpriced until uCRM is prepared and its items linked, as under $BASELINE_VERSION; with the switch on, links decide nothing."
  echo "  what changed      on this Uganda server: $EXPECTED_VERSION's log lines — 21 runtime files, 35 masked log lines (LM-CA1): no phone number in a log line any more, the webhook log's three phone fields as •••• and two digits, the report's BY NUMBER column padded by characters; no message, send, screen, setting or stored record changes, and no migration. The sales follow-up's ladder is $BASELINE_VERSION's and every key of it is as this run found it (LK-CA1): the steps that are on keep running ($(qf_kv "${LK_B1:-$LK_G1}" on | tr ',' ' '))"
  if [ "$MN_BEFORE|$OL_BEFORE|$FH_BEFORE|$HC_BEFORE" = "${MN_AFTER:-}|${OL_AFTER:-}|${FH_AFTER:-}|${HC_AFTER:-}" ]; then F_PILOT="as the operator left them, unchanged by this run"; else F_PILOT="CHANGED during this run, or not read"; fi
  echo "  the pilot         $MN_FLAG ${MN_AFTER#mn=}, $OL_KEY ${OL_AFTER#ol=}, $FH_KEY ${FH_AFTER#fh=}, $HC_KEY ${HC_AFTER#hc=} (files/store) — the salesperson pilot's switches, $F_PILOT (A5, A5b, V3f, V3h): the registry $(sw_both_on "$MN_AFTER" && echo "ON" || { sw_off "$MN_AFTER" && echo "OFF" || echo "with its two copies disagreeing"; }); 087's rows and trail, the registry, 5.18.89's rules, the routing and the automated-send policy as the code reads them, compared before and after (A8, R3, R11, R2b, R12, R2c)"
  echo "  the switches      $LC_KEY ${LC_AFTER#lc=}, $LS_KEY ${LS_AFTER#ls=}, $QU_KEY ${QU_AFTER#qu=}, $SA_KEY ${SA_AFTER#sa=}; install_auth_enabled ${IA_AFTER#ia=}, $WA_KEY ${WA_AFTER#wa=}; $BK_KEY ${BK_AFTER#bk=} — as the operator left them (V3b–V3e, V3j, R2)"
  echo "  what did not      the WhatsApp AI screen's Salesperson numbers card — its owner lists the salespeople and technicians exactly as $BASELINE_VERSION offers them (TN-G2, TN-CA2); the quoting organization — $F_QWHAT — the company every quote is made on, as 5.18.99 made it; the quotation summary's sign-off, $BASELINE_VERSION's line as text (QS-G1, QS-CA1; webhook.php changes only in LM's masked log lines); QuoteOrganization.php, QuoteTaxLine.php, TenantProfile.php, PublicPriceFeed.php, includes/api/api_retailer.php and retailer/index.html, $BASELINE_VERSION's byte for byte (Q-G1, Q-CA1) — cron_quote_wa.php and includes/post/post_kyc.php change only in LM's masked log lines$F_QD9; every number in the registry, its owner, its role and its switches (R11, TN-N1); wa_inbox_roles — read, never set (TN-G3, TN-CA3); every staff row, its role and is_admin — read on copies only; $F_SW (V3j); both ECO BANK cards show a figure (G3, BA2)$( [ -n "${V3J_WBB:-}" ] && echo " — or, with --without-bank-balance, said otherwise"); the Cashbook — its list, its tab \"Bank & other accounts\", both exports and cash in hand: D2 = A, read by both codes on the same copy and the same to the last digit in every currency and project (BK1, C1, A23, R23, BA2, CA2); the split itself and the tab's buttons $BASELINE_VERSION's (C3, CA2); every Balance, the counts, the pending disbursements and the P&L (C2, C4); the Cashbook's card, the landing page, the CEO page's tiles, the evening WhatsApp and tools/cash_in_hand.php as before; ECO Bank — every file of it, its two links, 088 and every statement kept, byte for byte and row for row (Q-G1, Q-CA1, BK3, BR2, BA1, BA2); the phone's More menu, byte for byte (BK3); 5.18.95's security fixes — the photo route, the repair page, the EFRIS links, the Splynx credentials — in the pin, the live code and the installed code alike (A22, A22L, R23a–R23g); the quarantine — the kept file and the stray store's old name, never opened, moved or written by this run: ${R19_SUM:-?} (A14, R19); the database — nothing written by this run and no migration added (R7, BA1); every key of the sales follow-up's ladder, in every place, as this run found it (LK-B1, LK-CA1); the Cashbook's tables (cb_ledger, cb_accounts) and the schema unchanged by every read of $EXPECTED_VERSION's code on the copies (C5, CA2); what a live plugin writes at use is the plugin's own (5.18.103's keys on Uganda applications — the uCRM catalogue's web-direct records, which 5.18.104 and 5.18.105 carry unchanged and add none to — among it: R7, QC-RB2); every figure of the book read on copies only, the live vault never written by a run on a copy (A23, R23, Q-G2, Q-CA2, Z1, Z2); 5.18.94's documents and every authorisation record (A17, R22, V13); the operator's three settings and the recordings' retention, read and said only (A18, A21); South Sudan (A6, A13, A17, A24, R13, R15, R17, R18, R22, R26, Q-CA2); Domain B (A7, R14); every switch and AI setting (V3–V3j), the sales follow-up's among them (LK-CA1); ucrm_quote_organization_id and every other key — read, never set (Q-G3, Q-CA6); every number's routing — the three departments' and any salesperson's (A9, R12); the assistant's prompt (A10, R16); the registry, 5.18.89's rules and the automated-send policy as the code judges them on this server's own configuration, the pilot as the operator left it (A11, R2b, R2c, R11); 087's rows and trail (A8, R3); cliDataDir() and getDataDir()'s rescue copy; uCRM: GETs only — no quote, no client, no product and no attribute created, changed or deleted (Q-G4, Q-CA3, QL-G1, QC-G1, QC-CA1); Evolution, WhatsApp, Splynx: nothing called or sent by this run — no number verified, switched or messaged"
  echo "  migrations        none added: 089, 090 and 091 as $BASELINE_VERSION left them (QF-G1, QF-CA1), the ledger the same before and after (R7)"
fi
echo
# The cash sheet: its path, its line count and the first 16 hex of its sha256, and the command to read it — never a
# figure, so this log and the terminal stay safe to send. `less` is a viewer, given no log of its own on purpose: a log
# of it would carry the sheet's figures.
echo "  cash sheet        $(sheet_say)"
if [ -n "$SHEET" ] && [ -f "$SHEET" ]; then
  echo "                    the figures of this run — the book before and after, the parts, P0's and the tool's output, the"
  echo "                    drift (CA3, by row id), the copy checks' and the notes' counts, ECO Bank's offered accounts (each"
  echo "                    one's row id and its last kept line's date), the quoting checks' counts and client ids (the"
  echo "                    move-list, Q-N2; the two clients Q-CA3 probed), the catalogue's items by name, each with its"
  echo "                    uCRM link and reason, which can carry a price (QL-G1, QL-N7), under \"uCRM items with the same"
  echo "                    spelling — a hint only\" the uCRM items spelled like each, by id, with whether each could be"
  echo "                    linked, the organization numbers uCRM gives its products, what the forms offer from uCRM in"
  echo "                    direct mode — each item with its uCRM ids, price and unit, or its reason (QC-G1, QC-CA1) — the"
  echo "                    uCRM catalogue's settings, the ids of the waiting web applications (QC-N4) and, after a"
  echo "                    rollback, of the web-direct ones with no quotation yet — a record only: 5.18.104, put back,"
  echo "                    handles each as before the deploy, through its own retry and its Orders card (QC-RB2) — and"
  echo "                    the lines of the physical count"
  echo "                    to fill in on paper. For you alone: read it on the"
  echo "                    server; never paste it, copy it or send it."
  echo "                    This log holds none of it. To read it:"
  echo "      less $SHEET"
fi
if [ "$MODE" != "rollback" ]; then
  echo
  echo "  check it          at least 20 minutes after the copy ($( [ -n "${R19_COPY_T:-}" ] && utc_of $(( R19_COPY_T + 1200 )) || echo "the copy's time is not recorded")) — R19 then says whether the quarantine still holds, conclusively once master has run the retry job after the copy — and once more the next day after 15:00 UTC, when the evening WhatsApp (18:00 Kampala) has run on the new code$( [ -n "$F_QORG" ] && echo " — the uCRM catalogue's switch is said as found (QC-ON1: ok while it is on, a note while it is off)"): each its own command, alone, with its own log and its own cash sheet:"
  echo "      $AFTER_CMD"
  echo
  echo "                    then the quarantine's own --check, its own command, alone:"
  echo "      $QCHECK_CMD"
  echo
  if [ "$MODE" = "after" ]; then
  echo "  the screens       as the steps now on make them — My quotations once list is on, WhatsApp offers once"
  echo "                    offers-test, the Inbox's voice transcript once voice-staff, the quotation chases once chase;"
  echo "                    on Uganda, whatever the steps, the WhatsApp AI screen's OpenAI key field, which says set or"
  echo "                    not set and never shows the key (VN-K2); every other screen as under $BASELINE_VERSION: the"
  echo "                    uCRM catalogue as it was, the Salesperson numbers card, the Cashbook and ECO Bank as before."
  echo "                    No screen of uCRM's changes. Do NOT make a test quote for a real customer: the plugin"
  echo "                    WhatsApps every new quote"
  else
  echo "  the screens       none changes: every switch of the sales follow-up is as this run found it (LK-CA1, QF-CA5), so"
  echo "                    every screen is as under $BASELINE_VERSION with the steps that are on. No screen of uCRM's"
  echo "                    changes. Do NOT make a test quote for a real customer: the plugin WhatsApps every new quote"
  fi
  echo
  echo "  your steps        yours alone, one at a time and only in the ladder's order (root docs/73 §H.2.3, C6) — this"
  echo "                    script does none of them, and kept every one as it found it. Step 12 (offers-live) only"
  echo "                    once $EXPECTED_VERSION serves and its --after-only (above) has PASSED (root docs/74 §A). Each"
  echo "                    step: on, then its check, each its own command, alone, its log in /root/dnb-sales; never"
  echo "                    while this script runs. Where the ladder stands, read-only:"
  echo "      cd $REPO && bash $QF_WRAPPER show"
  echo
  echo "                    The report, read-only on a copy of the book (P1; its wrapper pinned to $EXPECTED_VERSION), its own"
  echo "                    command, alone:"
  echo "      $QF_REPORT_CMD"
  echo
  echo "                    After each step, --after-only (check it, above): LK-AO, LM-ON, QF-ON0–QF-ON5, VA-ON1, VN-ON1–VN-ON4, OF-ON1,"
  echo "                    OF-ON2 and AC-ON1 judge each step that is on."
  echo "                    A step behaves under $EXPECTED_VERSION as under $BASELINE_VERSION; only its log lines carry no number."
else
  echo
  echo "  next              the quarantine's own --check, its own command, alone:"
  echo "      $QCHECK_CMD"
  echo
  echo "  deploy again      only once the cause of the rollback is understood — with --redeploy, its own command, alone:"
  echo "      $REDEPLOY_CMD"
fi
echo "  checks            $PASS ok, $FAIL failed, $NOTE notes"
if [ "$FAIL" = "0" ]; then echo; echo "  $EXPECTED_VERSION ($MODE): PASSED. Send this LOG FILE back (not a copy of the terminal, and never the cash sheet)."
else echo; echo "  $EXPECTED_VERSION ($MODE): $FAIL FAILED — send the log file (never the cash sheet); do not roll back on your own unless staff or customers are affected."; fi
# 5.18.98 — after a PASSED deploy or --after-only whose G3 went to its note under --without-bank-balance (this run's, or
# the deploy's recorded), ECO Bank's own read-only check, alone in its own block with its own log: whether both cards
# show a figure now. No switch command: the switch is the operator's, ON, and no mode of this script prints or runs
# one. Then the rollback, last, in its own block (root docs/74 §H.5): 5.18.104 put back by the documented deploy, every
# switch kept — no switch tool, no off-hook — then RB105; ECO Bank and its switch stay as they are. It needs no explicit
# choice: going back to 5.18.104 has no refusal of its own, and the ladder never blocks it. The by-hand path is the
# code's put-back alone (PUTBACK_CMD); it counts nothing, and says so.
if [ "$MODE" != "rollback" ] && [ "$FAIL" = "0" ] && [ -n "${V3J_WBB:-}" ]; then
  echo
  echo "  ECO Bank's own check, read-only, once a statement is kept on each card — its own command, alone: one line per"
  echo "  offered account and whether both ECO BANK cards show a figure (G3's question, asked of the installed code):"
  echo "      $CHECKBANK_CMD"
fi
if [ "$MODE" != "rollback" ]; then
  echo
  echo "  Only if it is ever needed — the rollback, never pasted together with any other command (root docs/44 §16.9)."
  echo "  $BASELINE_VERSION ($BASELINE_COMMIT) back — it asks you to type ROLLBACK before it changes anything. It"
  echo "  keeps every switch of the sales follow-up as it is — no switch tool, no off-hook: every step that is on keeps"
  echo "  running, open quote follow-ups and running offers carry on — and the lines $EXPECTED_VERSION masked write phone"
  echo "  numbers again. If step 12 is on, it says so in capitals before you type ROLLBACK and names your own"
  echo "  alternative; it never runs it. Then $BASELINE_VERSION is put back and checked (RB105, LM-RB1). The uCRM"
  echo "  catalogue stays as it is. Quotes already made in uCRM are not changed, and the $N_ADDED files $EXPECTED_VERSION"
  echo "  adds (its tests) stay on disk, reached by nothing. The summary's sign-off, the card's owner lists, every number"
  echo "  and its owner, the quoting organization, the Cashbook, cash in hand, ECO Bank, its switch, 088's tables and every"
  echo "  statement kept stay exactly as they are; 5.18.95's security fixes, 5.18.94's documents and every other switch"
  echo "  stay as they are. Then run the quarantine's own --check (A14 of any later deploy needs it)."
  echo "      $ROLLBACK_CMD"
  echo
  echo "  Only if that script cannot run — the same put-back of the code by hand, its own command, alone (never with the"
  echo "  one above; it counts nothing and runs no switch tool):"
  echo "      $PUTBACK_CMD"
fi
[ "$FAIL" = "0" ]
}

main "$@"; exit $?
